-- Alice's Library -- traduções em português (leitura bilíngue).
-- Gerado por scripts/build-traducoes-sql.mjs a partir de public/alices-library/livros/*.pt.json. Não edite à mão.
-- Rodar DEPOIS de livros.sql e livros_texto.sql (usa public.livros.texto_slug). Pode repetir: é um "upsert".
--
-- IMPORTANTE: o leitor do iPad lê as traduções dos arquivos livros/<slug>.pt.json que vão no app; rodar este SQL
-- NÃO é necessário para a leitura bilíngue funcionar. Ele guarda a mesma tradução no banco (consulta, backup,
-- revisão) e marca em public.livros quais livros têm tradução.

begin;

create table if not exists public.livros_traducoes (
  texto_slug text not null,
  idioma text not null default 'pt' check (idioma in ('pt')),
  cobertura text not null check (cobertura in ('trecho', 'parcial', 'completa')),
  credito text,
  titulos jsonb not null default '{}'::jsonb,
  paragrafos jsonb not null,
  total_paragrafos integer not null,
  atualizado_em timestamptz not null default now(),
  primary key (texto_slug, idioma)
);
comment on table public.livros_traducoes is 'Tradução parágrafo a parágrafo: paragrafos = { chave do parágrafo em inglês: texto em português }. A chave é keyOf() de public/alices-library/bilingual.js.';

alter table public.livros add column if not exists traducao_pt text check (traducao_pt in ('trecho', 'parcial', 'completa'));

revoke all on public.livros_traducoes from anon, authenticated;
grant select on public.livros_traducoes to anon, authenticated;
alter table public.livros_traducoes enable row level security;
drop policy if exists "traducoes are readable by everyone" on public.livros_traducoes;
create policy "traducoes are readable by everyone" on public.livros_traducoes for select to anon, authenticated using (true);

-- anna-sewell_black-beauty (10 parágrafos, excerpt)
insert into public.livros_traducoes (texto_slug, idioma, cobertura, credito, titulos, paragrafos, total_paragrafos) values ('anna-sewell_black-beauty', 'pt', 'trecho', 'Tradução para o português do Brasil feita por IA (Claude) para o Alice''s Library; trecho de abertura, revisão pendente.', $tr${"myearlyhome":"Meu primeiro lar"}$tr$::jsonb, $tr${"thefirstplacethaticanwellrememberwasalar~rookoverhungbyasteepbank":"O primeiro lugar de que consigo me lembrar bem era um grande e agradável pasto com um tanque de água limpa. Algumas árvores de boa sombra se debruçavam sobre ele, e juncos e ninfeias cresciam na parte funda. Do outro lado da cerca viva, de um lado, avistávamos um campo arado; do outro, por cima de um portão, a casa do nosso patrão, que ficava à beira da estrada. No alto do pasto havia um bosque de abetos, e embaixo um riacho corrente, sob a sombra de uma barranca íngreme.","whileiwasyoungiliveduponmymothersmilkasi~nicewarmshednearthegrove":"Enquanto eu era pequeno, vivia do leite de minha mãe, pois ainda não conseguia comer capim. De dia eu corria ao lado dela, e à noite me deitava bem junto a ela. Quando fazia calor, ficávamos junto ao tanque, à sombra das árvores, e quando fazia frio tínhamos um bom abrigo quente perto do bosque.","assoonasiwasoldenoughtoeatgrassmymotheru~eandcomebackintheevening":"Assim que tive idade para comer capim, minha mãe passou a sair para o trabalho durante o dia e a voltar à tardinha.","thereweresixyoungcoltsinthemeadowbesides~iteandkickaswellasgallop":"Havia no pasto, além de mim, seis potros; eram mais velhos do que eu, e alguns quase tão grandes quanto cavalos adultos. Eu corria com eles e me divertia muito; galopávamos todos juntos, voltas e mais voltas pelo campo, o mais depressa que podíamos. Às vezes a brincadeira era bastante rude, pois eles volta e meia mordiam e davam coices, além de galopar.","onedaywhentherewasagooddealofkickingmymo~ocometoherandthenshesaid":"Um dia, quando havia muito coice no ar, minha mãe relinchou para que eu fosse ter com ela, e então disse:","iwishyoutopayattentiontowhatiamgoingtosa~everbiteorkickeveninplay":"“Quero que você preste atenção ao que vou lhe dizer. Os potros que vivem aqui são muito bons potros, mas são potros de cavalo de carga e, naturalmente, não aprenderam boas maneiras. Você foi bem criado e nasceu de boa linhagem; seu pai tem grande nome por estas bandas, e seu avô ganhou a taça duas vezes nas corridas de Newmarket; sua avó tinha o gênio mais doce de todos os cavalos que conheci, e creio que você nunca me viu dar um coice ou uma mordida. Espero que cresça gentil e bom, e que nunca aprenda maus costumes; faça seu trabalho de boa vontade, levante bem as patas quando trotar, e nunca morda nem dê coices, nem mesmo de brincadeira.”","ihaveneverforgottenmymothersadviceiknews~ssbutheoftencalledherpet":"Nunca esqueci o conselho de minha mãe; eu sabia que ela era uma velha égua sensata, e o nosso patrão a tinha em alta conta. Chamava-se Duquesa, mas ele muitas vezes a chamava de Querida.","ourmasterwasagoodkindmanhegaveusgoodfood~nonamarketdayinalightgig":"O nosso patrão era um homem bom e gentil. Dava-nos boa comida, bom alojamento e palavras gentis; falava conosco com a mesma delicadeza com que falava com os filhinhos. Todos gostávamos dele, e minha mãe o amava muito. Quando o via no portão, relinchava de alegria e trotava até ele. Ele a afagava e acariciava e dizia: “Então, minha velha Querida, como vai o seu Escurinho?” Eu era de um preto fosco, por isso ele me chamava de Escurinho; depois me dava um pedaço de pão, que era uma delícia, e às vezes trazia uma cenoura para minha mãe. Todos os cavalos vinham ter com ele, mas acho que éramos os seus preferidos. Minha mãe sempre levava o patrão à cidade nos dias de feira, num cabriolé leve.","therewasaplowboydickwhosometimescameinto~sastonewouldhitandhurtus":"Havia um menino do arado, Dick, que às vezes entrava em nosso campo para colher amoras da cerca viva. Depois de comer quanto queria, fazia o que chamava de diversão com os potros, atirando pedras e paus para que galopassem. Não nos importávamos muito com ele, pois podíamos sair galopando; mas às vezes uma pedra nos acertava e machucava.","onedayhewasatthisgameanddidnotknowthatth~dupnearertoseewhatwenton":"Um dia ele estava nessa brincadeira e não sabia que o patrão estava no campo vizinho; mas ele estava ali, observando o que se passava; num pulo, transpôs a cerca viva e, agarrando Dick pelo braço, deu-lhe tamanho tapa no ouvido que o fez berrar de dor e de susto. Assim que vimos o patrão, trotamos mais para perto, para ver o que acontecia."}$tr$::jsonb, 10)
on conflict (texto_slug, idioma) do update set cobertura = excluded.cobertura, credito = excluded.credito, titulos = excluded.titulos, paragrafos = excluded.paragrafos, total_paragrafos = excluded.total_paragrafos, atualizado_em = now();

-- arthur-conan-doyle_a-study-in-scarlet (5 parágrafos, excerpt)
insert into public.livros_traducoes (texto_slug, idioma, cobertura, credito, titulos, paragrafos, total_paragrafos) values ('arthur-conan-doyle_a-study-in-scarlet', 'pt', 'trecho', 'Tradução para o português do Brasil feita por IA (Claude) para o Alice''s Library; trecho de abertura, revisão pendente.', $tr${"mrsherlockholmes":"O sr. Sherlock Holmes"}$tr$::jsonb, $tr${"intheyear1878itookmydegreeofdoctorofmedi~ceentereduponmynewduties":"No ano de 1878 recebi o grau de Doutor em Medicina pela Universidade de Londres e segui para Netley, a fim de fazer o curso prescrito para os cirurgiões do exército. Concluídos ali os estudos, fui devidamente designado Cirurgião Assistente do Quinto Regimento de Fuzileiros de Northumberland. O regimento estava então estacionado na Índia e, antes que eu pudesse juntar-me a ele, estourou a segunda guerra afegã. Ao desembarcar em Bombaim, soube que meu corpo de tropas havia avançado através dos desfiladeiros e já se achava bem dentro do território inimigo. Segui-o, contudo, com muitos outros oficiais que estavam na mesma situação que eu, e consegui chegar a salvo a Candahar, onde encontrei meu regimento e logo assumi as novas funções.","thecampaignbroughthonoursandpromotiontom~esafelytothebritishlines":"A campanha trouxe honrarias e promoções a muitos, mas para mim nada trouxe além de infortúnio e desastre. Fui retirado de minha brigada e destacado para os Berkshires, com os quais servi na fatídica batalha de Maiwand. Ali fui atingido no ombro por uma bala de Jezail, que me estilhaçou o osso e roçou a artéria subclávia. Teria caído nas mãos dos sanguinários Ghazis, não fosse a dedicação e a coragem de Murray, meu ordenança, que me atirou sobre um cavalo de carga e conseguiu levar-me são e salvo até as linhas britânicas.","wornwithpainandweakfromtheprolongedhards~sinattemptingtoimproveit":"Consumido pela dor e fraco pelos longos sofrimentos que suportara, fui removido, com um grande comboio de feridos, para o hospital da base em Peshawar. Ali me recuperei e já havia melhorado o bastante para andar pelas enfermarias, e até para tomar um pouco de sol na varanda, quando fui derrubado pela febre entérica, essa praga de nossas possessões indianas. Durante meses desesperaram de minha vida e, quando por fim voltei a mim e entrei em convalescença, estava tão fraco e emaciado que uma junta médica determinou que não se perdesse um só dia em me mandar de volta à Inglaterra. Fui, portanto, despachado no navio de transporte de tropas Orontes e desembarquei, um mês depois, no cais de Portsmouth, com a saúde irremediavelmente arruinada, mas com licença de um governo paternal para passar os nove meses seguintes tentando melhorá-la.","ihadneitherkithnorkininenglandandwasther~andlessexpensivedomicile":"Não tinha na Inglaterra parentes nem amigos e era, por isso, livre como o ar — ou tão livre quanto uma renda de onze xelins e seis pence por dia permite que um homem seja. Em tais circunstâncias, gravitei naturalmente para Londres, esse grande esgoto para onde são irresistivelmente drenados todos os ociosos e vadios do Império. Fiquei ali algum tempo num hotel particular na Strand, levando uma existência sem conforto e sem sentido, e gastando o dinheiro que tinha de modo bem mais liberal do que devia. O estado de minhas finanças tornou-se tão alarmante que logo percebi que precisava ou deixar a metrópole e ir me enterrar em algum recanto do campo, ou mudar por completo meu estilo de vida. Escolhendo a segunda alternativa, comecei por decidir deixar o hotel e instalar-me em alguma morada menos pretensiosa e menos dispendiosa.","ontheverydaythatihadcometothisconclusion~rtedofftogetherinahansom":"No mesmo dia em que cheguei a essa conclusão, eu estava de pé no bar do Criterion quando alguém me tocou o ombro e, voltando-me, reconheci o jovem Stamford, que fora meu auxiliar de curativos em Barts. A visão de um rosto amigo no grande ermo de Londres é coisa deveras agradável para um homem solitário. Nos velhos tempos, Stamford nunca fora um companheiro particularmente íntimo, mas agora o saudei com entusiasmo e ele, por sua vez, pareceu encantado em me ver. Na exuberância de minha alegria, convidei-o para almoçar comigo no Holborn, e partimos juntos num cabriolé."}$tr$::jsonb, 5)
on conflict (texto_slug, idioma) do update set cobertura = excluded.cobertura, credito = excluded.credito, titulos = excluded.titulos, paragrafos = excluded.paragrafos, total_paragrafos = excluded.total_paragrafos, atualizado_em = now();

-- arthur-conan-doyle_the-adventures-of-sherlock-holmes (5 parágrafos, excerpt)
insert into public.livros_traducoes (texto_slug, idioma, cobertura, credito, titulos, paragrafos, total_paragrafos) values ('arthur-conan-doyle_the-adventures-of-sherlock-holmes', 'pt', 'trecho', 'Tradução para o português do Brasil feita por IA (Claude) para o Alice''s Library; trecho de abertura, revisão pendente.', $tr${"ascandalinbohemia":"Um escândalo na Boêmia"}$tr$::jsonb, $tr${"i~i":"I","tosherlockholmessheisalwaysthewomanihave~ousandquestionablememory":"Para Sherlock Holmes, ela é sempre a mulher. Raramente o ouvi mencioná-la por outro nome. Aos olhos dele, ela eclipsa e supera todo o seu sexo. Não que ele sentisse por Irene Adler qualquer emoção semelhante ao amor. Todas as emoções, e essa em particular, eram abomináveis para a sua mente fria, precisa, mas admiravelmente equilibrada. Era, creio eu, a mais perfeita máquina de raciocinar e observar que o mundo já viu, mas, como amante, ele se teria colocado numa posição falsa. Jamais falava das paixões mais ternas, a não ser com um gracejo e um sorriso de escárnio. Eram coisas admiráveis para o observador, excelentes para erguer o véu dos motivos e das ações dos homens. Mas, para o raciocinador treinado, admitir tais intrusões em seu temperamento delicado e finamente ajustado era introduzir um fator perturbador, que poderia lançar dúvida sobre todos os seus resultados mentais. Um grão de areia num instrumento sensível, ou uma rachadura numa de suas lentes de alta potência, não seria mais perturbador do que uma emoção forte numa natureza como a dele. E, no entanto, só havia uma mulher para ele, e essa mulher era a falecida Irene Adler, de memória duvidosa e questionável.","ihadseenlittleofholmeslatelymymarriageha~formerfriendandcompanion":"Eu vira pouco de Holmes nos últimos tempos. O casamento nos afastara um do outro. Minha completa felicidade e os interesses domésticos que surgem em torno do homem que pela primeira vez se vê senhor de sua própria casa bastavam para absorver toda a minha atenção, enquanto Holmes, que detestava toda forma de vida em sociedade com toda a sua alma boêmia, permanecia em nossos aposentos da Baker Street, enterrado entre seus velhos livros, alternando de semana em semana entre a cocaína e a ambição, entre a sonolência da droga e a energia feroz de sua natureza aguda. Continuava, como sempre, profundamente atraído pelo estudo do crime, e empregava suas imensas faculdades e extraordinários poderes de observação em seguir pistas e esclarecer mistérios que a polícia oficial abandonara por desesperançados. De tempos em tempos chegava-me algum vago relato de suas atividades: de sua convocação a Odessa no caso do assassinato Trepoff, do esclarecimento da singular tragédia dos irmãos Atkinson em Trincomalee e, por fim, da missão que cumprira de modo tão delicado e bem-sucedido em favor da família reinante da Holanda. Além desses sinais de sua atividade, porém, que eu apenas partilhava com todos os leitores da imprensa diária, eu sabia pouco do meu antigo amigo e companheiro.","onenightitwasonthetwentiethofmarch1888iw~dformerlybeeninpartmyown":"Certa noite — era o dia vinte de março de 1888 — eu voltava de uma visita a um paciente (pois havia retomado a clínica civil) quando o caminho me levou pela Baker Street. Ao passar pela porta bem lembrada, que sempre há de estar associada em minha mente ao meu namoro e aos sombrios incidentes do Estudo em Vermelho, fui tomado por um vivo desejo de rever Holmes e saber em que empregava seus extraordinários poderes. Seus aposentos estavam brilhantemente iluminados e, mesmo enquanto eu olhava para cima, vi sua figura alta e magra passar duas vezes, em silhueta escura, contra a cortina. Ele andava de um lado para o outro, rápido, ansioso, com a cabeça afundada no peito e as mãos cruzadas às costas. Para mim, que conhecia todos os seus humores e hábitos, a atitude e o jeito dele contavam sua própria história. Estava de novo trabalhando. Erguera-se de seus sonhos provocados pela droga e seguia, ardente, o rastro de algum novo problema. Toquei a campainha e fui conduzido ao cômodo que outrora fora em parte meu.","hismannerwasnoteffusiveitseldomwasbuthew~ularintrospectivefashion":"Seu modo não foi efusivo. Raramente era; mas ele ficou contente, penso eu, em me ver. Quase sem dizer palavra, mas com um olhar bondoso, fez-me sinal para uma poltrona, atirou-me sua caixa de charutos e indicou um porta-licores e um gasogênio no canto. Depois ficou de pé diante do fogo e me examinou à sua singular maneira introspectiva."}$tr$::jsonb, 5)
on conflict (texto_slug, idioma) do update set cobertura = excluded.cobertura, credito = excluded.credito, titulos = excluded.titulos, paragrafos = excluded.paragrafos, total_paragrafos = excluded.total_paragrafos, atualizado_em = now();

-- arthur-conan-doyle_the-hound-of-the-baskervilles (17 parágrafos, excerpt)
insert into public.livros_traducoes (texto_slug, idioma, cobertura, credito, titulos, paragrafos, total_paragrafos) values ('arthur-conan-doyle_the-hound-of-the-baskervilles', 'pt', 'trecho', 'Tradução para o português do Brasil feita por IA (Claude) para o Alice''s Library; trecho de abertura, revisão pendente.', $tr${"mrsherlockholmes":"O Sr. Sherlock Holmes"}$tr$::jsonb, $tr${"mrsherlockholmeswhowasusuallyverylateint~nifiedsolidandreassuring":"O Sr. Sherlock Holmes, que costumava levantar-se muito tarde, exceto nas ocasiões nada raras em que passava a noite inteira em claro, estava sentado à mesa do desjejum. Eu, de pé diante da lareira, apanhei a bengala que nosso visitante deixara para trás na noite anterior. Era uma bela peça de madeira grossa, de cabo bulboso, do tipo conhecido como “Penang lawyer”. Logo abaixo do cabo havia uma larga faixa de prata, de quase uma polegada. “A James Mortimer, M.R.C.S., de seus amigos do C.C.H.”, estava gravado nela, com a data “1884”. Era exatamente o tipo de bengala que o velho médico de família costumava carregar: digna, sólida e tranquilizadora.","wellwatsonwhatdoyoumakeofit~lwatsonwhatdoyoumakeofit":"— Pois bem, Watson, o que o senhor deduz dela?","holmeswassittingwithhisbacktomeandihadgi~nhimnosignofmyoccupation":"Holmes estava sentado de costas para mim, e eu não lhe dera nenhum sinal da minha ocupação.","howdidyouknowwhatiwasdoingibelieveyouhav~eeyesinthebackofyourhead":"— Como soube o que eu estava fazendo? Creio que o senhor tem olhos na nuca.","ihaveatleastawellpolishedsilverplatedcof~hemanbyanexaminationofit":"— Tenho, pelo menos, uma cafeteira de prata bem polida bem à minha frente — disse ele. — Mas diga-me, Watson, o que deduz da bengala do nosso visitante? Já que tivemos o azar de não encontrá-lo e não fazemos ideia do que o trazia aqui, esta lembrança acidental ganha importância. Deixe-me ouvi-lo reconstruir o homem pelo exame dela.","ithinksaidifollowingasfarasicouldthemeth~smarkoftheirappreciation":"— Penso — disse eu, seguindo o mais fielmente que pude o método de meu companheiro — que o Dr. Mortimer é um médico bem-sucedido, de certa idade, e estimado, já que aqueles que o conhecem lhe dão esta prova de apreço.","goodsaidholmesexcellent~goodsaidholmesexcellent":"— Bom! — disse Holmes. — Excelente!","ithinkalsothattheprobabilityisinfavourof~tdealofhisvisitingonfoot":"— Penso também que é provável que seja um médico do campo, que faz grande parte de suas visitas a pé.","whyso~whyso":"— Por quê?","becausethisstickthoughoriginallyaveryhan~eatamountofwalkingwithit":"— Porque esta bengala, embora originalmente muito bonita, está tão maltratada que mal posso imaginar um médico da cidade carregando-a. A grossa ponteira de ferro está gasta, de modo que é evidente que ele caminhou muitíssimo com ela.","perfectlysoundsaidholmes~perfectlysoundsaidholmes":"— Perfeitamente correto! — disse Holmes.","andthenagainthereisthefriendsofthecchish~mallpresentationinreturn":"— E há ainda os “amigos do C.C.H.”. Suponho que seja o Clube de Caça de Tal Lugar, a caça local, a cujos membros ele talvez tenha prestado algum auxílio cirúrgico, e que lhe fez em troca um pequeno presente.","reallywatsonyouexcelyourselfsaidholmespu~hatiamverymuchinyourdebt":"— Realmente, Watson, o senhor se supera — disse Holmes, empurrando a cadeira para trás e acendendo um cigarro. — Sou obrigado a dizer que, em todos os relatos que o senhor teve a bondade de fazer de minhas modestas realizações, habitualmente subestimou suas próprias capacidades. Pode ser que o senhor mesmo não seja luminoso, mas é um condutor de luz. Algumas pessoas, sem possuir o gênio, têm um poder notável de estimulá-lo. Confesso, meu caro amigo, que estou em grande dívida com o senhor.","hehadneversaidasmuchbeforeandimustadmitt~eritagainwithaconvexlens":"Ele nunca dissera tanto antes, e devo admitir que suas palavras me deram um prazer intenso, pois eu muitas vezes me ressentira da indiferença dele diante de minha admiração e das tentativas que eu fizera de dar publicidade a seus métodos. Eu também me orgulhava de pensar que dominara seu sistema a ponto de aplicá-lo de um modo que lhe merecia a aprovação. Ele tomou então a bengala de minhas mãos e a examinou por alguns minutos a olho nu. Depois, com uma expressão de interesse, pousou o cigarro e, levando a bengala até a janela, voltou a examiná-la com uma lente convexa.","interestingthoughelementarysaidheasheret~asisforseveraldeductions":"— Interessante, ainda que elementar — disse ele, ao voltar para o seu canto favorito do sofá. — Há certamente um ou dois indícios na bengala. Ela nos dá base para várias deduções.","hasanythingescapedmeiaskedwithsomeselfim~encewhichihaveoverlooked":"— Algo me escapou? — perguntei, com certa presunção. — Espero que não haja nada de importante que eu tenha deixado passar.","iamafraidmydearwatsonthatmostofyourconcl~ionerandhewalksagooddeal":"— Receio, meu caro Watson, que a maior parte de suas conclusões era errônea. Quando disse que o senhor me estimulava, queria dizer, para ser franco, que, ao notar as suas falácias, eu era por vezes conduzido à verdade. Não que o senhor esteja inteiramente equivocado neste caso. O homem é certamente um médico do campo. E caminha bastante."}$tr$::jsonb, 17)
on conflict (texto_slug, idioma) do update set cobertura = excluded.cobertura, credito = excluded.credito, titulos = excluded.titulos, paragrafos = excluded.paragrafos, total_paragrafos = excluded.total_paragrafos, atualizado_em = now();

-- charles-dickens_a-christmas-carol (8 parágrafos, excerpt)
insert into public.livros_traducoes (texto_slug, idioma, cobertura, credito, titulos, paragrafos, total_paragrafos) values ('charles-dickens_a-christmas-carol', 'pt', 'trecho', 'Tradução para o português do Brasil feita por IA (Claude) para o Alice''s Library; trecho de abertura, revisão pendente.', $tr${"marleysghost":"O fantasma de Marley"}$tr$::jsonb, $tr${"marleywasdeadtobeginwiththereisnodoubtwh~rleywasasdeadasadoornail":"Marley estava morto, para começar. Quanto a isso não havia a menor dúvida. O registro de seu enterro fora assinado pelo clérigo, pelo sacristão, pelo agente funerário e pelo principal enlutado. Scrooge o assinara. E o nome de Scrooge valia ouro na Bolsa para qualquer coisa em que ele resolvesse pôr a mão. O velho Marley estava morto como um prego de porta.","mindidontmeantosaythatiknowofmyownknowle~rleywasasdeadasadoornail":"Atenção! Não pretendo dizer que sei, por conhecimento próprio, o que há de particularmente morto num prego de porta. Eu mesmo seria levado a considerar o prego de caixão como a peça de ferragem mais morta de todo o comércio. Mas a sabedoria de nossos antepassados está na comparação, e minhas mãos profanas não hão de perturbá-la, ou o país está perdido. Permitam-me, portanto, repetir com ênfase que Marley estava morto como um prego de porta.","scroogeknewhewasdeadofcoursehedidhowcoul~itwithanundoubtedbargain":"Scrooge sabia que ele estava morto? Claro que sabia. Como poderia ser de outro modo? Scrooge e ele foram sócios por não sei quantos anos. Scrooge era seu único testamenteiro, seu único administrador, seu único cessionário, seu único legatário universal, seu único amigo e único enlutado. E mesmo Scrooge não ficou tão terrivelmente abalado com o triste acontecimento que deixasse de ser excelente homem de negócios no próprio dia do funeral, que solenizou com uma pechincha indiscutível.","thementionofmarleysfuneralbringsmebackto~oastonishhissonsweakmind":"A menção ao funeral de Marley me traz de volta ao ponto de onde parti. Não há dúvida de que Marley estava morto. Isso deve ficar bem entendido, ou nada de maravilhoso poderá resultar da história que vou contar. Se não estivéssemos perfeitamente convencidos de que o pai de Hamlet morreu antes de a peça começar, não haveria nada de mais notável em vê-lo passear à noite, com vento leste, sobre as próprias muralhas, do que em qualquer outro cavalheiro de meia-idade que se aventurasse imprudentemente depois de escurecer num lugar ventoso — o adro da Catedral de São Paulo, por exemplo — literalmente para assombrar o espírito fraco do filho.","scroogeneverpaintedoutoldmarleysnamether~amesitwasallthesametohim":"Scrooge nunca apagou o nome do velho Marley. Lá continuou, anos depois, sobre a porta do armazém: Scrooge & Marley. A firma era conhecida como Scrooge & Marley. Às vezes as pessoas novas no ramo chamavam Scrooge de Scrooge, e às vezes de Marley, mas ele respondia a ambos os nomes. Para ele dava no mesmo.","ohbuthewasatightfistedhandatthegrindston~awitonedegreeatchristmas":"Ah! mas que mão-de-vaca na pedra de amolar, esse Scrooge! Um velho pecador que espremia, arrancava, agarrava, raspava, tomava e cobiçava! Duro e afiado como sílex, do qual aço nenhum jamais tirara fogo generoso; fechado, contido e solitário como uma ostra. O frio que trazia dentro de si congelava-lhe as velhas feições, beliscava-lhe o nariz pontudo, enrugava-lhe a face, endurecia-lhe o andar; deixava-lhe os olhos vermelhos, os lábios finos azulados; e falava com astúcia em sua voz áspera. Uma geada cobria-lhe a cabeça, as sobrancelhas e o queixo hirsuto. Levava sempre consigo a própria baixa temperatura; gelava o escritório nos dias de canícula e não o descongelava um grau sequer no Natal.","externalheatandcoldhadlittleinfluenceons~somelyandscroogeneverdid":"O calor e o frio de fora pouco influíam sobre Scrooge. Nenhum calor podia aquecê-lo, nenhum tempo invernal o enregelava. Nenhum vento que soprasse era mais amargo do que ele, nenhuma neve que caísse mais obstinada em seu propósito, nenhuma chuva torrencial menos aberta a súplicas. O mau tempo não sabia por onde pegá-lo. A mais pesada chuva, a neve, o granizo e a geada miúda só podiam gabar-se de uma vantagem sobre ele. Muitas vezes “desciam” com generosidade, e Scrooge nunca.","nobodyeverstoppedhiminthestreettosaywith~rthananevileyedarkmaster":"Ninguém jamais o parou na rua para dizer, com ar jovial: “Meu caro Scrooge, como vai? Quando virá me visitar?” Nenhum mendigo lhe implorava um trocado, nenhuma criança lhe perguntava que horas eram, nenhum homem ou mulher jamais, em toda a sua vida, indagou de Scrooge o caminho para este ou aquele lugar. Até os cães dos cegos pareciam conhecê-lo; e, quando o viam aproximar-se, puxavam os donos para dentro de portas e vielas; e depois abanavam o rabo como se dissessem: “Nenhum olho é melhor do que um olho mau, sinistro patrão!”"}$tr$::jsonb, 8)
on conflict (texto_slug, idioma) do update set cobertura = excluded.cobertura, credito = excluded.credito, titulos = excluded.titulos, paragrafos = excluded.paragrafos, total_paragrafos = excluded.total_paragrafos, atualizado_em = now();

-- charles-dickens_hard-times (4 parágrafos, excerpt)
insert into public.livros_traducoes (texto_slug, idioma, cobertura, credito, titulos, paragrafos, total_paragrafos) values ('charles-dickens_hard-times', 'pt', 'trecho', 'Tradução para o português do Brasil feita por IA (Claude) para o Alice''s Library; trecho de abertura, revisão pendente.', $tr${"theonethingneedful":"A única coisa necessária"}$tr$::jsonb, $tr${"nowwhatiwantisfactsteachtheseboysandgirl~echildrensticktofactssir":"“Pois bem, o que eu quero são Fatos. Não ensinem a estes meninos e meninas nada além de Fatos. Só os Fatos são necessários na vida. Não plantem mais nada, e arranquem tudo o mais. Só é possível formar a mente de animais racionais com Fatos: nenhuma outra coisa jamais lhes será de serventia. Este é o princípio segundo o qual crio os meus próprios filhos, e é o princípio segundo o qual crio estas crianças. Atenha-se aos Fatos, senhor!”","thescenewasaplainbaremonotonousvaultofas~twasallhelpedtheemphasis":"A cena era uma sala de aula simples, nua e monótona como uma abóbada, e o indicador quadrado do orador sublinhava cada frase com um traço na manga do mestre-escola, reforçando suas observações. A ênfase era ajudada pela testa quadrada do orador, uma muralha que tinha as sobrancelhas por base, enquanto seus olhos encontravam um porão espaçoso em duas cavernas escuras, à sombra da muralha. A ênfase era ajudada pela boca do orador, que era larga, fina e firmemente cerrada. A ênfase era ajudada pela voz do orador, que era inflexível, seca e ditatorial. A ênfase era ajudada pelo cabelo do orador, que se eriçava nas bordas da cabeça calva, uma plantação de abetos para proteger do vento a superfície reluzente, toda coberta de calombos, como a crosta de uma torta de ameixa, como se a cabeça mal tivesse espaço de armazém para os duros fatos guardados lá dentro. O porte obstinado do orador, o casaco quadrado, as pernas quadradas, os ombros quadrados — e até mesmo o lenço de pescoço, treinado para agarrá-lo pela garganta com um aperto intransigente, como um fato teimoso que era — tudo ajudava a ênfase.","inthislifewewantnothingbutfactssirnothin~tfactssirnothingbutfacts":"“Nesta vida, não queremos senão Fatos, senhor; nada senão Fatos!”","thespeakerandtheschoolmasterandthethirdg~tiltheywerefulltothebrim":"O orador, o mestre-escola e a terceira pessoa adulta presente recuaram um pouco, e percorreram com o olhar o plano inclinado de pequenos vasilhames ali dispostos em ordem, prontos para receber galões imperiais de fatos até transbordarem."}$tr$::jsonb, 4)
on conflict (texto_slug, idioma) do update set cobertura = excluded.cobertura, credito = excluded.credito, titulos = excluded.titulos, paragrafos = excluded.paragrafos, total_paragrafos = excluded.total_paragrafos, atualizado_em = now();

-- emily-bronte_wuthering-heights (12 parágrafos, excerpt)
insert into public.livros_traducoes (texto_slug, idioma, cobertura, credito, titulos, paragrafos, total_paragrafos) values ('emily-bronte_wuthering-heights', 'pt', 'trecho', 'Tradução para o português do Brasil feita por IA (Claude) para o Alice''s Library; trecho de abertura, revisão pendente.', $tr${"chapteri":"Capítulo I"}$tr$::jsonb, $tr${"1801ihavejustreturnedfromavisittomylandl~stcoatasiannouncedmyname":"1801.— Acabo de voltar de uma visita ao meu senhorio — o único vizinho que terei para me importunar. Este é certamente um belo país! Em toda a Inglaterra, não creio que eu pudesse ter escolhido um lugar tão completamente afastado do bulício da sociedade. Um paraíso perfeito para o misantropo: e o Sr. Heathcliff e eu formamos um par tão apropriado para repartir entre nós a desolação. Um excelente sujeito! Mal imaginava ele como meu coração se aqueceu por ele quando vi seus olhos negros recuarem tão desconfiados sob as sobrancelhas, enquanto eu me aproximava a cavalo, e quando seus dedos se abrigaram, com ciumenta resolução, ainda mais fundo no colete, ao eu anunciar meu nome.","mrheathcliffisaid~mrheathcliffisaid":"— Sr. Heathcliff? — disse eu.","anodwastheanswer~anodwastheanswer":"Um aceno de cabeça foi a resposta.","mrlockwoodyournewtenantsiridomyselftheho~dayyouhadhadsomethoughts":"— Sr. Lockwood, o seu novo inquilino, senhor. Faço-me a honra de visitá-lo logo depois da minha chegada, para exprimir a esperança de não o ter incomodado com minha insistência em solicitar a ocupação de Thrushcross Grange: ouvi ontem que o senhor havia pensado em...","thrushcrossgrangeismyownsirheinterrupted~meificouldhinderitwalkin":"— Thrushcross Grange é minha, senhor — interrompeu ele, estremecendo. — Não permitiria que ninguém me incomodasse, se pudesse evitá-lo. Entre!","thewalkinwasutteredwithclosedteethandexp~atedlyreservedthanmyself":"O “entre” foi proferido entre dentes cerrados, e exprimia o sentimento “Vá para o diabo”; nem mesmo o portão em que ele se apoiava manifestou qualquer movimento de simpatia pelas palavras; e creio que essa circunstância me decidiu a aceitar o convite: senti interesse por um homem que parecia ainda mais exageradamente reservado do que eu.","whenhesawmyhorsesbreastfairlypushingtheb~shorseandbringupsomewine":"Quando viu o peito do meu cavalo empurrando a cancela, estendeu enfim a mão para soltar a corrente, e depois me precedeu, taciturno, pela calçada, gritando ao entrarmos no pátio: — Joseph, leve o cavalo do Sr. Lockwood; e traga vinho.","herewehavethewholeestablishmentofdomesti~learetheonlyhedgecutters":"— Aí temos, suponho, todo o corpo de criados da casa — foi a reflexão sugerida por essa ordem composta. — Não admira que o capim cresça entre as lajes, e que o gado seja o único podador de sebes.","josephwasanelderlynayanoldmanveryoldperh~encetomyunexpectedadvent":"Joseph era um homem idoso, ou melhor, um velho: muito velho, talvez, embora rijo e nervoso. — O Senhor nos ajude! — resmungou ele num tom baixo de enfado rabugento, enquanto me tomava o cavalo, e olhava-me o rosto tão azedamente que conjecturei, caridoso, que ele devia precisar de auxílio divino para digerir o jantar, e que sua pia exclamação nada tinha a ver com o meu inesperado advento.","wutheringheightsisthenameofmrheathcliffs~edwithlargejuttingstones":"Wuthering Heights é o nome da residência do Sr. Heathcliff. “Wuthering” é um adjetivo provincial expressivo, que descreve o tumulto atmosférico a que sua situação está exposta em tempo de tempestade. Ventilação pura e tonificante devem ter ali em cima a todas as horas, de fato: pode-se adivinhar a força do vento norte soprando por sobre a borda pela inclinação excessiva de uns poucos abetos raquíticos no fim da casa, e por uma fileira de espinheiros descarnados, todos estendendo os galhos para o mesmo lado, como que implorando esmola ao sol. Felizmente, o arquiteto teve a previdência de construí-la sólida: as janelas estreitas são fundas na parede, e os cantos são defendidos por grandes pedras salientes.","beforepassingthethresholdipausedtoadmire~inspectingthepenetralium":"Antes de transpor o limiar, parei para admirar uma quantidade de entalhes grotescos prodigalizados pela fachada, e especialmente em torno da porta principal; sobre ela, entre uma selva de grifos em ruínas e meninos despudorados, descobri a data “1500” e o nome “Hareton Earnshaw”. Teria feito alguns comentários e pedido ao rabugento dono uma breve história do lugar; mas sua atitude à porta parecia exigir minha pronta entrada ou minha retirada completa, e eu não tinha desejo de agravar-lhe a impaciência antes de inspecionar o santuário interior.","onestopbroughtusintothefamilysittingroom~dogshauntedotherrecesses":"Um passo nos levou à sala de estar da família, sem qualquer vestíbulo ou corredor de entrada: chamam-na aqui “a casa” por excelência. Em geral inclui cozinha e salão; mas creio que em Wuthering Heights a cozinha foi obrigada a retirar-se de todo para outra parte: pelo menos distingui um vozerio e um tinir de utensílios culinários, lá no fundo; e não observei sinal de assar, ferver ou cozer junto à enorme lareira, nem qualquer brilho de panelas de cobre e escorredores de lata nas paredes. Uma das extremidades, de fato, refletia esplendidamente luz e calor de fileiras de imensos pratos de estanho, entremeados de jarras e canecas de prata, que se erguiam, fileira após fileira, num vasto aparador de carvalho, até o próprio teto. Este nunca fora forrado: toda a sua anatomia ficava exposta a um olhar curioso, exceto onde um engradado de madeira carregado de bolos de aveia e de cachos de pernis de boi, de carneiro e de presunto o escondia. Sobre a chaminé havia diversas velhas espingardas de aspecto sinistro e um par de pistolas de arção; e, a título de ornamento, três latas espalhafatosamente pintadas dispostas ao longo da cornija. O chão era de pedra lisa e branca; as cadeiras, rústicas estruturas de espaldar alto, pintadas de verde; uma ou duas pesadas, pretas, espreitavam na sombra. Num arco sob o aparador repousava uma enorme cadela perdigueira cor de fígado, cercada por um enxame de cachorrinhos guinchantes; e outros cães habitavam outros recantos."}$tr$::jsonb, 12)
on conflict (texto_slug, idioma) do update set cobertura = excluded.cobertura, credito = excluded.credito, titulos = excluded.titulos, paragrafos = excluded.paragrafos, total_paragrafos = excluded.total_paragrafos, atualizado_em = now();

-- f-scott-fitzgerald_the-great-gatsby (6 parágrafos, excerpt)
insert into public.livros_traducoes (texto_slug, idioma, cobertura, credito, titulos, paragrafos, total_paragrafos) values ('f-scott-fitzgerald_the-great-gatsby', 'pt', 'trecho', 'Tradução para o português do Brasil feita por IA (Claude) para o Alice''s Library; trecho de abertura, revisão pendente.', $tr${"chapteri":"Capítulo I"}$tr$::jsonb, $tr${"inmyyoungerandmorevulnerableyearsmyfathe~ingoverinmymindeversince":"Nos meus anos mais jovens e mais vulneráveis, meu pai me deu um conselho que desde então venho remoendo na cabeça.","wheneveryoufeellikecriticizinganyoneheto~headvantagesthatyouvehad":"“Sempre que você tiver vontade de criticar alguém”, disse-me ele, “lembre-se de que nem todos neste mundo tiveram as vantagens que você teve.”","hedidntsayanymorebutwevealwaysbeenunusua~elledoutunequallyatbirth":"Não disse mais nada, mas sempre fomos extraordinariamente comunicativos à nossa maneira reservada, e entendi que ele queria dizer muito mais do que aquilo. Em consequência, tendo a reservar todos os julgamentos, hábito que me abriu muitas naturezas curiosas e também fez de mim vítima de não poucos chatos veteranos. A mente anormal é rápida em detectar essa qualidade e a ela se apegar quando surge numa pessoa normal, e assim aconteceu que na faculdade fui injustamente acusado de político, porque eu era o confidente das mágoas secretas de homens desvairados e desconhecidos. A maior parte das confidências não foi solicitada — com frequência fingi sono, preocupação ou uma jocosidade hostil ao perceber, por algum sinal inequívoco, que uma revelação íntima tremeluzia no horizonte; pois as revelações íntimas dos rapazes, ou ao menos os termos em que as expressam, costumam ser plagiárias e deturpadas por supressões óbvias. Reservar o julgamento é uma questão de infinita esperança. Ainda hoje tenho um pouco de medo de perder alguma coisa se me esquecer de que, como meu pai sugeriu com esnobismo, e eu esnobemente repito, o senso das decências fundamentais é distribuído de modo desigual ao nascer.","andafterboastingthiswayofmytoleranceicom~shortwindedelationsofmen":"E, depois de me gabar assim da minha tolerância, chego à confissão de que ela tem um limite. A conduta pode estar fundada na rocha dura ou nos pântanos úmidos, mas a partir de certo ponto não me importa em que esteja fundada. Quando voltei do Leste, no outono passado, senti que queria o mundo de uniforme e numa espécie de sentido moral para sempre; não queria mais excursões desabridas com vislumbres privilegiados do coração humano. Só Gatsby, o homem que dá nome a este livro, ficou isento dessa minha reação — Gatsby, que representava tudo aquilo por que tenho um desprezo sincero. Se a personalidade é uma série ininterrupta de gestos bem-sucedidos, então havia algo de magnífico nele, uma sensibilidade aguçada às promessas da vida, como se estivesse ligado a uma dessas máquinas intrincadas que registram terremotos a dez mil milhas de distância. Essa receptividade nada tinha que ver com a flácida impressionabilidade que se dignifica com o nome de “temperamento criativo” — era um dom extraordinário para a esperança, uma prontidão romântica como nunca encontrei em nenhuma outra pessoa e como provavelmente nunca mais encontrarei. Não — Gatsby saiu-se bem no fim; foi o que se alimentou de Gatsby, a poeira imunda que flutuou na esteira de seus sonhos, que fechou temporariamente meu interesse pelas tristezas abortivas e pelas exultações de fôlego curto dos homens.","myfamilyhavebeenprominentwelltodopeoplei~atmyfathercarriesontoday":"Minha família é gente de posição e de bens nesta cidade do Meio-Oeste há três gerações. Os Carraway são uma espécie de clã, e temos a tradição de que descendemos dos duques de Buccleuch, mas o verdadeiro fundador da nossa linhagem foi o irmão de meu avô, que veio para cá em cinquenta e um, mandou um substituto para a Guerra Civil e fundou o negócio atacadista de ferragens que meu pai dirige até hoje.","ineversawthisgreatunclebutimsupposedtolo~htinthespringoftwentytwo":"Nunca vi esse tio-avô, mas supõe-se que eu me pareça com ele — em especial com o retrato bastante durão que está pendurado no escritório de meu pai. Formei-me em New Haven em 1915, exatamente um quarto de século depois de meu pai, e pouco depois participei daquela migração teutônica tardia conhecida como a Grande Guerra. Gostei tanto do contra-ataque que voltei inquieto. Em vez de ser o centro caloroso do mundo, o Meio-Oeste agora me parecia a borda esfarrapada do universo — por isso resolvi ir para o Leste aprender o negócio de títulos. Todo mundo que eu conhecia estava no negócio de títulos, de modo que supus que ele poderia sustentar mais um homem solteiro. Todos os meus tios e tias discutiram o assunto como se estivessem escolhendo um colégio preparatório para mim e por fim disseram: “Bem… sim”, com rostos muito graves e hesitantes. Meu pai concordou em me financiar por um ano e, depois de vários adiamentos, vim para o Leste, em definitivo, pensei, na primavera de vinte e dois."}$tr$::jsonb, 6)
on conflict (texto_slug, idioma) do update set cobertura = excluded.cobertura, credito = excluded.credito, titulos = excluded.titulos, paragrafos = excluded.paragrafos, total_paragrafos = excluded.total_paragrafos, atualizado_em = now();

-- frances-hodgson-burnett_a-little-princess (11 parágrafos, excerpt)
insert into public.livros_traducoes (texto_slug, idioma, cobertura, credito, titulos, paragrafos, total_paragrafos) values ('frances-hodgson-burnett_a-little-princess', 'pt', 'trecho', 'Tradução para o português do Brasil feita por IA (Claude) para o Alice''s Library; trecho de abertura, revisão pendente.', $tr${"sara":"Sara"}$tr$::jsonb, $tr${"onceonadarkwintersdaywhentheyellowfoghun~roughthebigthoroughfares":"Num escuro dia de inverno, quando a névoa amarela pairava tão espessa e pesada nas ruas de Londres que os lampiões estavam acesos e as vitrines das lojas ardiam à luz de gás como à noite, uma menininha de aspecto estranho viajava num coche com o pai, conduzida bem devagar pelas grandes avenidas.","shesatwithherfeettuckedunderherandleaned~oughtfulnessinherbigeyes":"Ela estava sentada com os pés encolhidos sob o corpo, recostada no pai, que a segurava num dos braços, e olhava pela janela as pessoas que passavam, com uma curiosa seriedade de gente antiga nos olhos grandes.","shewassuchalittlegirlthatonedidnotexpect~shehadlivedalonglongtime":"Era uma menina tão pequena que ninguém esperaria ver aquele olhar em seu rostinho. Teria sido um olhar velho para uma criança de doze anos, e Sara Crewe tinha apenas sete. O fato, porém, é que ela vivia sonhando e pensando coisas estranhas, e não se lembrava de nenhuma época em que não tivesse estado a pensar nas pessoas grandes e no mundo a que elas pertenciam. Sentia-se como se tivesse vivido muito, muito tempo.","atthismomentshewasrememberingthevoyagesh~dlaughatthethingsshesaid":"Naquele momento ela se lembrava da viagem que acabara de fazer de Bombaim com o pai, o capitão Crewe. Pensava no grande navio, nos lascares que passavam em silêncio de um lado para o outro, nas crianças que brincavam no convés quente e em algumas jovens esposas de oficiais que tentavam fazê-la conversar com elas e rir das coisas que dizia.","principallyshewasthinkingofwhataqueerthi~hemovedclosertoherfather":"Pensava, principalmente, em como era esquisito que num momento a gente estivesse na Índia, sob o sol escaldante, depois no meio do oceano, e depois num veículo estranho, por ruas estranhas, onde o dia era tão escuro quanto a noite. Achou isso tão intrigante que se aconchegou mais ao pai.","papashesaidinalowmysteriouslittlevoicewh~ichwasalmostawhisperpapa":"— Papai — disse ela, numa vozinha baixa e misteriosa, quase um sussurro —, papai.","whatisitdarlingcaptaincreweansweredholdi~facewhatissarathinkingof":"— O que é, querida? — respondeu o capitão Crewe, abraçando-a mais forte e olhando para o seu rosto. — Em que está pensando a Sara?","isthistheplacesarawhisperedcuddlingstill~stillclosertohimisitpapa":"— É este o lugar? — sussurrou Sara, aninhando-se ainda mais nele. — É, papai?","yeslittlesaraitiswehavereacheditatlastan~hathefeltsadwhenhesaidit":"— Sim, pequena Sara, é. Finalmente chegamos. — E, embora tivesse apenas sete anos, ela percebeu que ele estava triste ao dizer isso.","itseemedtohermanyyearssincehehadbeguntop~everwasallsheknewaboutit":"Parecia-lhe que fazia muitos anos que ele começara a preparar seu espírito para “o lugar”, como ela sempre o chamava. A mãe morrera quando ela nasceu, de modo que nunca a conhecera nem sentira sua falta. O pai, jovem, bonito, rico e mimador, parecia ser o único parente que tinha no mundo. Sempre tinham brincado juntos e se querido muito. Ela só sabia que ele era rico porque ouvira as pessoas dizerem isso quando pensavam que não estava escutando, e também as ouvira dizer que, quando crescesse, ela seria rica também. Não sabia tudo o que significava ser rico. Sempre morara num belo bangalô e se habituara a ver muitos criados que lhe faziam salamaleques, chamavam-na de “Missee Sahib” e lhe faziam todas as vontades. Tivera brinquedos, bichinhos e uma aia que a adorava, e aos poucos aprendera que as pessoas ricas tinham essas coisas. Contudo, era tudo o que sabia a respeito.","duringhershortlifeonlyonethinghadtrouble~hathecouldnotstaywithher":"Em sua curta vida, uma só coisa a perturbara, e essa coisa era “o lugar” para onde um dia seria levada. O clima da Índia era muito ruim para as crianças, e, assim que possível, elas eram mandadas embora — geralmente para a Inglaterra e para a escola. Vira outras crianças partirem e ouvira os pais e as mães delas falarem das cartas que recebiam. Sabia que também seria obrigada a ir e, embora às vezes as histórias do pai sobre a viagem e o novo país a atraíssem, atormentava-a a ideia de que ele não poderia ficar com ela."}$tr$::jsonb, 11)
on conflict (texto_slug, idioma) do update set cobertura = excluded.cobertura, credito = excluded.credito, titulos = excluded.titulos, paragrafos = excluded.paragrafos, total_paragrafos = excluded.total_paragrafos, atualizado_em = now();

-- frances-hodgson-burnett_the-secret-garden (7 parágrafos, excerpt)
insert into public.livros_traducoes (texto_slug, idioma, cobertura, credito, titulos, paragrafos, total_paragrafos) values ('frances-hodgson-burnett_the-secret-garden', 'pt', 'trecho', 'Tradução para o português do Brasil feita por IA (Claude) para o Alice''s Library; trecho de abertura, revisão pendente.', $tr${"thereisnooneleft":"Não resta ninguém"}$tr$::jsonb, $tr${"whenmarylennoxwassenttomisselthwaitemano~velearnedherlettersatall":"Quando Mary Lennox foi mandada para a Mansão Misselthwaite, para viver com o tio, todos disseram que era a criança de aspecto mais desagradável que já se vira. E era verdade. Tinha um rostinho magro e um corpinho magro, cabelos ralos e claros e uma expressão azeda. Seus cabelos eram amarelos, e seu rosto era amarelo porque ela nascera na Índia e vivera sempre doente de um jeito ou de outro. O pai ocupara um cargo no Governo inglês e estava sempre ocupado e doente também, e a mãe fora uma grande beldade, que só se interessava por festas e por divertir-se com gente alegre. Não queria uma menina de modo algum, e, quando Mary nasceu, entregou-a aos cuidados de uma aia, a quem fez entender que, se quisesse agradar à Mem Sahib, devia manter a criança longe das vistas o mais possível. Assim, quando era um bebê doentio, rabugento e feio, foi mantida longe, e, quando se tornou uma criaturinha doentia e rabugenta que começava a andar, também foi mantida longe. Nunca se lembrava de ter visto de perto nada além do rosto escuro da aia e dos outros criados nativos, e, como eles sempre a obedeciam e lhe faziam todas as vontades, porque a Mem Sahib ficaria zangada se fosse incomodada pelo choro dela, aos seis anos Mary era uma porquinha tão tirana e egoísta quanto jamais existiu. A jovem governanta inglesa que veio ensiná-la a ler e a escrever antipatizou tanto com ela que deixou o emprego em três meses, e, quando outras governantas vieram tentar ocupar o lugar, foram embora sempre em menos tempo que a primeira. De modo que, se Mary não tivesse resolvido que realmente queria aprender a ler livros, nunca teria aprendido as letras.","onefrightfullyhotmorningwhenshewasaboutn~yherbedsidewasnotherayah":"Numa manhã terrivelmente quente, quando tinha cerca de nove anos, ela acordou muito zangada, e ficou ainda mais zangada ao ver que a criada de pé junto à sua cama não era a sua aia.","whydidyoucomeshesaidtothestrangewomaniwi~letyoustaysendmyayahtome":"— Por que você veio? — disse à mulher estranha. — Não vou deixar você ficar. Mande minha aia vir aqui.","thewomanlookedfrightenedbutsheonlystamme~eayahtocometomissiesahib":"A mulher pareceu assustada, mas apenas gaguejou que a aia não podia vir e, quando Mary teve um acesso de fúria e bateu e chutou nela, só pareceu ainda mais assustada e repetiu que não era possível a aia vir até a Missie Sahib.","therewassomethingmysteriousintheairthatm~allsaidiewhenshereturned":"Havia algo de misterioso no ar naquela manhã. Nada era feito na ordem de costume, e vários dos criados nativos pareciam ter sumido, enquanto aqueles que Mary via esgueiravam-se ou apressavam-se com rostos cinzentos e assustados. Mas ninguém lhe dizia nada, e a aia não veio. Ela foi de fato deixada sozinha à medida que a manhã avançava e, por fim, saiu vagando pelo jardim e começou a brincar sozinha sob uma árvore perto da varanda. Fingiu que estava fazendo um canteiro e espetou grandes flores de hibisco escarlates em montinhos de terra, cada vez mais zangada, resmungando consigo mesma as coisas que diria e os nomes que chamaria Saidie quando ela voltasse.","pigpigdaughterofpigsshesaidbecausetocall~pigistheworstinsultofall":"— Porca! Porca! Filha de porcas! — dizia, porque chamar um nativo de porco é o pior insulto de todos.","shewasgrindingherteethandsayingthisovera~tothefairboyofficersface":"Rangia os dentes e repetia isso sem parar quando ouviu a mãe sair para a varanda com alguém. Estava com um rapaz louro, e os dois ficaram conversando em vozes baixas e estranhas. Mary conhecia o rapaz louro que parecia um menino. Ouvira dizer que era um oficial muito jovem, recém-chegado da Inglaterra. A criança o fitou, mas fitou ainda mais a mãe. Sempre fazia isso quando tinha oportunidade de vê-la, porque a Mem Sahib — Mary a chamava assim com mais frequência do que de qualquer outro modo — era uma pessoa tão alta, esguia e bonita e usava roupas tão lindas. Os cabelos dela eram como seda encaracolada, o narizinho delicado parecia desdenhar das coisas, e os olhos eram grandes e risonhos. Todas as suas roupas eram leves e esvoaçantes, e Mary dizia que eram “cheias de renda”. Pareciam mais cheias de renda do que nunca naquela manhã, mas os olhos dela não estavam nada risonhos. Estavam grandes e assustados, e erguidos em súplica para o rosto do oficial menino."}$tr$::jsonb, 7)
on conflict (texto_slug, idioma) do update set cobertura = excluded.cobertura, credito = excluded.credito, titulos = excluded.titulos, paragrafos = excluded.paragrafos, total_paragrafos = excluded.total_paragrafos, atualizado_em = now();

-- frederick-douglass_narrative-of-the-life-of-frederick-douglass (4 parágrafos, excerpt)
insert into public.livros_traducoes (texto_slug, idioma, cobertura, credito, titulos, paragrafos, total_paragrafos) values ('frederick-douglass_narrative-of-the-life-of-frederick-douglass', 'pt', 'trecho', 'Tradução para o português do Brasil feita por IA (Claude) para o Alice''s Library; trecho de abertura, revisão pendente.', $tr${"chapteri":"Capítulo I"}$tr$::jsonb, $tr${"iwasbornintuckahoenearhillsboroughandabo~asaboutseventeenyearsold":"Nasci em Tuckahoe, perto de Hillsborough, a cerca de doze milhas de Easton, no condado de Talbot, em Maryland. Não tenho conhecimento exato de minha idade, pois nunca vi nenhum registro autêntico que a contivesse. A grande maioria dos escravos sabe tão pouco de sua idade quanto os cavalos da deles, e é desejo da maior parte dos senhores que conheço manter seus escravos assim na ignorância. Não me lembro de ter conhecido um só escravo capaz de dizer o dia do próprio nascimento. Raramente chegam mais perto do que a época do plantio, a da colheita, a das cerejas, a primavera ou o outono. A falta de informação sobre a minha foi, mesmo na infância, motivo de infelicidade para mim. As crianças brancas sabiam dizer a sua idade. Eu não conseguia entender por que devia ser privado do mesmo privilégio. Não me era permitido fazer qualquer pergunta a meu senhor a esse respeito. Ele considerava todas essas perguntas, da parte de um escravo, impróprias e impertinentes, e sinal de um espírito inquieto. A estimativa mais aproximada que posso dar me coloca agora entre vinte e sete e vinte e oito anos de idade. Chego a isso por ter ouvido meu senhor dizer, em algum momento de 1835, que eu tinha cerca de dezessete anos.","mymotherwasnamedharrietbaileyshewastheda~grandmotherorgrandfather":"Minha mãe chamava-se Harriet Bailey. Era filha de Isaac e Betsey Bailey, ambos de cor, e bastante escuros. Minha mãe tinha a pele mais escura do que a de minha avó ou a de meu avô.","myfatherwasawhitemanhewasadmittedtobesuc~hisistheinevitableresult":"Meu pai era um homem branco. Assim o admitiam todos os que ouvi falar de minha ascendência. Murmurava-se também a opinião de que meu senhor era meu pai; mas da exatidão dessa opinião nada sei; os meios de sabê-lo me foram negados. Minha mãe e eu fomos separados quando eu era apenas um bebê, antes que eu a conhecesse como mãe. É costume comum, na parte de Maryland de onde fugi, separar as crianças das mães desde muito cedo. Com frequência, antes que a criança complete doze meses, a mãe lhe é tirada e alugada a alguma fazenda a considerável distância, e a criança é posta aos cuidados de uma velha, idosa demais para o trabalho no campo. Para que se faz essa separação, não sei, a não ser para impedir o desenvolvimento do afeto da criança pela mãe e para embotar e destruir o afeto natural da mãe pelo filho. Este é o resultado inevitável.","ineversawmymothertoknowherassuchmorethan~eltatthedeathofastranger":"Nunca vi minha mãe, de modo a conhecê-la como tal, mais de quatro ou cinco vezes em minha vida; e cada uma dessas vezes foi muito breve, e à noite. Ela fora alugada a um certo Sr. Stewart, que morava a cerca de doze milhas de minha casa. Fazia suas viagens para me ver durante a noite, percorrendo todo o caminho a pé, depois de cumprida a labuta do dia. Era trabalhadora do campo, e o açoite é a pena por não estar na lavoura ao nascer do sol, a menos que o escravo tenha licença especial do senhor em contrário — licença que raramente obtêm, e que dá a quem a concede o orgulhoso nome de senhor bondoso. Não me lembro de jamais ter visto minha mãe à luz do dia. Ela estava comigo à noite. Deitava-se ao meu lado e me fazia dormir, mas muito antes de eu acordar já havia partido. Muito pouca comunicação houve entre nós. A morte logo pôs fim ao pouco que poderíamos ter enquanto ela viveu, e com isso a seus sofrimentos e penas. Morreu quando eu tinha cerca de sete anos, numa das fazendas de meu senhor, perto de Lee’s Mill. Não me permitiram estar presente durante sua doença, sua morte ou seu enterro. Ela já se fora muito antes de eu saber de qualquer coisa. Por nunca ter desfrutado, em grau considerável, de sua presença consoladora, de seu cuidado terno e vigilante, recebi a notícia de sua morte com emoções muito semelhantes às que provavelmente teria sentido pela morte de uma estranha."}$tr$::jsonb, 4)
on conflict (texto_slug, idioma) do update set cobertura = excluded.cobertura, credito = excluded.credito, titulos = excluded.titulos, paragrafos = excluded.paragrafos, total_paragrafos = excluded.total_paragrafos, atualizado_em = now();

-- g-k-chesterton_the-everlasting-man (3 parágrafos, excerpt)
insert into public.livros_traducoes (texto_slug, idioma, cobertura, credito, titulos, paragrafos, total_paragrafos) values ('g-k-chesterton_the-everlasting-man', 'pt', 'trecho', 'Tradução para o português do Brasil feita por IA (Claude) para o Alice''s Library; trecho de abertura, revisão pendente.', $tr${"themaninthecave":"O homem da caverna"}$tr$::jsonb, $tr${"farawayinsomestrangeconstellationinskies~nsomemorefamiliarfashion":"Longe daqui, em alguma estranha constelação, em céus infinitamente remotos, há uma pequena estrela que os astrônomos talvez descubram um dia. Ao menos nunca pude observar, no rosto ou nas maneiras da maioria dos astrônomos ou homens de ciência, qualquer sinal de que a tivessem descoberto, embora na verdade estejam caminhando sobre ela o tempo todo. É uma estrela que faz brotar de si mesma plantas muito estranhas e animais muito estranhos, e nenhum mais estranho que os homens de ciência. Seria assim, ao menos, que eu começaria uma história do mundo, se tivesse de seguir o costume científico de começar por um relato do universo astronômico. Tentaria ver até esta Terra de fora, não pela insistência banal em sua posição relativa ao sol, mas por algum esforço de imaginação para conceber sua posição remota aos olhos de um espectador desumanizado. Só que não acredito em desumanizar-se para estudar a humanidade. Não acredito em me deter nas distâncias que supostamente apequenam o mundo; acho que há algo até um tanto vulgar nessa ideia de repreender o espírito pelo tamanho. E como a primeira ideia não é viável — a de fazer da Terra um planeta estranho para torná-la significativa —, não me rebaixarei ao outro artifício, o de fazer dela um planeta pequeno para torná-la insignificante. Prefiro insistir que nem sequer sabemos que ela é um planeta, no sentido em que sabemos que é um lugar; e um lugar muito extraordinário, aliás. Essa é a nota que desejo dar desde o início, se não à maneira astronômica, então de algum modo mais familiar.","oneofmyfirstjournalisticadventuresormisa~leandhewasratherabusyman":"Uma de minhas primeiras aventuras, ou desventuras, jornalísticas disse respeito a um comentário sobre Grant Allen, que havia escrito um livro sobre a Evolução da Ideia de Deus. Aconteceu-me observar que seria muito mais interessante se Deus escrevesse um livro sobre a evolução da ideia de Grant Allen. E lembro que o editor objetou à minha observação por considerá-la blasfema, o que naturalmente me divertiu não pouco. Pois a graça da coisa, é claro, era que ele nunca reparou no título do próprio livro, que esse sim era blasfemo; pois significava, traduzido para o inglês, “Vou lhes mostrar como cresceu entre os homens esta noção absurda de que existe um Deus”. Minha observação era estritamente piedosa e correta, pois reconhecia o propósito divino até em suas manifestações mais aparentemente obscuras ou sem sentido. Naquela hora aprendi muitas coisas, entre elas que há algo puramente acústico em boa parte dessa espécie agnóstica de reverência. O editor não percebera o ponto porque, no título do livro, a palavra longa vinha no começo e a curta no fim; ao passo que, no meu comentário, a palavra curta vinha no começo e lhe deu uma espécie de choque. Tenho notado que, se você põe uma palavra como Deus na mesma frase que uma palavra como cão, essas palavras abruptas e angulosas atingem as pessoas como tiros de pistola. Dizer que Deus fez o cão ou que o cão fez Deus parece não importar; isso é só uma das disputas estéreis dos teólogos sutis demais. Mas, desde que se comece com uma palavra longa como evolução, o resto passará inofensivamente; muito provavelmente o editor não havia lido o título inteiro, pois é um título bastante longo e ele era um homem bastante ocupado.","butthislittleincidenthasalwayslingeredin~vereadtheoriginofspecies":"Mas esse pequeno incidente sempre ficou em minha mente como uma espécie de parábola. A maioria das histórias modernas da humanidade começa com a palavra evolução, e com uma exposição bastante prolixa da evolução, pelo mesmo motivo que agiu neste caso. Há algo de lento, suave e gradual na palavra e até na ideia. Na verdade, no que toca a essas coisas primordiais, não é uma palavra muito prática nem uma ideia muito proveitosa. Ninguém consegue imaginar como o nada poderia se tornar algo. Ninguém se aproxima um centímetro disso explicando como algo poderia se tornar outra coisa. É muitíssimo mais lógico começar dizendo “No princípio Deus criou os céus e a terra”, ainda que se queira dizer apenas “No princípio algum poder inconcebível iniciou algum processo inconcebível”. Pois Deus é, por natureza, um nome de mistério, e ninguém jamais supôs que o homem pudesse imaginar como um mundo foi criado, assim como não poderia criar um. Mas a evolução é de fato tomada por explicação. Tem a qualidade fatal de deixar em muitas mentes a impressão de que entendem isso e todo o resto; assim como muitas delas vivem sob uma espécie de ilusão de haverem lido A origem das espécies."}$tr$::jsonb, 3)
on conflict (texto_slug, idioma) do update set cobertura = excluded.cobertura, credito = excluded.credito, titulos = excluded.titulos, paragrafos = excluded.paragrafos, total_paragrafos = excluded.total_paragrafos, atualizado_em = now();

-- george-bernard-shaw_pygmalion (28 parágrafos, excerpt)
insert into public.livros_traducoes (texto_slug, idioma, cobertura, credito, titulos, paragrafos, total_paragrafos) values ('george-bernard-shaw_pygmalion', 'pt', 'trecho', 'Tradução para o português do Brasil feita por IA (Claude) para o Alice''s Library; trecho de abertura, revisão pendente.', $tr${"acti":"Ato I"}$tr$::jsonb, $tr${"coventgardenat1115pmtorrentsofheavysumme~inwhichheiswritingbusily":"Covent Garden, às 11h15 da noite. Torrentes de forte chuva de verão. Apitos de cocheiros soam freneticamente em todas as direções. Pedestres correm para se abrigar no mercado e sob o pórtico da Igreja de São Paulo, onde já há várias pessoas, entre elas uma senhora e sua filha em traje de noite. Todos espiam a chuva com ar sombrio, exceto um homem de costas para os demais, que parece inteiramente absorvido por um caderno em que escreve febrilmente.","thechurchclockstrikesthefirstquarter~ckstrikesthefirstquarter":"O relógio da igreja bate o primeiro quarto.","thedaughterinthespacebetweenthecentralpi~hesbeengonetwentyminutes":"A Filha — No espaço entre as colunas centrais, junto à que fica à sua esquerda. Estou gelada até os ossos. O que será que Freddy está fazendo todo esse tempo? Saiu há vinte minutos.","themotheronherdaughtersrightnotsolongbut~ghttohavegotusacabbythis":"A Mãe — À direita da filha. Não tanto assim. Mas já devia ter nos arranjado um carro.","abystanderontheladysrighthewontgetnocabn~roppingtheirtheatrefares":"Um Passante — À direita da senhora. Ele não vai achar carro nenhum, não, antes das onze e meia, madame, quando eles voltam depois de deixar o pessoal do teatro.","themotherbutwemusthaveacabwecantstandher~lhalfpastelevenitstoobad":"A Mãe — Mas nós precisamos de um carro. Não podemos ficar aqui até as onze e meia. É demais.","abystanderwellitaintmyfaultmissus~rwellitaintmyfaultmissus":"Um Passante — Bem, a culpa não é minha, madame.","thedaughteriffreddyhadabitofgumptionhewo~vegotoneatthetheatredoor":"A Filha — Se Freddy tivesse um pingo de juízo, teria arranjado um na porta do teatro.","themotherwhatcouldhehavedonepoorboy~atcouldhehavedonepoorboy":"A Mãe — O que ele podia ter feito, pobre rapaz?","thedaughterotherpeoplegotcabswhycouldnth~eoplegotcabswhycouldnthe":"A Filha — Outras pessoas arranjaram carros. Por que ele não podia?","freddyrushesinoutoftherainfromthesoutham~ssverywetaroundtheankles":"Freddy entra correndo, fugindo da chuva, pelo lado da Southampton Street, e se coloca entre as duas, fechando um guarda-chuva pingando. É um rapaz de vinte anos, em traje de noite, muito molhado até os tornozelos.","thedaughterwellhaventyougotacab~hterwellhaventyougotacab":"A Filha — Então, não conseguiu um carro?","freddytheresnotonetobehadforloveormoney~onetobehadforloveormoney":"Freddy — Não há nenhum a preço nenhum, nem por amor nem por dinheiro.","themotherohfreddytheremustbeoneyoucantha~ustbeoneyoucanthavetried":"A Mãe — Ora, Freddy, tem de haver um. Você não deve ter procurado.","thedaughteritstootiresomedoyouexpectusto~ustogoandgetoneourselves":"A Filha — Que coisa mais cansativa. Você espera que a gente mesma vá buscar um?","freddyitellyoutheyreallengagedtherainwas~herandtheywereallengaged":"Freddy — Estou dizendo que estão todos ocupados. A chuva veio tão de repente: ninguém estava preparado; e todo mundo teve de pegar um carro. Fui até Charing Cross para um lado e quase até Ludgate Circus para o outro; e estavam todos ocupados.","themotherdidyoutrytrafalgarsquare~didyoutrytrafalgarsquare":"A Mãe — Você tentou em Trafalgar Square?","freddytherewasntoneattrafalgarsquare~asntoneattrafalgarsquare":"Freddy — Não havia nenhum em Trafalgar Square.","thedaughterdidyoutry~thedaughterdidyoutry":"A Filha — Você tentou?","freddyitriedasfarascharingcrossstationdi~ectmetowalktohammersmith":"Freddy — Tentei até a estação de Charing Cross. Esperava que eu fosse a pé até Hammersmith?","thedaughteryouhaventtriedatall~ghteryouhaventtriedatall":"A Filha — Você não tentou coisa nenhuma.","themotheryoureallyareveryhelplessfreddyg~ackuntilyouhavefoundacab":"A Mãe — Você é realmente muito desajeitado, Freddy. Vá de novo; e não volte enquanto não achar um carro.","freddyishallsimplygetsoakedfornothing~implygetsoakedfornothing":"Freddy — Vou simplesmente me encharcar à toa.","thedaughterandwhataboutusarewetostayhere~tonothingonyouselfishpig":"A Filha — E nós? Vamos ficar aqui a noite toda neste vento, quase sem nada no corpo? Seu egoísta...","freddyohverywellillgoillgoheopenshisumbr~rorchestratestheincident":"Freddy — Ah, está bem: eu vou, eu vou. Abre o guarda-chuva e sai correndo em direção ao Strand, mas esbarra numa florista que se apressava para se abrigar, e lhe derruba o cesto das mãos. Um clarão ofuscante de relâmpago, seguido imediatamente por um estrondo de trovão, orquestra o incidente.","theflowergirlnahthenfreddylookwhygowinde~enfreddylookwhygowindeah":"A Florista — Ora, Freddy: olha por onde anda, querido.","freddysorryherushesoff~freddysorryherushesoff":"Freddy — Desculpe. Sai correndo.","theflowergirlpickingupherscatteredflower~edstheservicesofadentist":"A Florista — Apanhando as flores espalhadas e recolocando-as no cesto. Que modos são esses! Dois maços de violetas pisados na lama. Senta-se no pedestal da coluna, separando as flores, à direita da senhora. Não é de modo algum uma pessoa atraente. Tem talvez dezoito anos, talvez vinte, dificilmente mais. Usa um chapeuzinho de marinheiro, de palha preta, que há muito está exposto à poeira e à fuligem de Londres e raramente, se é que alguma vez, foi escovado. Seu cabelo precisa seriamente de uma lavagem: a cor de rato dificilmente pode ser natural. Usa um casaco preto de má qualidade, que chega quase aos joelhos e é ajustado na cintura. Tem uma saia marrom com um avental grosseiro. Suas botas estão muito gastas. Sem dúvida é tão limpa quanto suas posses permitem; mas, comparada às damas, é muito suja. Seus traços não são piores que os delas; mas o estado deles deixa a desejar; e ela precisa dos serviços de um dentista."}$tr$::jsonb, 28)
on conflict (texto_slug, idioma) do update set cobertura = excluded.cobertura, credito = excluded.credito, titulos = excluded.titulos, paragrafos = excluded.paragrafos, total_paragrafos = excluded.total_paragrafos, atualizado_em = now();

-- george-bernard-shaw_saint-joan (28 parágrafos, excerpt)
insert into public.livros_traducoes (texto_slug, idioma, cobertura, credito, titulos, paragrafos, total_paragrafos) values ('george-bernard-shaw_saint-joan', 'pt', 'trecho', 'Tradução para o português do Brasil feita por IA (Claude) para o Alice''s Library; trecho de abertura, revisão pendente.', $tr${"scenei":"Cena I"}$tr$::jsonb, $tr${"afinespringmorningontherivermeusebetween~inthecastleofvaucouleurs":"Uma bela manhã de primavera às margens do rio Meuse, entre a Lorena e a Champanhe, no ano de 1429 d.C., no castelo de Vaucouleurs.","captainrobertdebaudricourtamilitarysquir~becausehehasneverbloomed":"O capitão Robert de Baudricourt, escudeiro militar, bonito e fisicamente enérgico, mas sem vontade própria, disfarça esse defeito à sua maneira habitual, vociferando terrivelmente contra seu mordomo, um verme pisoteado, de poucas carnes e poucos cabelos, que podia ter qualquer idade entre 18 e 55 anos, sendo o tipo de homem que a idade não consegue murchar porque jamais chegou a florescer.","thetwoareinasunnystonechamberonthefirstf~oodenchestunderthewindow":"Os dois estão numa clara sala de pedra no primeiro andar do castelo. A uma mesa de carvalho simples e robusta, sentado numa cadeira que combina com ela, o capitão apresenta o perfil esquerdo. O mordomo está de pé diante dele, do outro lado da mesa, se é que uma postura tão submissa como a sua pode ser chamada de estar de pé. A janela com mainéis, do século XIII, está aberta atrás dele. Perto dela, no canto, há uma torrinha com uma estreita porta em arco que dá para uma escada em caracol, a qual desce até o pátio. Há um banco robusto de quatro pés sob a mesa e uma arca de madeira sob a janela.","robertnoeggsnoeggsthousandthundersmanwha~manwhatdoyoumeanbynoeggs":"Robert — Sem ovos! Sem ovos!! Mil trovões, homem, que quer dizer com sem ovos?","stewardsiritisnotmyfaultitistheactofgod~otmyfaultitistheactofgod":"Mordomo — Senhor: não é culpa minha. É obra de Deus.","robertblasphemyyoutellmetherearenoeggsan~ndyoublameyourmakerforit":"Robert — Blasfêmia. Você me diz que não há ovos e culpa o seu Criador por isso.","stewardsirwhatcanidoicannotlayeggs~whatcanidoicannotlayeggs":"Mordomo — Senhor: que posso eu fazer? Não posso pôr ovos.","robertsarcastichayoujestaboutit~arcastichayoujestaboutit":"Robert — Sarcástico. Ah! Você zomba disso.","stewardnosirgodknowsweallhavetogowithout~havesirthehenswillnotlay":"Mordomo — Não, senhor, Deus sabe que não. Todos nós temos de ficar sem ovos, assim como o senhor. As galinhas não botam.","robertindeedrisingnowlistentomeyou~edrisingnowlistentomeyou":"Robert — Ora essa! Levantando-se. Agora ouça-me bem, você.","stewardhumblyyessir~stewardhumblyyessir":"Mordomo — Humildemente. Sim, senhor.","robertwhatami~robertwhatami":"Robert — O que sou eu?","stewardwhatareyousir~stewardwhatareyousir":"Mordomo — O que o senhor é, senhor?","robertcomingathimyeswhatamiamirobertsqui~fvaucouleursoramiacowboy":"Robert — Avançando sobre ele. Sim: o que sou eu? Sou Robert, escudeiro de Baudricourt e capitão deste castelo de Vaucouleurs: ou sou um vaqueiro?","stewardohsiryouknowyouareagreatermanhere~anherethanthekinghimself":"Mordomo — Oh, senhor, o senhor sabe que é aqui um homem maior do que o próprio rei.","robertpreciselyandnowdoyouknowwhatyouare~ndnowdoyouknowwhatyouare":"Robert — Precisamente. E agora, sabe o que você é?","stewardiamnobodysirexceptthatihavethehon~ethehonortobeyoursteward":"Mordomo — Não sou ninguém, senhor, a não ser que tenho a honra de ser o seu mordomo.","robertdrivinghimtothewalladjectivebyadje~ehestridesbacktothetable":"Robert — Encurralando-o, adjetivo por adjetivo. Você não tem apenas a honra de ser meu mordomo, mas o privilégio de ser o pior, mais incompetente, babão, choramingas, tagarela, balbuciante idiota de mordomo de toda a França. Volta a passos largos para a mesa.","stewardcoweringonthechestyessirtoagreatm~likeyouimustseemlikethat":"Mordomo — Encolhido sobre a arca. Sim, senhor: a um grande homem como o senhor devo parecer assim.","robertturningmyfaultisupposeeh~turningmyfaultisupposeeh":"Robert — Virando-se. A culpa é minha, suponho. Hein?","stewardcomingtohimdeprecatinglyohsiryoua~stinnocentwordssuchaturn":"Mordomo — Aproximando-se dele, em tom de súplica. Oh, senhor: o senhor sempre dá às minhas palavras mais inocentes uma volta tão estranha!","robertiwillgiveyourneckaturnifyoudaretel~rearethatyoucannotlayany":"Robert — Vou dar uma volta no seu pescoço se você ousar me dizer, quando eu perguntar quantos ovos há, que não pode pô-los.","stewardprotestingohsirohsir~wardprotestingohsirohsir":"Mordomo — Protestando. Oh, senhor, oh, senhor...","robertnonotohsirohsirbutnosirnosirmythre~terdaytoodonotforgetthat":"Robert — Não: nada de oh, senhor, oh, senhor, mas sim, não, senhor, não, senhor. Minhas três galinhas da Berbéria e a preta são as melhores poedeiras da Champanhe. E você vem me dizer que não há ovos! Quem os roubou? Diga-me isso antes que eu o ponha a pontapés pelo portão do castelo como mentiroso e vendedor dos meus bens a ladrões. O leite também faltou ontem: não se esqueça disso.","stewarddesperateiknowsiriknowonlytoowell~morrowtherewillbenothing":"Mordomo — Desesperado. Eu sei, senhor. Sei só demais. Não há leite: não há ovos: amanhã não haverá nada.","robertnothingyouwillstealtheloteh~hingyouwillstealtheloteh":"Robert — Nada! Você vai roubar tudo: hein?","stewardnosirnobodywillstealanythingbutth~aspellonuswearebewitched":"Mordomo — Não, senhor: ninguém vai roubar coisa alguma. Mas há um feitiço sobre nós: estamos enfeitiçados.","robertthatstoryisnotgoodenoughformerober~sseatwithanairoffinality":"Robert — Essa história não me convence. Robert de Baudricourt queima bruxas e enforca ladrões. Vá. Traga-me quatro dúzias de ovos e dois galões de leite aqui nesta sala antes do meio-dia, ou que o Céu tenha piedade dos seus ossos! Eu lhe ensinarei a me fazer de tolo. Retoma o assento com ar de quem deu a palavra final."}$tr$::jsonb, 28)
