-- h-g-wells_the-time-machine (15 parágrafos, excerpt)
insert into public.livros_traducoes (texto_slug, idioma, cobertura, credito, titulos, paragrafos, total_paragrafos) values ('h-g-wells_the-time-machine', 'pt', 'trecho', 'Tradução para o português do Brasil feita por IA (Claude) para o Alice''s Library; trecho de abertura, revisão pendente.', $tr${"chapteri":"Capítulo I"}$tr$::jsonb, $tr${"thetimetravellerforsoitwillbeconvenientt~thoughtitandhisfecundity":"O Viajante do Tempo (pois assim será conveniente referir-se a ele) expunha-nos um assunto recôndito. Seus olhos cinzentos brilhavam e cintilavam, e seu rosto, geralmente pálido, estava corado e animado. O fogo ardia vivamente, e o suave fulgor das lâmpadas incandescentes, nos lírios de prata, apanhava as bolhas que cintilavam e passavam em nossas taças. Nossas poltronas, sendo patentes dele, abraçavam-nos e acariciavam-nos em vez de se submeterem a que nos sentássemos nelas, e havia aquela atmosfera luxuosa de depois do jantar em que o pensamento vagueia, graciosamente livre das peias da precisão. E ele nos expôs a questão assim — marcando os pontos com um indicador magro — enquanto nos sentávamos, a admirar preguiçosamente seu fervor diante daquele novo paradoxo (como o julgávamos) e sua fecundidade.","youmustfollowmecarefullyishallhavetocont~sfoundedonamisconception":"“Precisam acompanhar-me com atenção. Terei de contestar uma ou duas ideias quase universalmente aceitas. A geometria, por exemplo, que lhes ensinaram na escola, funda-se num equívoco.”","isnotthatratheralargethingtoexpectustobe~ntativepersonwithredhair":"“Não é um pouco demais esperar que comecemos por aí?”, disse Filby, pessoa argumentadora e de cabelos ruivos.","idonotmeantoaskyoutoacceptanythingwithou~hingsaremereabstractions":"“Não pretendo pedir que aceitem coisa alguma sem fundamento razoável. Logo admitirão tudo o que preciso de vocês. Sabem, naturalmente, que uma linha matemática, uma linha de espessura nula, não tem existência real. Isso lhes ensinaram? Tampouco tem um plano matemático. Essas coisas são meras abstrações.”","thatisallrightsaidthepsychologist~rightsaidthepsychologist":"“Até aí tudo bem”, disse o Psicólogo.","norhavingonlylengthbreadthandthicknessca~nacubehavearealexistence":"“Nem, tendo apenas comprimento, largura e espessura, pode um cubo ter existência real.”","thereiobjectsaidfilbyofcourseasolidbodym~odymayexistallrealthings":"“Aí eu discordo”, disse Filby. “É claro que um corpo sólido pode existir. Todas as coisas reais...”","somostpeoplethinkbutwaitamomentcananinst~aninstantaneouscubeexist":"“É o que a maioria pensa. Mas esperem um momento. Pode um cubo instantâneo existir?”","dontfollowyousaidfilby~dontfollowyousaidfilby":"“Não o acompanho”, disse Filby.","canacubethatdoesnotlastforanytimeatallha~eatallhavearealexistence":"“Pode um cubo que não dura tempo algum ter existência real?”","filbybecamepensiveclearlythetimetravelle~inningtotheendofourlives":"Filby ficou pensativo. “Evidentemente”, prosseguiu o Viajante do Tempo, “todo corpo real deve ter extensão em quatro direções: deve ter Comprimento, Largura, Espessura e... Duração. Mas por uma enfermidade natural da carne, que lhes explicarei em um momento, tendemos a ignorar esse fato. Existem realmente quatro dimensões, três que chamamos os três planos do Espaço, e uma quarta, o Tempo. Há, contudo, uma tendência a traçar uma distinção irreal entre as três primeiras dimensões e a última, porque acontece que nossa consciência se move de modo intermitente numa só direção ao longo desta, do começo ao fim de nossas vidas.”","thatsaidaveryyoungmanmakingspasmodiceffo~elampthatveryclearindeed":"“Isso”, disse um rapaz muito jovem, fazendo esforços espasmódicos para reacender o charuto na lâmpada; “isso... muito claro, de fato.”","nowitisveryremarkablethatthisissoextensi~aboutthisfourthdimension":"“Ora, é muito notável que isso seja tão amplamente ignorado”, continuou o Viajante do Tempo, com um leve acréscimo de bom humor. “É realmente isso o que se entende por Quarta Dimensão, embora algumas pessoas que falam da Quarta Dimensão não saibam que é isso que querem dizer. É apenas outra maneira de encarar o Tempo. Não há diferença entre o Tempo e qualquer das três dimensões do Espaço, exceto que nossa consciência se move ao longo dele. Mas algumas pessoas tolas pegaram a ideia pelo lado errado. Todos vocês já ouviram o que elas têm a dizer sobre essa Quarta Dimensão?”","ihavenotsaidtheprovincialmayor~otsaidtheprovincialmayor":"“Eu não”, disse o Prefeito da província.","itissimplythisthatspaceasourmathematicia~perspectiveofthethingsee":"“É simplesmente isto. Que o Espaço, como o apresentam nossos matemáticos, é descrito como tendo três dimensões, que se podem chamar Comprimento, Largura e Espessura, e é sempre definível por referência a três planos, cada um em ângulo reto com os outros. Mas alguns filósofos vêm perguntando por que precisamente três dimensões — por que não outra direção em ângulo reto com as três outras? — e chegaram a tentar construir uma geometria de Quatro Dimensões. O professor Simon Newcomb expunha isso à Sociedade Matemática de Nova York há apenas um mês, mais ou menos. Sabem como, numa superfície plana, que tem apenas duas dimensões, podemos representar a figura de um sólido de três dimensões; do mesmo modo, eles pensam que, por modelos de três dimensões, poderiam representar um de quatro — se conseguissem dominar a perspectiva da coisa. Entendem?”"}$tr$::jsonb, 15)
