-- h-g-wells_the-war-of-the-worlds (5 parágrafos, excerpt)
insert into public.livros_traducoes (texto_slug, idioma, cobertura, credito, titulos, paragrafos, total_paragrafos) values ('h-g-wells_the-war-of-the-worlds', 'pt', 'trecho', 'Tradução para o português do Brasil feita por IA (Claude) para o Alice''s Library; trecho de abertura, revisão pendente.', $tr${"theeveofthewar":"A véspera da guerra"}$tr$::jsonb, $tr${"noonewouldhavebelievedinthelastyearsofth~ethegreatdisillusionment":"Ninguém teria acreditado, nos últimos anos do século XIX, que este mundo estava sendo observado de perto e com atenção por inteligências superiores à do homem e, no entanto, tão mortais quanto ela; que, enquanto os homens se ocupavam de seus vários afazeres, eram examinados e estudados, talvez quase tão minuciosamente quanto um homem com um microscópio examinaria as criaturas transitórias que pululam e se multiplicam numa gota d’água. Com infinita complacência, os homens iam e vinham pelo globo cuidando de seus pequenos negócios, serenos na certeza de seu domínio sobre a matéria. É possível que os infusórios sob o microscópio façam o mesmo. Ninguém dava um pensamento aos mundos mais antigos do espaço como fontes de perigo para o homem, ou só pensava neles para descartar a ideia de vida ali como impossível ou improvável. É curioso recordar alguns dos hábitos mentais daqueles dias idos. No máximo, os homens terrestres imaginavam que pudesse haver outros homens em Marte, talvez inferiores a eles e dispostos a acolher uma empresa missionária. No entanto, do outro lado do abismo do espaço, mentes que estão para as nossas como as nossas para as das bestas que perecem, intelectos vastos, frios e impiedosos, contemplavam esta Terra com olhos invejosos e, lenta e seguramente, traçavam seus planos contra nós. E no início do século XX veio o grande desengano.","theplanetmarsiscarcelyneedremindthereade~pportofanimatedexistence":"O planeta Marte, mal preciso lembrar ao leitor, gira em torno do sol a uma distância média de 140.000.000 de milhas, e a luz e o calor que dele recebe mal chegam à metade do que recebe este mundo. Deve ser, se a hipótese nebular tem alguma verdade, mais velho que o nosso mundo; e muito antes de esta Terra deixar de ser incandescente, a vida em sua superfície deve ter começado seu curso. O fato de ter apenas um sétimo do volume da Terra deve ter acelerado seu resfriamento até a temperatura em que a vida pôde começar. Tem ar e água e tudo o que é necessário para sustentar a existência animada.","yetsovainismanandsoblindedbyhisvanitytha~beginningbutneareritsend":"Contudo, tão vaidoso é o homem, e tão cego pela vaidade, que nenhum escritor, até o fim do século XIX, exprimiu a ideia de que ali pudesse ter se desenvolvido uma vida inteligente muito além do nível terrestre, ou mesmo qualquer vida inteligente. Tampouco se compreendia em geral que, sendo Marte mais velho que a Terra, com pouco mais de um quarto de sua área superficial e mais afastado do sol, segue-se necessariamente que ele está não só mais distante do começo do tempo, mas mais próximo de seu fim.","thesecularcoolingthatmustsomedayovertake~andnarrownavycrowdedseas":"O resfriamento secular que um dia há de alcançar o nosso planeta já avançou muito em nosso vizinho. Seu estado físico ainda é em grande parte um mistério, mas sabemos agora que, mesmo na região equatorial, a temperatura do meio-dia mal se aproxima da de nosso inverno mais frio. Seu ar é muito mais rarefeito que o nosso, seus oceanos encolheram até cobrir apenas um terço da superfície e, à medida que suas lentas estações mudam, enormes calotas de neve se formam e derretem em torno de cada polo, inundando periodicamente suas zonas temperadas. Esse último estágio de exaustão, que para nós ainda é inacreditavelmente remoto, tornou-se um problema atual para os habitantes de Marte. A pressão imediata da necessidade aguçou-lhes o intelecto, ampliou-lhes os poderes e endureceu-lhes o coração. E, olhando através do espaço com instrumentos e inteligências como mal sonhamos, eles veem, à sua distância mínima de apenas 35.000.000 de milhas em direção ao sol, uma estrela da manhã de esperança, o nosso planeta mais quente, verde de vegetação e cinzento de água, com uma atmosfera nublada eloquente de fertilidade, e com vislumbres, por entre os farrapos de nuvens à deriva, de vastas extensões de terra populosa e de mares estreitos apinhados de navios.","andwementhecreatureswhoinhabitthisearthm~generationcreepsuponthem":"E nós, homens, as criaturas que habitam esta Terra, devemos ser para eles ao menos tão estranhos e inferiores quanto são para nós os macacos e os lêmures. O lado intelectual do homem já admite que a vida é uma luta incessante pela existência, e parece que esta é também a crença das mentes de Marte. O mundo deles está muito avançado em seu resfriamento, e este mundo ainda está repleto de vida, mas repleto apenas do que eles consideram animais inferiores. Levar a guerra em direção ao sol é, de fato, sua única fuga da destruição que, geração após geração, rasteja até eles."}$tr$::jsonb, 5)
on conflict (texto_slug, idioma) do update set cobertura = excluded.cobertura, credito = excluded.credito, titulos = excluded.titulos, paragrafos = excluded.paragrafos, total_paragrafos = excluded.total_paragrafos, atualizado_em = now();

-- henry-james_the-turn-of-the-screw (10 parágrafos, excerpt)
insert into public.livros_traducoes (texto_slug, idioma, cobertura, credito, titulos, paragrafos, total_paragrafos) values ('henry-james_the-turn-of-the-screw', 'pt', 'trecho', 'Tradução para o português do Brasil feita por IA (Claude) para o Alice''s Library; trecho de abertura, revisão pendente.', $tr${"prologue":"Prólogo"}$tr$::jsonb, $tr${"thestoryhadheldusroundthefiresufficientl~oughtoutwhatwasinhismind":"A história nos havia prendido, em volta do fogo, num suspense suficiente; mas, afora a observação óbvia de que era arrepiante, como convém, na noite de Natal, a uma história estranha contada numa casa antiga, não me lembro de comentário algum até que alguém por acaso disse que era o único caso que conhecera em que tal visitação recaíra sobre uma criança. O caso, devo mencionar, era o de uma aparição numa casa antiga como a que nos reunira para a ocasião — uma aparição, de natureza terrível, a um menino que dormia no quarto com a mãe e que a acordou no terror daquilo; acordou-a não para dissipar o seu medo e embalá-lo de novo para o sono, mas para enfrentar também ela, antes de o conseguir, a mesma visão que o abalara. Foi essa observação que arrancou de Douglas — não de imediato, mas mais tarde, na mesma noite — uma resposta que teve a interessante consequência para a qual chamo a atenção. Alguém contou outra história, nada particularmente eficaz, que vi que ele não acompanhava. Tomei isso por sinal de que ele próprio tinha algo a apresentar e de que bastaria esperar. Esperamos, de fato, até duas noites depois; mas naquela mesma noite, antes de nos dispersarmos, ele trouxe à luz o que tinha em mente.","iquiteagreeinregardtogriffinsghostorwhat~hatdoyousaytotwochildren":"“Concordo plenamente — quanto ao fantasma de Griffin, ou o que quer que fosse — que o seu aparecimento primeiro a um menininho, em idade tão tenra, acrescenta um toque particular. Mas não é a primeira ocorrência desse gênero encantador que sei ter envolvido uma criança. Se a criança dá ao efeito mais uma volta do parafuso, que dizem de duas crianças...?”","wesayofcoursesomebodyexclaimedthattheygi~hatwewanttohearaboutthem":"“Dizemos, naturalmente” — exclamou alguém — “que elas dão duas voltas! E também que queremos ouvir sobre elas.”","icanseedouglastherebeforethefiretowhichh~gatallthatiknowtouchesit":"Vejo Douglas ali diante do fogo, ao qual se levantara para apresentar as costas, olhando para baixo, para o seu interlocutor, com as mãos nos bolsos. “Ninguém além de mim, até agora, jamais ouviu. É horrível demais.” Isso, naturalmente, foi declarado por várias vozes como a coisa que mais lhe aumentava o preço, e nosso amigo, com arte discreta, preparou seu triunfo passando os olhos pelo resto de nós e prosseguindo: “Está acima de tudo. Nada que eu conheça se lhe compara.”","forsheerterrorirememberasking~eerterrorirememberasking":"“Em puro terror?” lembro-me de ter perguntado.","heseemedtosayitwasnotsosimpleasthattober~efordreadfuldreadfulness":"Ele pareceu dizer que não era tão simples assim; parecia realmente sem saber como qualificá-lo. Passou a mão sobre os olhos, fez uma pequena careta de dor. “Em horrendez — em horror!”","ohhowdeliciouscriedoneofthewomen~iciouscriedoneofthewomen":"“Oh, que delícia!” exclamou uma das mulheres.","hetooknonoticeofherhelookedatmebutasifin~uglinessandhorrorandpain":"Ele não lhe deu atenção; olhou para mim, mas como se, em vez de mim, visse aquilo de que falava. “Em feiura sobrenatural geral, e horror, e dor.”","wellthenisaidjustsitrightdownandbegin~justsitrightdownandbegin":"“Pois bem”, disse eu, “sente-se aí mesmo e comece.”","heturnedroundtothefiregaveakicktoalogwat~werwaspromptohthankgodno":"Ele se voltou para o fogo, deu um pontapé numa tora, observou-a um instante. Depois, ao nos encarar de novo: “Não posso começar. Terei de mandar buscar na cidade.” Houve um gemido unânime diante disso, e muita censura; após o que, em seu jeito preocupado, ele explicou. “A história está escrita. Está numa gaveta trancada — não sai de lá há anos. Eu poderia escrever ao meu criado e incluir a chave; ele mandaria o pacote como o encontrasse.” Era a mim em particular que ele parecia propor isso — parecia quase apelar por auxílio para não hesitar. Ele havia quebrado uma espessura de gelo, formada ao longo de muitos invernos; tivera suas razões para um longo silêncio. Os outros se ressentiam do adiamento, mas eram justamente os seus escrúpulos que me encantavam. Exortei-o a escrever pelo primeiro correio e a combinar conosco uma audição próxima; depois lhe perguntei se a experiência em questão fora sua. A resposta veio pronta. “Oh, graças a Deus, não!”"}$tr$::jsonb, 10)
