-- jane-austen_northanger-abbey (2 parágrafos, excerpt)
insert into public.livros_traducoes (texto_slug, idioma, cobertura, credito, titulos, paragrafos, total_paragrafos) values ('jane-austen_northanger-abbey', 'pt', 'trecho', 'Tradução para o português do Brasil feita por IA (Claude) para o Alice''s Library; trecho de abertura, revisão pendente.', $tr${"chapteri":"Capítulo I"}$tr$::jsonb, $tr${"noonewhohadeverseencatherinemorlandinher~slopeatthebackofthehouse":"Ninguém que tivesse visto Catherine Morland na infância teria suposto que ela nascera para ser heroína. Sua situação na vida, o caráter do pai e da mãe, sua própria pessoa e disposição, tudo lhe era igualmente adverso. O pai era clérigo, sem ser negligenciado nem pobre, e homem muito respeitável, embora se chamasse Richard — e nunca tivesse sido bonito. Tinha considerável independência, além de dois bons benefícios eclesiásticos — e não era nem um pouco dado a trancar as filhas. A mãe era mulher de bom senso simples e útil, de gênio brando e, o que é mais notável, de boa constituição. Tivera três filhos antes de nascer Catherine; e, em vez de morrer ao trazer esta ao mundo, como qualquer um esperaria, continuou vivendo — viveu para ter mais seis filhos — para vê-los crescer à sua volta e para gozar ela própria de excelente saúde. Uma família de dez filhos será sempre chamada de bela família, havendo cabeças, braços e pernas bastantes para o número; mas os Morland tinham pouco outro direito ao qualificativo, pois eram em geral muito feios, e Catherine, por muitos anos de sua vida, tão feia quanto qualquer um. Tinha o corpo magro e desajeitado, a pele amarelada e sem cor, os cabelos escuros e escorridos e as feições fortes — tanto quanto à pessoa; e não menos desfavorável ao heroísmo parecia-lhe o espírito. Gostava de todas as brincadeiras de meninos e preferia de longe o críquete não apenas às bonecas, mas aos divertimentos mais heroicos da infância, como criar um arganaz, alimentar um canário ou regar um roseiral. Na verdade, não tinha gosto algum por jardins; e, se colhia flores, era principalmente pelo prazer da travessura — ao menos assim se conjecturava, por ela preferir sempre as que lhe eram proibidas. Tais eram suas propensões — e suas aptidões eram igualmente extraordinárias. Nunca conseguia aprender ou compreender coisa alguma antes de lhe ser ensinada; e às vezes nem mesmo então, pois era muitas vezes desatenta e ocasionalmente estúpida. A mãe levou três meses para lhe ensinar apenas a recitar a “Súplica do Mendigo”; e, afinal, a irmã que vinha logo depois, Sally, a dizia melhor do que ela. Não que Catherine fosse sempre estúpida — de modo algum; aprendeu a fábula “A Lebre e os Muitos Amigos” tão depressa quanto qualquer menina da Inglaterra. A mãe queria que aprendesse música; e Catherine tinha certeza de que gostaria, pois adorava tilintar as teclas da velha e desolada espineta; assim, aos oito anos começou. Aprendeu durante um ano e não pôde suportar; e a sra. Morland, que não insistia em que as filhas fossem prendadas apesar da incapacidade ou do desgosto, permitiu que largasse. O dia que dispensou o professor de música foi um dos mais felizes da vida de Catherine. Seu gosto pelo desenho não era superior; embora, sempre que conseguia o lado de fora de uma carta da mãe ou se apossava de algum outro pedaço de papel avulso, fizesse o que podia nesse gênero, desenhando casas e árvores, galinhas e pintinhos, todos muito parecidos uns com os outros. Escrita e contas aprendeu com o pai; francês, com a mãe: sua proficiência em qualquer das duas não era notável, e ela fugia às lições de ambas sempre que podia. Que caráter estranho, inexplicável! — pois, com todos esses sintomas de dissipação aos dez anos, não tinha nem mau coração nem mau gênio, raramente era teimosa, quase nunca briguenta, e muito boa para com os pequenos, com poucas interrupções de tirania; era, além disso, barulhenta e selvagem, detestava confinamento e limpeza, e nada amava tanto no mundo quanto rolar pela encosta verde atrás da casa.","suchwascatherinemorlandattenatfifteenapp~mhercradlecaneverreceive":"Assim era Catherine Morland aos dez anos. Aos quinze, as aparências melhoravam; começou a frisar os cabelos e a desejar bailes; a tez melhorou, as feições se suavizaram com o viço e a cor, os olhos ganharam mais animação e o corpo mais importância. O amor à sujeira cedeu lugar a uma inclinação pelos enfeites, e ela se tornou limpa à medida que se tornava elegante; tinha agora o prazer de ouvir, às vezes, o pai e a mãe comentarem seu melhoramento pessoal. “Catherine está ficando uma moça bem bonita — hoje está quase linda”, eram palavras que lhe chegavam aos ouvidos de vez em quando; e como eram bem-vindos esses sons! Parecer quase linda é uma aquisição de deleite maior para uma menina que foi feia nos primeiros quinze anos de sua vida do que jamais poderá receber uma beldade desde o berço."}$tr$::jsonb, 2)
