-- jane-austen_sense-and-sensibility (4 parágrafos, excerpt)
insert into public.livros_traducoes (texto_slug, idioma, cobertura, credito, titulos, paragrafos, total_paragrafos) values ('jane-austen_sense-and-sensibility', 'pt', 'trecho', 'Tradução para o português do Brasil feita por IA (Claude) para o Alice''s Library; trecho de abertura, revisão pendente.', $tr${"chapteri":"Capítulo I"}$tr$::jsonb, $tr${"thefamilyofdashwoodhadlongbeensettledins~dedarelishtohisexistence":"A família Dashwood estava havia muito estabelecida em Sussex. Sua propriedade era grande, e sua residência ficava em Norland Park, no centro de suas terras, onde, por muitas gerações, viveram de maneira tão respeitável que conquistaram a boa opinião geral de seus vizinhos e conhecidos. O último dono da propriedade era um homem solteiro, que viveu até idade muito avançada e que, durante muitos anos de sua vida, teve na irmã uma companheira constante e governanta da casa. Mas a morte dela, ocorrida dez anos antes da sua, produziu grande mudança em seu lar; pois, para suprir-lhe a perda, convidou e recebeu em casa a família de seu sobrinho, o Sr. Henry Dashwood, herdeiro legítimo da propriedade de Norland e a pessoa a quem pretendia legá-la. Na companhia do sobrinho, da sobrinha e dos filhos deles, os dias do velho cavalheiro transcorreram confortavelmente. Sua afeição por todos aumentou. A atenção constante do Sr. e da Sra. Henry Dashwood a seus desejos, que procedia não somente de interesse, mas de bondade de coração, deu-lhe todo o grau de sólido conforto que sua idade podia receber; e a alegria das crianças acrescentava sabor à sua existência.","byaformermarriagemrhenrydashwoodhadoneso~hadonlyalifeinterestinit":"De um casamento anterior, o Sr. Henry Dashwood tinha um filho; de sua atual esposa, três filhas. O filho, rapaz sério e respeitável, estava amplamente provido pela fortuna da mãe, que fora grande, e da qual metade lhe coube ao atingir a maioridade. Com o próprio casamento, ocorrido logo depois, aumentou também sua riqueza. Para ele, portanto, a sucessão da propriedade de Norland não era tão realmente importante quanto para as irmãs; pois a fortuna delas, independente do que lhes pudesse advir de o pai herdar aquela propriedade, não podia ser senão pequena. A mãe nada tinha, e o pai apenas sete mil libras à sua livre disposição; pois a metade restante da fortuna de sua primeira esposa também estava assegurada ao filho dela, e ele tinha sobre ela apenas o usufruto vitalício.","theoldgentlemandiedhiswillwasreadandlike~hemathousandpoundsapiece":"O velho cavalheiro morreu: seu testamento foi lido e, como quase todos os testamentos, deu tanta decepção quanto prazer. Não foi tão injusto nem tão ingrato a ponto de tirar a propriedade do sobrinho; mas deixou-a a ele em condições que destruíam metade do valor do legado. O Sr. Dashwood a desejara mais por causa da esposa e das filhas do que por si ou pelo filho; mas ao filho, e ao filho do filho, um menino de quatro anos, ela foi assegurada de tal modo que o deixava sem poder algum de prover aqueles que lhe eram mais caros, e que mais precisavam de provisão, seja por algum encargo sobre a propriedade, seja pela venda de seus valiosos bosques. Tudo foi vinculado em benefício dessa criança, que, em visitas ocasionais com o pai e a mãe a Norland, havia ganhado de tal modo a afeição do tio, por atrativos de modo algum incomuns em crianças de dois ou três anos — uma articulação imperfeita, um desejo ardente de fazer a própria vontade, muitas travessuras manhosas e muito barulho — que superou todo o valor de todas as atenções que, por anos, ele recebera da sobrinha e das filhas dela. Não pretendia, contudo, ser indelicado e, como prova de sua afeição pelas três meninas, deixou-lhes mil libras a cada uma.","mrdashwoodsdisappointmentwasatfirstsever~dforhiswidowanddaughters":"A decepção do Sr. Dashwood foi, a princípio, severa; mas seu temperamento era alegre e otimista; e ele podia razoavelmente esperar viver muitos anos e, vivendo com economia, juntar uma soma considerável com o rendimento de uma propriedade já grande e capaz de melhoramento quase imediato. Mas a fortuna, que tanto tardara a chegar, foi sua por apenas um ano. Não sobreviveu ao tio por mais tempo; e dez mil libras, incluindo os recentes legados, era tudo o que restava à viúva e às filhas."}$tr$::jsonb, 4)
