-- l-m-montgomery_anne-of-green-gables (5 parágrafos, excerpt)
insert into public.livros_traducoes (texto_slug, idioma, cobertura, credito, titulos, paragrafos, total_paragrafos) values ('l-m-montgomery_anne-of-green-gables', 'pt', 'trecho', 'Tradução para o português do Brasil feita por IA (Claude) para o Alice''s Library; trecho de abertura, revisão pendente.', $tr${"mrsrachellyndeissurprised":"A surpresa da Sra. Rachel Lynde"}$tr$::jsonb, $tr${"mrsrachellyndelivedjustwheretheavonleama~whysandwhereforesthereof":"A Sra. Rachel Lynde morava justamente onde a estrada principal de Avonlea descia a uma pequena baixada, orlada de amieiros e brincos-de-princesa e atravessada por um riacho que nascia lá longe, nos bosques da velha propriedade dos Cuthbert; diziam que, em seu curso inicial por esses bosques, era um riacho intrincado e impetuoso, de poços e cascatas cheios de segredos sombrios; mas, quando chegava ao Vale de Lynde, já era uma corrente tranquila e bem-comportada, pois nem mesmo um riacho podia passar pela porta da Sra. Rachel Lynde sem o devido respeito à decência e ao decoro; provavelmente sabia que a Sra. Rachel estava sentada à janela, de olho vivo em tudo o que passava, de riachos e crianças para cima, e que, se notasse qualquer coisa estranha ou fora do lugar, não descansaria enquanto não farejasse os porquês e os comos.","thereareplentyofpeopleinavonleaandoutofi~ofmrsrachelsallseeingeye":"Há muita gente, em Avonlea e fora dela, que consegue cuidar de perto dos negócios dos vizinhos à força de negligenciar os seus; mas a Sra. Rachel Lynde era uma dessas criaturas capazes que dão conta dos próprios assuntos e, de quebra, dos alheios. Era uma dona de casa notável; seu trabalho estava sempre pronto e bem-feito; “comandava” o Círculo de Costura, ajudava a comandar a Escola Dominical e era o mais firme esteio da Sociedade de Auxílio da Igreja e do Auxiliar das Missões Estrangeiras. Ainda assim, a Sra. Rachel achava tempo de sobra para ficar horas à janela da cozinha, tricotando colchas de “urdidura de algodão” — já fizera dezesseis, como as donas de casa de Avonlea costumavam contar em voz reverente — e vigiando de olho vivo a estrada principal que cruzava a baixada e subia, sinuosa, a íngreme colina vermelha adiante. Como Avonlea ocupava uma pequena península triangular que avançava pelo Golfo de São Lourenço, com água em dois lados, quem saísse ou entrasse tinha de passar por aquela estrada da colina e, assim, enfrentar o corredor invisível do olhar onividente da Sra. Rachel.","shewassittingthereoneafternooninearlyjun~utanythinginhiswholelife":"Ela estava ali sentada numa tarde do início de junho. O sol entrava pela janela, quente e claro; o pomar na encosta abaixo da casa estava num rubor de noiva, todo em flores branco-rosadas, zumbindo com miríades de abelhas. Thomas Lynde — um homenzinho manso a quem o povo de Avonlea chamava de “o marido de Rachel Lynde” — semeava sua sementeira tardia de nabos no campo da colina, atrás do celeiro; e Matthew Cuthbert devia estar semeando a dele no grande campo vermelho do riacho, lá para os lados de Green Gables. A Sra. Rachel sabia que ele devia porque o ouvira dizer a Peter Morrison, na noite anterior, na loja de William J. Blair, em Carmody, que pretendia semear as sementes de nabo na tarde seguinte. Peter lhe perguntara, é claro, pois nunca se soube que Matthew Cuthbert desse informação por iniciativa própria sobre coisa alguma em toda a sua vida.","andyetherewasmatthewcuthbertathalfpastth~ingandwhywashegoingthere":"E no entanto ali estava Matthew Cuthbert, às três e meia da tarde de um dia de muito trabalho, atravessando placidamente a baixada e subindo a colina; além disso, usava colarinho branco e seu melhor terno, prova clara de que ia sair de Avonlea; e levava a charrete e a égua alazã, o que indicava que ia a uma distância considerável. Ora, aonde ia Matthew Cuthbert e por que ia lá?","haditbeenanyothermaninavonleamrsrachelde~noonsenjoymentwasspoiled":"Se fosse qualquer outro homem de Avonlea, a Sra. Rachel, juntando habilmente isto e aquilo, poderia ter dado um bom palpite para ambas as perguntas. Mas Matthew saía tão raramente de casa que devia ser algo urgente e incomum o que o levava; era o homem mais tímido do mundo e detestava ter de ir entre estranhos ou a qualquer lugar onde pudesse ter de conversar. Matthew de colarinho branco e dirigindo uma charrete era coisa que não acontecia com frequência. A Sra. Rachel, por mais que cismasse, não conseguia entender nada, e o prazer de sua tarde estava estragado."}$tr$::jsonb, 5)
on conflict (texto_slug, idioma) do update set cobertura = excluded.cobertura, credito = excluded.credito, titulos = excluded.titulos, paragrafos = excluded.paragrafos, total_paragrafos = excluded.total_paragrafos, atualizado_em = now();

-- lewis-carroll_alices-adventures-in-wonderland (50 parágrafos, partial)
insert into public.livros_traducoes (texto_slug, idioma, cobertura, credito, titulos, paragrafos, total_paragrafos) values ('lewis-carroll_alices-adventures-in-wonderland', 'pt', 'parcial', 'Tradução para o português do Brasil feita por IA (Claude) para o Alice''s Library; capítulos I e II, revisão pendente.', $tr${"downtherabbithole":"Pela Toca do Coelho","thepooloftears":"A Poça de Lágrimas"}$tr$::jsonb, $tr${"alicewasbeginningtogetverytiredofsitting~tpicturesorconversations":"Alice estava começando a ficar muito cansada de ficar sentada ao lado da irmã, na margem do rio, sem ter nada para fazer: uma ou duas vezes espiara o livro que a irmã lia, mas não tinha figuras nem diálogos, “e para que serve um livro”, pensou Alice, “sem figuras nem diálogos?”","soshewasconsideringinherownmindaswellass~ithpinkeyesranclosebyher":"Então ficou pensando consigo mesma (tanto quanto podia, pois o calor do dia a deixava com muito sono e a cabeça pesada) se o prazer de fazer uma guirlanda de margaridas valeria o trabalho de se levantar para colher as flores, quando, de repente, um Coelho Branco de olhos cor-de-rosa passou correndo bem perto dela.","therewasnothingsoveryremarkableinthatnor~erabbitholeunderthehedge":"Não havia nada de tão extraordinário nisso; nem Alice achou tão estranho assim ouvir o Coelho dizer a si mesmo: “Ai, meu Deus! Ai, meu Deus! Vou chegar atrasado!” (quando pensou no assunto depois, ocorreu-lhe que deveria ter estranhado aquilo, mas na hora tudo pareceu muito natural); mas, quando o Coelho de fato tirou um relógio do bolso do colete, olhou para ele e depois saiu apressado, Alice pôs-se de pé num salto, pois lhe passou pela cabeça que nunca tinha visto um coelho com bolso de colete, nem com um relógio para tirar de lá; e, ardendo de curiosidade, atravessou o campo correndo atrás dele e, por sorte, chegou a tempo de vê-lo entrar numa grande toca de coelho debaixo da cerca viva.","inanothermomentdownwentaliceafteritnever~worldshewastogetoutagain":"No instante seguinte, lá se foi Alice atrás dele, sem pensar nem uma vez em como faria para sair dali.","therabbitholewentstraightonlikeatunnelfo~fallingdownaverydeepwell":"A toca do coelho seguia em linha reta como um túnel por algum tempo, e depois descia de repente, tão de repente que Alice não teve um momento sequer para pensar em se segurar antes de se ver caindo por um poço muito fundo.","eitherthewellwasverydeeporshefellveryslo~cupboardsasshefellpastit":"Ou o poço era muito fundo, ou ela caía muito devagar, pois teve tempo de sobra, enquanto descia, para olhar à sua volta e se perguntar o que iria acontecer em seguida. Primeiro tentou olhar para baixo e ver aonde estava indo, mas estava escuro demais para enxergar qualquer coisa; depois olhou para as paredes do poço e notou que estavam cheias de armários e estantes; aqui e ali via mapas e quadros pendurados em ganchos. Pegou um pote de uma das prateleiras quando passou; tinha o rótulo “Geleia de Laranja”, mas, para sua grande decepção, estava vazio: não quis largar o pote com medo de matar alguém lá embaixo, e conseguiu colocá-lo em um dos armários ao passar por ele.","wellthoughtalicetoherselfaftersuchafalla~sewhichwasverylikelytrue":"“Bem!”, pensou Alice com seus botões, “depois de uma queda como esta, não vou fazer caso de rolar escada abaixo! Como vão me achar corajosa, lá em casa! Ora, eu não diria nada a respeito, mesmo que caísse do alto do telhado!” (O que era bem provável que fosse verdade.)","downdowndownwouldthefallnevercometoanend~ywerenicegrandwordstosay":"Caindo, caindo, caindo. Será que a queda nunca ia acabar! “Quantas milhas será que já caí até agora?”, disse em voz alta. “Devo estar chegando perto do centro da Terra. Deixe-me ver: isso seria uns seis mil quilômetros para baixo, creio eu...” (pois, como veem, Alice tinha aprendido várias coisas desse tipo nas lições da escola, e embora aquela não fosse uma ótima ocasião para exibir seus conhecimentos, já que não havia ninguém para ouvi-la, ainda assim era bom exercício repeti-los) “... sim, essa deve ser mais ou menos a distância certa... mas, então, em que Latitude ou Longitude será que eu estou?” (Alice não tinha a menor ideia do que era Latitude, nem Longitude, mas achava que eram palavras bonitas e imponentes de dizer.)","presentlyshebeganagainiwonderifishallfal~lseeitwrittenupsomewhere":"Logo começou de novo. “Será que vou atravessar a Terra de lado a lado! Que engraçado vai ser aparecer no meio de gente que anda de cabeça para baixo! Os Antipáticos, creio eu...” (ficou bastante contente por não haver ninguém ouvindo, desta vez, pois não lhe soou nada como a palavra certa) “... mas vou ter que perguntar a eles o nome do país, sabem como é. Por favor, minha senhora, aqui é a Nova Zelândia ou a Austrália?” (e tentou fazer uma reverência ao falar — imaginem fazer reverência enquanto se cai pelo ar! Acham que conseguiriam?) “E que menininha ignorante ela vai achar que eu sou, por perguntar! Não, não vai dar certo perguntar: talvez eu veja escrito em algum lugar.”","downdowndowntherewasnothingelsetodosoali~yleavesandthefallwasover":"Caindo, caindo, caindo. Não havia mais nada a fazer, então Alice logo voltou a falar. “A Dinah vai sentir muito a minha falta esta noite, imagino!” (Dinah era a gata.) “Espero que se lembrem do pires de leite dela na hora do chá. Dinah, minha querida! Como eu queria que você estivesse aqui embaixo comigo! Receio que não haja ratos no ar, mas você poderia pegar um morcego, que é muito parecido com um rato, sabe. Mas será que gatos comem morcegos?” E aí Alice começou a ficar com sono e continuou dizendo a si mesma, num tom sonhador: “Gatos comem morcegos? Gatos comem morcegos?” e às vezes: “Morcegos comem gatos?”, pois, como não sabia responder a nenhuma das perguntas, pouco importava de que jeito a fizesse. Sentia que estava cochilando e já começava a sonhar que andava de mãos dadas com Dinah, dizendo-lhe com muita seriedade: “Agora, Dinah, diga-me a verdade: você já comeu um morcego?”, quando de repente, bum! bum! caiu sobre um monte de gravetos e folhas secas, e a queda terminou.","alicewasnotabithurtandshejumpedupontoher~flampshangingfromtheroof":"Alice não se machucou nem um pouco e pôs-se de pé num instante; olhou para cima, mas estava tudo escuro lá no alto; à sua frente havia outro longo corredor, e o Coelho Branco ainda estava à vista, apressando-se por ele. Não havia um minuto a perder: lá se foi Alice como o vento, e chegou a tempo de ouvi-lo dizer, ao dobrar uma esquina: “Ai, minhas orelhas e meus bigodes, como está ficando tarde!” Estava logo atrás dele quando dobrou a esquina, mas o Coelho já não estava mais à vista: viu-se num salão comprido e baixo, iluminado por uma fileira de lamparinas penduradas no teto.","thereweredoorsallroundthehallbuttheywere~wshewasevertogetoutagain":"Havia portas por todos os lados do salão, mas todas estavam trancadas; e, depois de percorrer um lado inteiro e voltar pelo outro, tentando todas as portas, caminhou tristemente pelo meio, perguntando-se como faria para sair dali.","suddenlyshecameuponalittlethreeleggedtab~ohergreatdelightitfitted":"De repente deparou com uma mesinha de três pernas, toda feita de vidro maciço; não havia nada sobre ela, a não ser uma minúscula chave dourada, e o primeiro pensamento de Alice foi que talvez pertencesse a uma das portas do salão; mas, ai!, ou as fechaduras eram grandes demais, ou a chave era pequena demais, mas de qualquer modo ela não abria nenhuma. Contudo, na segunda volta, encontrou uma cortina baixa que não tinha notado antes, e atrás dela havia uma portinha de uns quarenta centímetros de altura: experimentou a chavinha dourada na fechadura e, para sua grande alegria, serviu!","aliceopenedthedoorandfoundthatitledintoa~deedwerereallyimpossible":"Alice abriu a porta e viu que dava para uma passagem estreita, não muito maior que uma toca de rato: ajoelhou-se e olhou ao longo da passagem para o jardim mais lindo que já se viu. Como desejava sair daquele salão escuro e passear entre aqueles canteiros de flores vivas e aquelas fontes frescas, mas não conseguia nem passar a cabeça pela porta; “e, mesmo que minha cabeça passasse”, pensou a pobre Alice, “de pouco serviria sem os ombros. Ah, como eu queria poder me fechar como um telescópio! Acho que conseguiria, se ao menos soubesse como começar.” Pois, como veem, tantas coisas estranhas tinham acontecido ultimamente que Alice começara a achar que pouquíssimas coisas eram realmente impossíveis.","thereseemedtobenouseinwaitingbythelittle~rintedonitinlargeletters":"Parecia não adiantar nada esperar junto à portinha, então voltou à mesa, meio na esperança de encontrar outra chave sobre ela, ou, pelo menos, um livro de regras para fechar as pessoas como telescópios: desta vez encontrou um frasquinho (“que certamente não estava aqui antes”, disse Alice), e em volta do gargalo havia uma etiqueta de papel com as palavras “Beba-me” lindamente impressas em letras grandes.","itwasallverywelltosaydrinkmebutthewiseli~greewithyousoonerorlater":"Era muito fácil dizer “Beba-me”, mas a sábia Alice não ia fazer isso assim de pressa. “Não, vou olhar primeiro”, disse ela, “para ver se está marcado ‘veneno’ ou não”; pois tinha lido várias historinhas simpáticas sobre crianças que se queimaram, foram devoradas por feras e sofreram outras coisas desagradáveis, tudo porque não quiseram se lembrar das regras simples que os amigos lhes haviam ensinado: como, por exemplo, que um atiçador em brasa queima se o segurarmos por tempo demais; e que, se cortamos o dedo bem fundo com uma faca, em geral sangra; e ela nunca esquecera que, se bebemos muito de uma garrafa marcada “veneno”, é quase certo que, mais cedo ou mais tarde, nos fará mal.","howeverthisbottlewasnotmarkedpoisonsoali~sheverysoonfinisheditoff":"Contudo, esse frasco não estava marcado “veneno”, então Alice se arriscou a prová-lo e, achando-o muito gostoso (tinha, na verdade, um sabor misturado de torta de cereja, creme, abacaxi, peru assado, caramelo e torrada quente com manteiga), logo o bebeu até o fim.","whatacuriousfeelingsaidaliceimustbeshutt~shuttinguplikeatelescope":"“Que sensação curiosa!”, disse Alice; “devo estar me fechando como um telescópio.”","andsoitwasindeedshewasnowonlytenincheshi~everhavingseensuchathing":"E era mesmo isso: estava agora com apenas vinte e cinco centímetros de altura, e o rosto se iluminou com a ideia de que agora tinha o tamanho certo para passar pela portinha rumo àquele jardim encantador. Primeiro, porém, esperou alguns minutos para ver se ia encolher mais: sentiu-se um pouco nervosa com isso; “pois poderia acabar”, disse Alice consigo mesma, “comigo me apagando de vez, como uma vela. Como será que eu ficaria então?” E tentou imaginar como é a chama de uma vela depois que a vela é soprada, pois não conseguia se lembrar de jamais ter visto tal coisa.","afterawhilefindingthatnothingmorehappene~ttlethingsatdownandcried":"Passado algum tempo, vendo que nada mais acontecia, decidiu ir para o jardim de uma vez; mas, ai da pobre Alice! ao chegar à porta, descobriu que tinha esquecido a chavinha dourada, e quando voltou à mesa para pegá-la, viu que não havia como alcançá-la: via a chave muito bem através do vidro e fez o possível para escalar uma das pernas da mesa, mas era escorregadia demais; e, quando se cansou de tanto tentar, a pobre coitadinha sentou-se e chorou.","cometheresnouseincryinglikethatsaidalice~makeonerespectableperson":"“Vamos, não adianta nada chorar assim!”, disse Alice a si mesma, com certa aspereza; “aconselho-a a parar agora mesmo!” Costumava dar a si mesma ótimos conselhos (embora raramente os seguisse), e às vezes se repreendia com tanta severidade que as lágrimas lhe vinham aos olhos; e uma vez lembrou-se de ter tentado dar tapas nas próprias orelhas por ter trapaceado contra si mesma num jogo de críquete que disputava consigo mesma, pois essa criança curiosa adorava fingir que era duas pessoas. “Mas agora não adianta nada”, pensou a pobre Alice, “fingir que sou duas pessoas! Ora, mal sobrou de mim o bastante para fazer uma pessoa respeitável!”","soonhereyefellonalittleglassboxthatwasly~andidontcarewhichhappens":"Logo seu olhar caiu sobre uma caixinha de vidro que estava sob a mesa: abriu-a e encontrou dentro um bolinho muito pequeno, no qual as palavras “Coma-me” estavam lindamente escritas com groselhas. “Bem, vou comê-lo”, disse Alice, “e, se me fizer crescer, poderei alcançar a chave; e, se me fizer encolher, poderei passar por baixo da porta; então, de um jeito ou de outro, chegarei ao jardim, e não me importa o que aconteça!”","sheatealittlebitandsaidanxiouslytohersel~lifetogooninthecommonway":"Comeu um pedacinho e disse ansiosa a si mesma: “Para que lado? Para que lado?”, com a mão sobre o alto da cabeça para sentir em que direção crescia, e ficou muito surpresa ao ver que continuava do mesmo tamanho: na verdade, é o que costuma acontecer quando se come bolo, mas Alice se acostumara tanto a esperar que só coisas extraordinárias acontecessem que lhe parecia sem graça e tolo que a vida continuasse da maneira comum.","soshesettoworkandverysoonfinishedoffthec~rysoonfinishedoffthecake":"Então pôs mãos à obra e logo acabou com o bolo.","curiouserandcuriousercriedaliceshewassom~airofbootseverychristmas":"“Cada vez mais curioso!”, exclamou Alice (estava tão surpresa que, por um momento, esqueceu-se completamente de como falar bem); “agora estou me abrindo como o maior telescópio que já existiu! Adeus, pés!” (pois, quando olhou para os pés, pareciam quase fora de vista, de tão longe que estavam ficando). “Ah, meus pobres pezinhos, quem será que vai calçar suas meias e seus sapatos agora, queridos? Tenho certeza de que eu não vou conseguir! Estarei longe demais para me preocupar com vocês: arranjem-se como puderem... mas preciso ser gentil com eles”, pensou Alice, “senão talvez não andem para onde eu quero ir! Deixe-me ver: darei a eles um par de botas novas todo Natal.”","andshewentonplanningtoherselfhowshewould~oddthedirectionswilllook":"E continuou planejando como faria isso. “Terão que ir pelo correio”, pensou; “e que engraçado vai ser mandar presentes para os próprios pés! E como vão parecer estranhos os endereços!","alicesrightfootesqhearthrugnearthefender~rthefenderwithaliceslove":"Ao Ilustríssimo Pé Direito de Alice,\nTapete da Lareira,\nPerto do Guarda-Fogo,\n(Com o Amor de Alice).","ohdearwhatnonsenseimtalking~earwhatnonsenseimtalking":"Ai, meu Deus, que bobagem estou dizendo!”","justthenherheadstruckagainsttheroofofthe~urriedofftothegardendoor":"Nesse momento sua cabeça bateu no teto do salão: na verdade, estava agora com mais de dois metros e setenta de altura, e logo pegou a chavinha dourada e correu para a porta do jardim.","pooraliceitwasasmuchasshecoulddolyingdow~atdownandbegantocryagain":"Pobre Alice! Era tudo o que conseguia fazer, deitada de lado, olhar com um olho só para dentro do jardim; mas passar por lá era mais impossível do que nunca: sentou-se e começou a chorar de novo.","yououghttobeashamedofyourselfsaidaliceag~dreachinghalfdownthehall":"“Você devia ter vergonha”, disse Alice, “uma menina grande como você” (bem podia dizer isso), “de continuar chorando desse jeito! Pare agora mesmo, estou mandando!” Mas continuou do mesmo jeito, derramando litros e litros de lágrimas, até haver uma grande poça em volta dela, com uns dez centímetros de fundo, que se estendia até a metade do salão.","afteratimesheheardalittlepatteringoffeet~arknessashardashecouldgo":"Passado um tempo, ouviu um leve tamborilar de passos ao longe e enxugou depressa os olhos para ver o que vinha. Era o Coelho Branco que voltava, magnificamente vestido, com um par de luvas brancas de pelica numa mão e um grande leque na outra: vinha trotando com muita pressa, resmungando consigo mesmo: “Ai! a Duquesa, a Duquesa! Ai! como vai ficar furiosa se eu a fizer esperar!” Alice sentia-se tão desesperada que estava pronta a pedir ajuda a qualquer um; assim, quando o Coelho se aproximou, começou, com voz baixa e tímida: “Por favor, senhor...” O Coelho sobressaltou-se violentamente, largou as luvas brancas e o leque e saiu em disparada para a escuridão o mais depressa que pôde.","alicetookupthefanandglovesandasthehallwa~ebeenchangedforanyofthem":"Alice pegou o leque e as luvas e, como o salão estava muito quente, ficou se abanando o tempo todo enquanto falava: “Meu Deus, meu Deus! Como está tudo esquisito hoje! E ontem as coisas iam como de costume. Será que me trocaram durante a noite? Deixe-me pensar: eu era a mesma quando me levantei esta manhã? Quase me parece lembrar que me sentia um pouco diferente. Mas, se não sou a mesma, a pergunta seguinte é: quem, afinal, sou eu? Ah, esse é o grande enigma!” E começou a pensar em todas as crianças que conhecia da sua idade, para ver se poderia ter sido trocada por alguma delas.","imsureimnotadashesaidforherhairgoesinsuc~omethesameastheyusedtodo":"“Tenho certeza de que não sou a Ada”, disse, “pois o cabelo dela faz cachos tão compridos, e o meu não faz cachos de jeito nenhum; e tenho certeza de que não posso ser a Mabel, pois eu sei todo tipo de coisa, e ela, ah! ela sabe tão pouquinho! Além disso, ela é ela, e eu sou eu, e... ai, meu Deus, como tudo isso é confuso! Vou ver se ainda sei tudo o que sabia. Deixe-me ver: quatro vezes cinco são doze, e quatro vezes seis são treze, e quatro vezes sete são... ai, meu Deus! Desse jeito nunca chegarei a vinte! Mas a Tabuada não importa: vamos tentar Geografia. Londres é a capital de Paris, e Paris é a capital de Roma, e Roma... não, está tudo errado, tenho certeza! Devo ter sido trocada pela Mabel! Vou tentar dizer ‘Como faz o pequeno...’ ” e cruzou as mãos no colo como se estivesse recitando a lição e começou a repetir, mas sua voz soou rouca e estranha, e as palavras não saíam como de costume:","howdoththelittlecrocodileimprovehisshini~henileoneverygoldenscale":"“Como faz o pequeno crocodilo\nPara polir a cauda a luzir,\nE derramar as águas do Nilo\nEm cada escama a refulgir!","howcheerfullyheseemstogrinhowneatlysprea~sinwithgentlysmilingjaws":"“Com que alegria parece sorrir,\nCom que capricho abre as garras,\nE acolhe os peixinhos a vir\nCom suas mandíbulas bem amáveis!”","imsurethosearenottherightwordssaidpooral~tiredofbeingallalonehere":"“Tenho certeza de que essas não são as palavras certas”, disse a pobre Alice, e os olhos se encheram de lágrimas de novo enquanto continuava: “Devo ser a Mabel, afinal, e vou ter que ir morar naquela casinha apertada, e ficar quase sem brinquedos, e ah! com um monte de lições para aprender! Não, já decidi: se sou a Mabel, fico aqui embaixo! Não vai adiantar nada eles enfiarem a cabeça aqui e dizerem ‘Suba de novo, querida!’ Vou só olhar para cima e dizer ‘Quem sou eu, então? Digam-me isso primeiro e, se eu gostar de ser essa pessoa, subirei: se não, ficarei aqui embaixo até ser outra pessoa’... mas, ai, meu Deus!”, exclamou Alice, com uma súbita explosão de lágrimas, “como eu queria que eles enfiassem a cabeça aqui! Estou tão cansada de ficar sozinha aqui!”","asshesaidthisshelookeddownatherhandsandw~dshrinkingawayaltogether":"Ao dizer isso, olhou para as mãos e surpreendeu-se ao ver que tinha calçado uma das luvinhas brancas de pelica do Coelho enquanto falava. “Como posso ter feito isso?”, pensou. “Devo estar encolhendo de novo.” Levantou-se e foi até a mesa para se medir por ela e descobriu que, tanto quanto podia calcular, estava agora com uns sessenta centímetros de altura e continuava encolhendo depressa: logo descobriu que a causa era o leque que segurava, e largou-o apressadamente, a tempo de evitar sumir de vez.","thatwasanarrowescapesaidaliceagooddealfr~declareitstoobadthatitis":"“Foi por um triz!”, disse Alice, bastante assustada com a mudança súbita, mas muito contente por se descobrir ainda existindo; “e agora, ao jardim!” e correu a toda a velocidade de volta à portinha: mas, ai!, a portinha estava fechada de novo, e a chavinha dourada continuava sobre a mesa de vidro, como antes, “e as coisas estão piores do que nunca”, pensou a pobre menina, “pois nunca fui tão pequena como agora, nunca! E, francamente, é muito ruim, é sim!”","asshesaidthesewordsherfootslippedandinan~ptwhenshewasninefeethigh":"Ao dizer essas palavras, seu pé escorregou e, no instante seguinte, splash! estava com água salgada até o queixo. Sua primeira ideia foi que tinha caído de algum modo no mar, “e nesse caso posso voltar de trem”, disse consigo mesma. (Alice tinha ido à praia uma vez na vida e chegara à conclusão geral de que, aonde quer que se vá no litoral inglês, encontra-se uma porção de cabines de banho no mar, algumas crianças cavando na areia com pás de madeira, depois uma fileira de pensões e, atrás delas, uma estação de trem.) Contudo, logo percebeu que estava na poça de lágrimas que havia chorado quando tinha dois metros e setenta de altura.","iwishihadntcriedsomuchsaidaliceassheswam~ereverythingisqueertoday":"“Quem me dera não ter chorado tanto!”, disse Alice, enquanto nadava tentando achar a saída. “Agora serei castigada por isso, suponho, morrendo afogada nas minhas próprias lágrimas! Será mesmo uma coisa esquisita! Mas, enfim, tudo é esquisito hoje.”","justthensheheardsomethingsplashingabouti~thadslippedinlikeherself":"Nesse momento ouviu algo chapinhando na poça, um pouco adiante, e nadou mais para perto para ver o que era: a princípio pensou que devia ser uma morsa ou um hipopótamo, mas depois lembrou-se de como estava pequena agora e logo percebeu que era apenas um camundongo que escorregara para dentro como ela.","woulditbeofanyusenowthoughtalicetospeakt~ttleeyesbutitsaidnothing":"“Será que adiantaria alguma coisa”, pensou Alice, “falar com este camundongo? Está tudo tão fora do comum aqui embaixo que acho muito provável que ele fale: de qualquer modo, não custa tentar.” Então começou: “Ó Camundongo, o senhor sabe o caminho para sair desta poça? Estou muito cansada de nadar por aqui, ó Camundongo!” (Alice achou que devia ser essa a maneira certa de falar com um camundongo: nunca fizera tal coisa, mas lembrava-se de ter visto na Gramática Latina do irmão: “Um camundongo — de um camundongo — a um camundongo — um camundongo — ó camundongo!”) O Camundongo olhou para ela com certa curiosidade e pareceu-lhe piscar com um dos olhinhos, mas não disse nada.","perhapsitdoesntunderstandenglishthoughta~teforgotyoudidntlikecats":"“Talvez ele não entenda inglês”, pensou Alice; “ouso dizer que é um camundongo francês, vindo com Guilherme, o Conquistador.” (Pois, com todo o seu conhecimento de história, Alice não tinha noção muito clara de há quanto tempo as coisas haviam acontecido.) Então começou de novo: “Où est ma chatte?”, que era a primeira frase do seu livro de lições de francês. O Camundongo deu um salto súbito para fora da água e pareceu tremer todo de medo. “Ah, peço perdão!”, exclamou Alice depressa, receando ter ferido os sentimentos do pobre animal. “Esqueci completamente que o senhor não gosta de gatos.”","notlikecatscriedthemouseinashrillpassion~ldyoulikecatsifyouwereme":"“Não gosto de gatos!”, exclamou o Camundongo, com voz estridente e apaixonada. “A senhorita gostaria de gatos se estivesse no meu lugar?”","wellperhapsnotsaidaliceinasoothingtonedo~eranymoreifyoudrathernot":"“Bem, talvez não”, disse Alice em tom apaziguador: “não fique zangado por isso. E, no entanto, queria poder lhe mostrar a nossa gata Dinah: acho que o senhor passaria a gostar de gatos se pudesse vê-la. É uma coisinha tão querida e quieta”, continuou Alice, meio para si mesma, enquanto nadava preguiçosamente na poça, “e fica ronronando tão bonitinho junto ao fogo, lambendo as patas e lavando o rosto... e é uma coisinha tão macia de embalar... e é tão boa de caça aos ratos... ai, peço perdão!”, exclamou Alice de novo, pois desta vez o Camundongo estava todo eriçado, e ela teve certeza de que ele estava realmente ofendido. “Não falaremos mais nela, se o senhor preferir.”","weindeedcriedthemousewhowastremblingdown~ontletmehearthenameagain":"“Falaremos!”, exclamou o Camundongo, que tremia até a ponta da cauda. “Como se eu fosse tratar de tal assunto! Nossa família sempre odiou os gatos: criaturas nojentas, baixas e vulgares! Que eu não ouça esse nome outra vez!”","iwontindeedsaidaliceinagreathurrytochang~mmotioninthepoolasitwent":"“Não ouvirá, de fato!”, disse Alice, com muita pressa de mudar de assunto. “O senhor gosta... gosta... de... de cães?” O Camundongo não respondeu, então Alice continuou, ansiosa: “Há um cachorrinho tão simpático perto da nossa casa que eu gostaria de lhe mostrar! Um terrier pequeno, de olhos brilhantes, sabe, com uns pelos castanhos tão compridos e encaracolados! E ele busca as coisas quando a gente joga, e se senta nas patas traseiras para pedir o jantar, e toda sorte de coisas... não me lembro nem da metade... e pertence a um fazendeiro, sabe, que diz que é tão útil que vale cem libras! Diz que ele mata todos os ratos e... ai, meu Deus!”, exclamou Alice em tom de tristeza, “receio tê-lo ofendido de novo!” Pois o Camundongo se afastava dela a nado o mais depressa que podia, causando uma grande agitação na poça à medida que ia.","soshecalledsoftlyafteritmousedeardocomeb~dwhyitisihatecatsanddogs":"Então chamou-o baixinho: “Querido Camundongo! Volte, por favor, e não falaremos de gatos nem de cães, se o senhor não gosta deles!” Quando o Camundongo ouviu isso, deu meia-volta e nadou devagar de volta até ela: tinha o rosto bem pálido (de raiva, pensou Alice) e disse, com voz baixa e trêmula: “Vamos até a margem, e então lhe contarei a minha história, e a senhorita compreenderá por que odeio gatos e cães.”","itwashightimetogoforthepoolwasgettingqui~wholepartyswamtotheshore":"Já era hora de ir, pois a poça estava ficando lotada de aves e bichos que haviam caído nela: havia um Pato e um Dodô, um Louro e uma Águia-bebê, e várias outras criaturas curiosas. Alice abriu o caminho, e todo o grupo nadou até a margem."}$tr$::jsonb, 50)
on conflict (texto_slug, idioma) do update set cobertura = excluded.cobertura, credito = excluded.credito, titulos = excluded.titulos, paragrafos = excluded.paragrafos, total_paragrafos = excluded.total_paragrafos, atualizado_em = now();

-- lewis-carroll_through-the-looking-glass (6 parágrafos, excerpt)
insert into public.livros_traducoes (texto_slug, idioma, cobertura, credito, titulos, paragrafos, total_paragrafos) values ('lewis-carroll_through-the-looking-glass', 'pt', 'trecho', 'Tradução para o português do Brasil feita por IA (Claude) para o Alice''s Library; trecho de abertura, revisão pendente.', $tr${"lookingglasshouse":"A casa do espelho"}$tr$::jsonb, $tr${"onethingwascertainthatthewhitekittenhadh~ehadanyhandinthemischief":"Uma coisa era certa: a gatinha branca não tinha nada a ver com aquilo — a culpa era toda da gatinha preta. Pois a gatinha branca estivera tendo o rosto lavado pela gata velha durante o último quarto de hora (e suportando muito bem, considerando); de modo que, como você vê, ela não podia ter tido nenhuma mão na travessura.","thewaydinahwashedherchildrensfaceswasthi~titwasallmeantforitsgood":"O jeito como Dinah lavava o rosto dos filhos era este: primeiro prendia a pobrezinha pela orelha com uma pata, e depois, com a outra, esfregava-lhe o rosto todo, ao contrário, começando pelo nariz; e justo agora, como eu disse, ela estava trabalhando duro na gatinha branca, que estava deitada bem quietinha, tentando ronronar — sem dúvida sentindo que tudo aquilo era para o seu bem.","buttheblackkittenhadbeenfinishedwithearl~teritsowntailinthemiddle":"Mas a gatinha preta fora despachada mais cedo, naquela tarde, e assim, enquanto Alice estava sentada, encolhida num canto da grande poltrona, meio falando sozinha e meio dormindo, a gatinha tinha se divertido a valer com o novelo de lã que Alice tentava enrolar, rolando-o para cima e para baixo até que ele se desfizesse todo de novo; e lá estava ele, espalhado pelo tapete da lareira, todo nós e emaranhados, com a gatinha correndo atrás do próprio rabo no meio.","ohyouwickedlittlethingcriedalicecatching~uldbegladtohelpifitmight":"— Ah, sua coisinha malvada! — exclamou Alice, pegando a gatinha e dando-lhe um beijinho para que entendesse que estava em desgraça. — Realmente, Dinah devia ter lhe ensinado melhores maneiras! Devia, Dinah, você sabe que devia! — acrescentou, olhando com ar de censura para a gata velha e falando com a voz mais zangada que conseguiu — e então voltou aos tropeções para a poltrona, levando consigo a gatinha e a lã, e começou a enrolar o novelo de novo. Mas não avançava muito depressa, pois falava o tempo todo, às vezes com a gatinha, às vezes consigo mesma. Kitty ficou sentada muito recatada no seu colo, fingindo acompanhar o progresso do enrolar, e de vez em quando estendendo uma pata e tocando de leve o novelo, como se fosse feliz em ajudar, se pudesse.","doyouknowwhattomorrowiskittyalicebeganyo~yardsofitgotunwoundagain":"— Sabe que dia é amanhã, Kitty? — começou Alice. — Você teria adivinhado se estivesse na janela comigo — só que Dinah estava te arrumando, e você não pôde. Eu estava vendo os meninos juntarem gravetos para a fogueira — e ela precisa de muitos gravetos, Kitty! Só que ficou tão frio, e nevou tanto, que eles tiveram de parar. Não faz mal, Kitty, amanhã nós vamos ver a fogueira. — Aqui Alice deu duas ou três voltas de lã no pescoço da gatinha, só para ver como ficava: isso provocou uma correria em que o novelo rolou para o chão, e metros e metros de lã se desenrolaram de novo.","doyouknowiwassoangrykittyalicewentonasso~orstedwhileiwasntlooking":"— Sabe, eu fiquei tão zangada, Kitty — continuou Alice, assim que se acomodaram de novo —, quando vi todo o estrago que você tinha feito, que quase abri a janela e te pus para fora, na neve! E você teria merecido, sua queridinha travessa! O que tem a dizer em sua defesa? Agora não me interrompa! — prosseguiu, erguendo um dedo. — Vou lhe dizer todos os seus defeitos. Número um: você miou duas vezes enquanto Dinah lavava seu rosto esta manhã. Agora não pode negar, Kitty: eu ouvi! O que é que você diz? — (fingindo que a gatinha falava.) — A pata dela entrou no seu olho? Bem, a culpa é sua, por manter os olhos abertos — se você os tivesse fechado bem fechados, não teria acontecido. Agora chega de desculpas, e escute! Número dois: você puxou Snowdrop pelo rabo bem na hora em que eu tinha posto o pires de leite diante dela! O quê, você estava com sede, é? Como sabe que ela não estava com sede também? Agora o número três: você desenrolou toda a lã enquanto eu não estava olhando!"}$tr$::jsonb, 6)
on conflict (texto_slug, idioma) do update set cobertura = excluded.cobertura, credito = excluded.credito, titulos = excluded.titulos, paragrafos = excluded.paragrafos, total_paragrafos = excluded.total_paragrafos, atualizado_em = now();

-- mark-twain_a-connecticut-yankee-in-king-arthurs-court (10 parágrafos, excerpt)
insert into public.livros_traducoes (texto_slug, idioma, cobertura, credito, titulos, paragrafos, total_paragrafos) values ('mark-twain_a-connecticut-yankee-in-king-arthurs-court', 'pt', 'trecho', 'Tradução para o português do Brasil feita por IA (Claude) para o Alice''s Library; trecho de abertura, revisão pendente.', $tr${"awordofexplanation":"Uma palavra de explicação"}$tr$::jsonb, $tr${"itwasinwarwickcastlethaticameacrossthecu~eroranyothercommonmatter":"Foi no Castelo de Warwick que topei com o curioso forasteiro de quem vou falar. Atraíram-me nele três coisas: a sua simplicidade cândida, a sua maravilhosa familiaridade com armaduras antigas e o repouso de sua companhia — pois era ele quem falava o tempo todo. Juntamo-nos, como fazem as pessoas modestas, na cauda do rebanho que era conduzido pela visita, e ele logo começou a dizer coisas que me interessaram. Enquanto falava, suave, agradável, fluente, parecia ir se afastando imperceptivelmente deste mundo e deste tempo, rumo a alguma era remota e a um velho país esquecido; e assim foi tecendo em torno de mim tal encantamento que me parecia mover-me entre espectros, sombras, pó e bolor de uma cinzenta antiguidade, em conversa com uma relíquia dela! Exatamente como eu falaria dos meus amigos ou inimigos pessoais mais próximos, ou dos meus vizinhos mais familiares, falava ele de Sir Bedivere, Sir Bors de Ganis, Sir Lancelot do Lago, Sir Galaaz e de todos os outros grandes nomes da Távola Redonda — e como parecia velho, velho, indizivelmente velho, e desbotado, e seco, e bolorento, e antigo, à medida que prosseguia! Logo ele se voltou para mim e disse, como quem fala do tempo ou de qualquer outro assunto banal —","youknowabouttransmigrationofsoulsdoyoukn~ositionofepochsandbodies":"“O senhor conhece a transmigração das almas; conhece a transposição das épocas — e dos corpos?”","isaidihadnotheardofithewassolittleintere~iceofthesalariedcicerone":"Respondi que nunca ouvira falar. Ele estava tão pouco interessado — como quando as pessoas falam do tempo — que nem reparou se lhe dei resposta ou não. Houve meio momento de silêncio, logo interrompido pela voz monótona do cicerone assalariado:","ancienthauberkdateofthesixthcenturytimeo~ouslybycromwellssoldiers":"“Antiga cota de malha, do século VI, tempo do Rei Artur e da Távola Redonda; diz-se ter pertencido ao cavaleiro Sir Sagramor, o Desejoso; observem o orifício redondo através da malha, no peito esquerdo; não se explica; supõe-se ter sido feito por uma bala depois da invenção das armas de fogo — talvez maldosamente pelos soldados de Cromwell.”","myacquaintancesmilednotamodernsmilebuton~teredapparentlytohimself":"Meu conhecido sorriu — não um sorriso moderno, mas um que deve ter saído do uso geral muitos, muitos séculos atrás — e murmurou, aparentemente consigo mesmo:","wityewellisawitdonethenafterapauseaddedi~rapauseaddedididitmyself":"“Sabei bem que vi isso ser feito.” Depois, após uma pausa, acrescentou: “Eu mesmo o fiz.”","bythetimeihadrecoveredfromtheelectricsur~iseofthisremarkhewasgone":"Quando me refiz da surpresa elétrica dessa observação, ele já se fora.","allthateveningisatbymyfireatthewarwickar~hiswhichherefollowstowit":"Toda aquela noite fiquei sentado junto ao fogo no Warwick Arms, mergulhado num sonho dos tempos antigos, enquanto a chuva batia nas janelas e o vento rugia pelos beirais e cantos. De quando em quando mergulhava no encantador livro do velho Sir Thomas Malory, banqueteava-me em seu rico festim de prodígios e aventuras, aspirava a fragrância de seus nomes obsoletos, e tornava a sonhar. Chegada afinal a meia-noite, li outro conto, como saideira — este que aqui segue, a saber:","howsirlauncelotslewtwogiantsandmadeacast~giantsandmadeacastlefree":"Como Sir Lancelot matou dois gigantes e libertou um castelo","anonwithalcamethereuponhimtwogreatgiants~adstrickenthemtotheearth":"Logo em seguida vieram sobre ele dois grandes gigantes, bem armados, exceto as cabeças, com duas horríveis clavas nas mãos. Sir Lancelot pôs o escudo diante de si e desviou o golpe de um dos gigantes, e com a espada lhe fendeu a cabeça em duas. Quando o companheiro viu isso, fugiu como louco, por medo dos golpes horríveis, e Sir Lancelot atrás dele com toda a sua força, e feriu-o no ombro, e fendeu-o até o meio. Então Sir Lancelot entrou no salão, e vieram diante dele três vintenas de damas e donzelas, e todas se ajoelharam diante dele, e agradeceram a Deus e a ele a sua libertação. Pois, senhor, disseram elas, a maior parte de nós está aqui há sete anos como prisioneira deles, e trabalhamos toda sorte de obras de seda para nosso sustento, e somos todas grandes damas de nascimento, e bendito seja o tempo, cavaleiro, em que nasceste; pois fizeste a maior honra que jamais fez cavaleiro no mundo, disso daremos testemunho, e todas te rogamos que nos digas o teu nome, para que possamos dizer a nossos amigos quem nos tirou da prisão. Belas donzelas, disse ele, meu nome é Sir Lancelot do Lago. E assim se despediu delas e as encomendou a Deus. E então montou o seu cavalo, e cavalgou por muitas terras estranhas e selvagens, e por muitas águas e vales, e mal alojado esteve. E por fim, por ventura, aconteceu-lhe chegar, ao cair da noite, a um belo pátio, e ali encontrou uma velha dama que o hospedou de boa vontade, e ali teve boa acolhida para si e para o cavalo. E quando foi tempo, o seu anfitrião o levou a um belo sótão sobre o portão, para seu leito. Ali Sir Lancelot se desarmou, e pôs o arnês junto de si, e foi deitar-se, e logo adormeceu. Pouco depois veio alguém a cavalo e bateu ao portão com grande pressa. E quando Sir Lancelot ouviu isso levantou-se e olhou pela janela, e viu, à luz da lua, três cavaleiros virem cavalgando atrás daquele homem, e os três o açoitaram ao mesmo tempo com espadas, e aquele cavaleiro voltou-se contra eles, cavalheirescamente, e defendeu-se. Em verdade, disse Sir Lancelot, aquele cavaleiro ali eu ajudarei, pois seria vergonha para mim ver três cavaleiros contra um, e se ele for morto sou partícipe de sua morte. E com isso pegou o arnês e saiu por uma janela, descendo por um lençol, até os quatro cavaleiros, e então Sir Lancelot disse em alta voz: Voltai-vos, cavaleiros, para mim, e deixai a luta com aquele cavaleiro. E então os três deixaram Sir Kay e voltaram-se para Sir Lancelot, e começou ali grande batalha, pois desmontaram os três e desferiram muitos golpes em Sir Lancelot, e o assaltaram por todos os lados. Então Sir Kay preparou-se para ajudar Sir Lancelot. Não, senhor, disse este, não quero vossa ajuda; portanto, se quereis que eu vos ajude, deixai-me só com eles. Sir Kay, para comprazer o cavaleiro, permitiu-lhe fazer a sua vontade, e assim ficou de lado. E então, em menos de seis golpes, Sir Lancelot os havia derrubado por terra."}$tr$::jsonb, 10)
