-- mark-twain_the-prince-and-the-pauper (1 parágrafos, excerpt)
insert into public.livros_traducoes (texto_slug, idioma, cobertura, credito, titulos, paragrafos, total_paragrafos) values ('mark-twain_the-prince-and-the-pauper', 'pt', 'trecho', 'Tradução para o português do Brasil feita por IA (Claude) para o Alice''s Library; trecho de abertura, revisão pendente.', $tr${"thebirthoftheprinceandthepauper":"O nascimento do príncipe e do pobre"}$tr$::jsonb, $tr${"intheancientcityoflondononacertainautumn~totroublewithhispresence":"Na antiga cidade de Londres, num certo dia de outono do segundo quarto do século XVI, nasceu um menino numa família pobre de sobrenome Canty, que não o queria. No mesmo dia nasceu outra criança inglesa numa família rica de sobrenome Tudor, que o queria. Toda a Inglaterra o queria também. A Inglaterra tanto o desejara, tanto esperara por ele e tanto rogara a Deus por ele que, agora que ele de fato chegara, o povo quase enlouqueceu de alegria. Meros conhecidos se abraçavam, se beijavam e choravam. Todos tiraram feriado, e grandes e pequenos, ricos e pobres, banquetearam-se, dançaram e cantaram, e ficaram bem alegres; e continuaram assim por dias e noites a fio. De dia, Londres era um espetáculo, com alegres bandeiras tremulando em cada sacada e telhado, e esplêndidos cortejos desfilando pelas ruas. De noite, era de novo um espetáculo, com suas grandes fogueiras em cada esquina e seus bandos de foliões se divertindo em torno delas. Não se falava em toda a Inglaterra senão do novo bebê, Edward Tudor, Príncipe de Gales, que jazia envolto em sedas e cetins, inconsciente de toda aquela agitação, sem saber que grandes lordes e damas o serviam e velavam por ele — e sem se importar, aliás. Mas não se falava do outro bebê, Tom Canty, envolto em seus pobres trapos, exceto na família de miseráveis a quem ele acabara de vir incomodar com sua presença."}$tr$::jsonb, 1)
on conflict (texto_slug, idioma) do update set cobertura = excluded.cobertura, credito = excluded.credito, titulos = excluded.titulos, paragrafos = excluded.paragrafos, total_paragrafos = excluded.total_paragrafos, atualizado_em = now();

-- mary-shelley_frankenstein (6 parágrafos, excerpt)
insert into public.livros_traducoes (texto_slug, idioma, cobertura, credito, titulos, paragrafos, total_paragrafos) values ('mary-shelley_frankenstein', 'pt', 'trecho', 'Tradução para o português do Brasil feita por IA (Claude) para o Alice''s Library; trecho de abertura, revisão pendente.', $tr${"letteri":"Carta I"}$tr$::jsonb, $tr${"tomrssavilleengland~tomrssavilleengland":"À Sra. Saville, Inglaterra.","stpetersburghdec11th17~stpetersburghdec11th17":"São Petersburgo, 11 de dezembro de 17—.","youwillrejoicetohearthatnodisasterhasacc~hesuccessofmyundertaking":"A senhora ficará feliz em saber que nenhum desastre acompanhou o início de um empreendimento que via com tão maus presságios. Cheguei aqui ontem; e minha primeira tarefa é assegurar à minha querida irmã o meu bem-estar e a crescente confiança que tenho no êxito de minha empresa.","iamalreadyfarnorthoflondonandasiwalkinth~yanundertakingsuchasmine":"Já estou muito ao norte de Londres; e, enquanto caminho pelas ruas de Petersburgo, sinto uma fria brisa do norte tocar-me as faces, que me retesa os nervos e me enche de deleite. Você compreende esta sensação? Essa brisa, que viajou desde as regiões para as quais avanço, dá-me um antegosto daqueles climas gelados. Animados por esse vento promissor, meus devaneios tornam-se mais fervorosos e vívidos. Tento em vão persuadir-me de que o polo é a sede do gelo e da desolação; ele se apresenta sempre à minha imaginação como a região da beleza e do deleite. Ali, Margaret, o sol é sempre visível; seu largo disco roça o horizonte, difundindo um esplendor perpétuo. Ali — pois, com a tua licença, minha irmã, hei de depositar alguma confiança nos navegadores que me precederam —, ali a neve e o gelo são banidos; e, navegando sobre um mar calmo, podemos ser levados a uma terra que supera em maravilhas e em beleza todas as regiões até hoje descobertas no globo habitável. Seus produtos e feições podem não ter exemplo, assim como os fenômenos dos corpos celestes decerto não o têm nessas solidões ignoradas. O que não se pode esperar de um país de luz eterna? Posso ali descobrir o poder prodigioso que atrai a agulha; e posso regular mil observações celestes, que requerem apenas esta viagem para que suas aparentes excentricidades se tornem consistentes para sempre. Saciarei minha ardente curiosidade com a vista de uma parte do mundo jamais visitada, e poderei pisar uma terra nunca antes marcada pelo pé do homem. Esses são meus atrativos, e bastam para vencer todo temor do perigo ou da morte, e para induzir-me a começar esta laboriosa viagem com a alegria que sente uma criança ao embarcar num barquinho, com seus companheiros de folguedo, numa expedição de descobrimento rio acima, pelo rio de sua terra. Mas, supondo que todas essas conjecturas sejam falsas, você não pode contestar o inestimável benefício que concederei a toda a humanidade, até a última geração, descobrindo uma passagem perto do polo para aqueles países, aos quais hoje se requerem tantos meses para chegar; ou desvendando o segredo do ímã, o que, se é que é possível, só pode ser realizado por um empreendimento como o meu.","thesereflectionshavedispelledtheagitatio~toembarkinaseafaringlife":"Essas reflexões dissiparam a agitação com que comecei esta carta, e sinto o coração arder num entusiasmo que me eleva aos céus; pois nada contribui tanto para tranquilizar o espírito quanto um propósito firme — um ponto em que a alma possa fixar o seu olho intelectual. Esta expedição foi o sonho predileto de meus primeiros anos. Li com ardor os relatos das várias viagens feitas na perspectiva de chegar ao Pacífico Norte pelos mares que circundam o polo. Talvez você se lembre de que uma história de todas as viagens feitas com fins de descobrimento compunha toda a biblioteca de nosso bom tio Thomas. Minha educação foi negligenciada, mas eu era apaixonado pela leitura. Esses volumes eram meu estudo dia e noite, e a familiaridade com eles aumentou o pesar que eu sentira, quando criança, ao saber que a ordem de meu pai moribundo proibira meu tio de permitir que eu abraçasse a vida do mar.","thesevisionsfadedwheniperusedforthefirst~hanneloftheirearlierbent":"Essas visões se desvaneceram quando li, pela primeira vez, aqueles poetas cujas efusões enlevaram minha alma e a elevaram ao céu. Tornei-me também poeta e, por um ano, vivi num Paraíso de minha própria criação; imaginei que também eu poderia obter um nicho no templo onde os nomes de Homero e Shakespeare são consagrados. Você conhece bem o meu fracasso e o quanto me pesou a decepção. Mas justamente então herdei a fortuna de meu primo, e meus pensamentos voltaram ao canal de sua inclinação anterior."}$tr$::jsonb, 6)
