-- robert-louis-stevenson_kidnapped (10 parágrafos, excerpt)
insert into public.livros_traducoes (texto_slug, idioma, cobertura, credito, titulos, paragrafos, total_paragrafos) values ('robert-louis-stevenson_kidnapped', 'pt', 'trecho', 'Tradução para o português do Brasil feita por IA (Claude) para o Alice''s Library; trecho de abertura, revisão pendente.', $tr${"isetoffuponmyjourneytothehouseofshaws":"Parto rumo à casa de Shaws"}$tr$::jsonb, $tr${"iwillbeginthestoryofmyadventureswithacer~ginningtoariseanddieaway":"Começarei a história de minhas aventuras numa certa manhã do início de junho do ano da graça de 1751, quando tirei pela última vez a chave da porta da casa de meu pai. O sol começava a bater no topo dos montes quando desci a estrada; e, quando cheguei à casa paroquial, os melros já assobiavam nos lilases do jardim, e a névoa que pairava em torno do vale na hora da alvorada começava a subir e a dissipar-se.","mrcampbelltheministerofessendeanwaswaiti~appeditkindlyunderhisarm":"O sr. Campbell, ministro de Essendean, esperava-me junto ao portão do jardim, bom homem! Perguntou-me se eu já tomara o desjejum; e, ouvindo que não me faltava nada, tomou minha mão entre as suas e meteu-a com carinho debaixo do braço.","welldavieladsaidheiwillgowithyouasfarast~antowalkforwardinsilence":"— Pois bem, Davie, rapaz — disse ele —, vou contigo até o vau, para pôr-te a caminho. — E começamos a andar em silêncio.","areyesorrytoleaveessendeansaidheafterawh~sendeansaidheafterawhile":"— Tens pena de deixar Essendean? — disse ele, passado algum tempo.","whysirsaidiifiknewwhereiwasgoingorwhatwa~ingiwouldgowithagoodwill":"— Ora, senhor — disse eu —, se eu soubesse para onde vou, ou o que provavelmente será de mim, dir-lhe-ia com franqueza. Essendean é de fato um bom lugar, e fui muito feliz aqui; mas nunca estive em nenhum outro. Meu pai e minha mãe, já que ambos estão mortos, não ficarei mais perto deles em Essendean do que no reino da Hungria, e, para falar a verdade, se eu pensasse ter uma chance de melhorar de sorte onde vou, iria de bom grado.","aysaidmrcampbellverywelldaviethenitbehov~ndbewelllivedwherehegoes":"— Sim? — disse o sr. Campbell. — Muito bem, Davie. Então me cabe dizer-te a tua sorte, ou até onde eu possa. Quando tua mãe se foi, e teu pai (o digno e cristão homem) começou a adoecer para o seu fim, confiou-me uma certa carta, que disse ser a tua herança. ‘Logo que eu me for’, disse ele, ‘e a casa estiver arrumada e os haveres dispostos’ (o que tudo, Davie, foi feito), ‘entregue esta carta nas mãos de meu rapaz e ponha-o a caminho da casa de Shaws, não longe de Cramond. É de lá que eu vim’, disse ele, ‘e é onde convém que meu rapaz volte. É um moço sério’, disse teu pai, ‘e bom caminhante; e não duvido que chegará a salvo e viverá bem onde for.’","thehouseofshawsicriedwhathadmypoorfather~rtodowiththehouseofshaws":"— A casa de Shaws! — exclamei. — Que tinha meu pobre pai a ver com a casa de Shaws?","naysaidmrcampbellwhocantellthatforasuret~handofourdepartedbrother":"— Não — disse o sr. Campbell —, quem pode dizê-lo com certeza? Mas o nome dessa família, Davie, rapaz, é o nome que tu levas: os Balfour de Shaws, casa antiga, honesta, respeitável, talvez decaída nestes últimos dias. Teu pai também era homem de letras, como convinha à sua posição; ninguém dirigia a escola com mais proveito; nem tinha ele o jeito ou a fala de um dómine qualquer; mas (como tu mesmo hás de lembrar) eu sempre tive prazer em tê-lo na casa paroquial para conhecer os fidalgos; e os da minha própria casa, Campbell de Kilrennet, Campbell de Dunswire, Campbell de Minch e outros, todos cavalheiros bem conhecidos, tinham prazer em sua companhia. Por fim, para pôr diante de ti todos os elementos deste negócio, eis aqui a própria carta testamentária, subscrita de próprio punho pelo nosso irmão falecido.","hegavemetheletterwhichwasaddressedinthes~inieintheforestofettrick":"Deu-me a carta, que trazia o seguinte endereço: “Às mãos de Ebenezer Balfour, Esquire, de Shaws, em sua casa de Shaws, serão entregues por meu filho, David Balfour.” Meu coração batia forte diante da grande perspectiva que de súbito se abria a um rapaz de dezessete anos, filho de um pobre dómine de aldeia na Floresta de Ettrick.","mrcampbellistammeredandifyouwereinmyshoe~uwereinmyshoeswouldyougo":"— Sr. Campbell — balbuciei —, se o senhor estivesse no meu lugar, iria?"}$tr$::jsonb, 10)
