-- robert-louis-stevenson_treasure-island (9 parágrafos, excerpt)
insert into public.livros_traducoes (texto_slug, idioma, cobertura, credito, titulos, paragrafos, total_paragrafos) values ('robert-louis-stevenson_treasure-island', 'pt', 'trecho', 'Tradução para o português do Brasil feita por IA (Claude) para o Alice''s Library; trecho de abertura, revisão pendente.', $tr${"attheadmiralbenbow":"Na estalagem Almirante Benbow"}$tr$::jsonb, $tr${"squiretrelawneydoctorliveseyandtherestof~uphislodgingunderourroof":"O fidalgo Trelawney, o doutor Livesey e os demais cavalheiros, tendo-me pedido que escrevesse todos os pormenores sobre a Ilha do Tesouro, do princípio ao fim, sem guardar nada senão a localização da ilha, e isso apenas porque ainda há tesouro por levantar, tomo da pena neste ano da graça de 17—, e volto ao tempo em que meu pai mantinha a estalagem Almirante Benbow, e o velho marinheiro moreno, com o talho de sabre, veio pela primeira vez alojar-se sob o nosso teto.","irememberhimasifitwereyesterdayashecamep~thesangsooftenafterwards":"Lembro-me dele como se fosse ontem, quando veio caminhando pesadamente até a porta da estalagem, com o baú de marinheiro atrás, num carrinho de mão; um homem alto, forte, corpulento, cor de noz; o rabicho besuntado de alcatrão caindo-lhe sobre os ombros do casaco azul sujo; as mãos calejadas e cheias de cicatrizes, de unhas negras e quebradas, e o talho de sabre atravessando uma face, de um branco sujo e lívido. Lembro-me de que ele olhou em volta da enseada, assobiando consigo mesmo, e depois rompeu naquela velha canção do mar que tantas vezes cantaria depois:","fifteenmenonthedeadmanschestyohohoandabo~estyohohoandabottleofrum":"“Quinze homens no baú do morto,\nIô-hô-hô e uma garrafa de rum!”","inthehigholdtotteringvoicethatseemedtoha~liffsandupatoursignboard":"na voz alta, velha e trêmula que parecia ter sido afinada e quebrada nas barras do cabrestante. Depois bateu à porta com um pedaço de pau semelhante a uma alavanca que trazia e, quando meu pai apareceu, pediu rudemente um copo de rum. Quando lhe trouxeram, bebeu-o devagar, como um apreciador, demorando-se no sabor e ainda olhando em volta, para os penhascos e para a nossa tabuleta.","thisisahandycovesaysheatlengthandapleasa~dgrogshopmuchcompanymate":"— Esta é uma enseada cômoda — disse ele, por fim — e uma taverna bem situada e agradável. Muita freguesia, camarada?","myfathertoldhimnoverylittlecompanythemor~companythemorewasthepity":"Meu pai disse que não, muito pouca freguesia, e era uma pena.","wellthensaidhethisistheberthformehereyou~kingasfierceasacommander":"— Pois bem, então — disse ele —, este é o poiso para mim. Ei, você, camarada — gritou ao homem que empurrava o carrinho —, encoste aqui e ajude a levantar meu baú. Vou ficar aqui um tempo — continuou. — Sou um homem simples; rum, toicinho e ovos é o que quero, e aquele promontório lá em cima para vigiar os navios ao largo. Como podem me chamar? Podem me chamar de capitão. Ah, já vi o que querem... tomem — e atirou três ou quatro moedas de ouro na soleira. — Podem me avisar quando eu tiver gasto isso — disse, com ar feroz como o de um comandante.","andindeedbadashisclotheswereandcoarselya~llwecouldlearnofourguest":"E, de fato, por piores que fossem suas roupas e por mais grosseiro que fosse o seu falar, não tinha nada da aparência de um homem que navegara como marinheiro raso, mas parecia um imediato ou um capitão, acostumado a ser obedecido ou a bater. O homem que veio com o carrinho nos contou que o coche do correio o deixara na manhã anterior no Royal George; que ele perguntara quais estalagens havia ao longo da costa e, ouvindo falar bem da nossa, suponho, e descrevê-la como isolada, escolhera-a entre as outras para sua residência. E isso foi tudo o que pudemos saber de nosso hóspede.","hewasaverysilentmanbycustomalldayhehungr~inawayasharerinhisalarms":"Era por hábito um homem muito calado. Durante o dia todo rondava a enseada ou os penhascos, com uma luneta de latão; à noite sentava-se num canto da sala junto ao fogo e bebia rum com água muito forte. Quase sempre não falava quando lhe falavam; apenas erguia o olhar, súbito e feroz, e soprava pelo nariz como uma sirene de nevoeiro; e nós e o pessoal que frequentava a casa logo aprendemos a deixá-lo em paz. Todos os dias, ao voltar do passeio, perguntava se algum homem do mar passara pela estrada. A princípio pensamos que era a falta de companhia de sua própria espécie que o fazia perguntar isso; mas por fim começamos a ver que desejava evitá-los. Quando um marinheiro se hospedava no Almirante Benbow (como de quando em quando alguns faziam, a caminho de Bristol pela estrada da costa), ele o espiava pela porta de cortina antes de entrar na sala; e com certeza ficava calado como um rato quando havia algum presente. Para mim, ao menos, não havia segredo nessa questão; pois eu era, de certo modo, partícipe de seus sobressaltos."}$tr$::jsonb, 9)
