-- thomas-hardy_the-mayor-of-casterbridge (6 parágrafos, excerpt)
insert into public.livros_traducoes (texto_slug, idioma, cobertura, credito, titulos, paragrafos, total_paragrafos) values ('thomas-hardy_the-mayor-of-casterbridge', 'pt', 'trecho', 'Tradução para o português do Brasil feita por IA (Claude) para o Alice''s Library; trecho de abertura, revisão pendente.', $tr${"chapteri":"Capítulo I"}$tr$::jsonb, $tr${"oneeveningoflatesummerbeforethenineteent~totheirappearancejustnow":"Numa tarde do fim do verão, antes de o século XIX haver percorrido um terço de sua extensão, um jovem e uma mulher, esta carregando uma criança, aproximavam-se a pé da grande aldeia de Weydon-Priors, em Upper Wessex. Estavam vestidos com simplicidade, mas não mal, embora a espessa geada de poeira acumulada em seus sapatos e roupas, de uma viagem obviamente longa, emprestasse à aparência deles, naquele momento, uma desvantajosa pobreza.","themanwasoffinefigureswarthyandsterninas~intherightashepacedalong":"O homem tinha belo porte, era moreno e de aspecto severo; e mostrava de perfil um ângulo facial tão pouco inclinado que era quase perpendicular. Vestia uma jaqueta curta de veludo cotelê marrom, mais nova que o resto do traje, que era um colete de fustão com botões de chifre branco, calções do mesmo tecido, polainas curtidas e um chapéu de palha coberto de lona preta lustrosa. Às costas levava, por uma correia em laço, um cesto de junco, do qual se projetava numa ponta o cabo de uma foice de feno, vendo-se também na abertura um trado para atar o feno. Seu andar medido e sem elasticidade era o andar do homem do campo habilidoso, distinto do arrastar errante do trabalhador comum; ao passo que, no giro e no assentar de cada pé, havia ainda uma indiferença obstinada e cínica, pessoal dele, que se mostrava até nas pregas de fustão alternando-se regularmente, ora na perna esquerda, ora na direita, enquanto caminhava.","whatwasreallypeculiarhoweverinthiscouple~dbabbleofthechildinreply":"O que era verdadeiramente peculiar, porém, na marcha daquele casal, e teria atraído a atenção de qualquer observador casual de outro modo inclinado a ignorá-los, era o perfeito silêncio que guardavam. Caminhavam lado a lado de um modo que sugeria de longe a conversa baixa, fácil e confidencial de pessoas cheias de reciprocidade; mas, de mais perto, percebia-se que o homem lia, ou fingia ler, uma folha de baladas que mantinha diante dos olhos com alguma dificuldade pela mão que passara pela correia do cesto. Se essa causa aparente era a causa real, ou se era uma assumida para escapar a uma conversa que lhe seria enfadonha, ninguém além dele poderia dizer com precisão; mas sua taciturnidade era inquebrantável, e a mulher não gozava de companhia alguma com a sua presença. Virtualmente caminhava sozinha pela estrada, exceto pela criança que levava. Às vezes o cotovelo dobrado do homem quase tocava o ombro dela, pois ela se mantinha tão junto ao seu flanco quanto possível sem contato efetivo, mas parecia não ter a menor ideia de tomar-lhe o braço, nem ele de oferecê-lo; e, longe de mostrar surpresa com o seu silêncio indiferente, parecia recebê-lo como coisa natural. Se alguma palavra era proferida pelo pequeno grupo, era um sussurro ocasional da mulher à criança — uma menininha de saias curtas e botinhas azuis de lã tricotada — e o balbucio murmurado da criança em resposta.","thechiefalmosttheonlyattractionoftheyoun~ndprobablyofcivilization":"O principal — quase o único — atrativo do rosto da jovem mulher era a sua mobilidade. Quando baixava o olhar de lado para a menina, tornava-se bonita, e até formosa, sobretudo porque, no movimento, seus traços apanhavam obliquamente os raios do sol de cores fortes, que faziam transparências de suas pálpebras e narinas e punham fogo em seus lábios. Quando se arrastava na sombra da sebe, pensando em silêncio, tinha a expressão dura, meio apática, de quem julga tudo possível das mãos do Tempo e do Acaso, exceto, talvez, jogo limpo. A primeira fase era obra da Natureza, a segunda provavelmente da civilização.","thatthemanandwomanwerehusbandandwifeandt~usastheymoveddowntheroad":"Que o homem e a mulher eram marido e mulher, e pais da menina de colo, dificilmente se poderia duvidar. Nenhuma outra relação explicaria a atmosfera de familiaridade gasta que os três levavam consigo como um nimbo ao descerem pela estrada.","thewifemostlykepthereyesfixedaheadthough~extraneoussoundtobeheard":"A esposa mantinha quase sempre os olhos fixos adiante, embora com pouco interesse — sendo a paisagem, aliás, uma que se poderia encontrar em quase qualquer ponto de qualquer condado da Inglaterra nessa época do ano; uma estrada nem reta nem torta, nem plana nem montanhosa, margeada por sebes, árvores e outra vegetação, que haviam entrado na fase verde-enegrecida de cor por que passam as folhas condenadas a caminho do pardo, do amarelo e do vermelho. A margem relvosa do barranco e os ramos mais próximos da sebe estavam polvilhados pela poeira que fora levantada sobre eles por veículos apressados, a mesma poeira que, assentada na estrada, amortecia como um tapete o ruído dos passos deles; e isto, com a já mencionada total ausência de conversa, permitia que se ouvisse todo som estranho."}$tr$::jsonb, 6)
on conflict (texto_slug, idioma) do update set cobertura = excluded.cobertura, credito = excluded.credito, titulos = excluded.titulos, paragrafos = excluded.paragrafos, total_paragrafos = excluded.total_paragrafos, atualizado_em = now();

-- william-shakespeare_a-midsummer-nights-dream (18 parágrafos, excerpt)
insert into public.livros_traducoes (texto_slug, idioma, cobertura, credito, titulos, paragrafos, total_paragrafos) values ('william-shakespeare_a-midsummer-nights-dream', 'pt', 'trecho', 'Tradução para o português do Brasil feita por IA (Claude) para o Alice''s Library; trecho de abertura, revisão pendente.', $tr${"acti":"Ato I"}$tr$::jsonb, $tr${"scenei~scenei":"Cena I","athensthepalaceoftheseus~athensthepalaceoftheseus":"Atenas. O palácio de Teseu.","entertheseushippolytaphilostrateandatten~philostrateandattendants":"Entram Teseu, Hipólita, Filóstrato e Criados.","theseusnowfairhippolytaournuptialhourdra~ringoutayoungmansrevenue":"Teseu — Agora, bela Hipólita, nossa hora nupcial\nAvança depressa; quatro dias felizes trazem\nOutra lua: mas, ó, como me parece lenta\nEsta velha lua a minguar! Ela retarda meus desejos,\nComo uma madrasta ou uma viúva dotada\nQue por longo tempo consome a renda de um jovem.","hippolytafourdayswillquicklysteepthemsel~thenightofoursolemnities":"Hipólita — Quatro dias logo se embeberão de noite;\nQuatro noites logo sonharão o tempo a passar;\nE então a lua, como um arco de prata\nRecém-curvado no céu, contemplará a noite\nDas nossas solenidades.","theseusgophilostratestiruptheathenianyou~htriumphandwithrevelling":"Teseu — Vai, Filóstrato,\nDespertai a juventude ateniense para os festejos;\nAcorda o espírito vivo e ágil da alegria:\nManda a melancolia para os funerais;\nA pálida companheira não é para a nossa pompa. Sai Filóstrato.\nHipólita, cortejei-te com a minha espada\nE ganhei teu amor causando-te ofensas;\nMas casar-me-ei contigo em outro tom,\nCom pompa, com triunfo e com folguedos.","enteregeushermialysanderanddemetrius~rmialysanderanddemetrius":"Entram Egeu, Hérmia, Lisandro e Demétrio.","egeushappybetheseusourrenownedduke~betheseusourrenownedduke":"Egeu — Feliz seja Teseu, nosso renomado duque!","theseusthanksgoodegeuswhatsthenewswithth~geuswhatsthenewswiththee":"Teseu — Obrigado, bom Egeu: que novas me trazes?","egeusfullofvexationcomeiwithcomplaintaga~iatelyprovidedinthatcase":"Egeu — Cheio de aflição venho, com queixa\nContra minha filha, minha filha Hérmia.\nAvança, Demétrio. Meu nobre senhor,\nEste homem tem meu consentimento para casar com ela.\nAvança, Lisandro: e, meu gracioso duque,\nEste homem enfeitiçou o coração de minha filha:\nTu, tu, Lisandro, tu lhe deste versos\nE trocaste com minha filha penhores de amor:\nTu, ao luar, à janela dela cantaste\nCom voz fingida versos de fingido amor,\nE roubaste a impressão de sua fantasia\nCom pulseiras de teus cabelos, anéis, bugigangas, galanteios,\nQuinquilharias, ninharias, ramalhetes, doces, mensageiros\nDe forte poder sobre a juventude ainda não endurecida:\nCom astúcia furtaste o coração de minha filha,\nTransformaste a obediência que me é devida\nEm teimosa aspereza: e, meu gracioso duque,\nSe ela não consentir aqui, perante vossa graça,\nEm casar com Demétrio,\nPeço o antigo privilégio de Atenas:\nSendo ela minha, posso dispor dela:\nO que será ou para este cavalheiro\nOu para a morte, conforme nossa lei\nImediatamente prevista neste caso.","theseuswhatsayyouhermiabeadvisedfairmaid~etriusisaworthygentleman":"Teseu — Que dizes, Hérmia? Aconselha-te, bela donzela:\nPara ti teu pai deveria ser como um deus;\nAquele que compôs tuas belezas, sim, e aquele\nPara quem és apenas como uma forma em cera\nPor ele impressa e em seu poder\nDeixar a figura ou desfigurá-la.\nDemétrio é um digno cavalheiro.","hermiasoislysander~hermiasoislysander":"Hérmia — Lisandro também é.","theseusinhimselfheisbutinthiskindwanting~hermustbeheldtheworthier":"Teseu — Em si mesmo é;\nMas, neste caso, faltando-lhe a voz de teu pai,\nO outro deve ser tido como mais digno.","hermiaiwouldmyfatherlookdbutwithmyeyes~fatherlookdbutwithmyeyes":"Hérmia — Quisera que meu pai olhasse com os meus olhos.","theseusratheryoureyesmustwithhisjudgment~smustwithhisjudgmentlook":"Teseu — Antes devem teus olhos olhar com o juízo dele.","hermiaidoentreatyourgracetopardonmeiknow~eifirefusetoweddemetrius":"Hérmia — Suplico a vossa graça que me perdoe.\nNão sei por que poder me sinto tão ousada,\nNem como isso pode afetar meu recato,\nAo expor meus pensamentos em tal presença;\nMas rogo a vossa graça que eu saiba\nO pior que pode me acontecer neste caso,\nSe eu recusar casar com Demétrio.","theseuseithertodiethedeathortoabjurefore~ddiesinsingleblessedness":"Teseu — Ou morrer a morte ou abjurar\nPara sempre a sociedade dos homens.\nPor isso, bela Hérmia, interroga teus desejos;\nConsulta tua juventude, examina bem teu sangue,\nVê se, caso não cedas à escolha de teu pai,\nPodes suportar a libré de uma freira,\nPara sempre em sombrio claustro enclausurada,\nPara viver estéril irmã toda a vida,\nEntoando hinos débeis à fria lua infrutífera.\nTrês vezes bem-aventurados os que dominam assim o sangue\nPara suportar tal peregrinação virginal;\nMas mais terrenamente feliz é a rosa destilada\nDo que a que, murchando no espinho virgem,\nCresce, vive e morre em bem-aventurança solitária.","hermiasowilligrowsolivesodiemylordereiwi~entsnottogivesovereignty":"Hérmia — Assim crescerei, assim viverei, assim morrerei, meu senhor,\nAntes de entregar minha patente virginal\nA sua senhoria, cujo indesejado jugo\nMinha alma não consente em dar soberania."}$tr$::jsonb, 18)
