-- william-shakespeare_as-you-like-it (24 parágrafos, excerpt)
insert into public.livros_traducoes (texto_slug, idioma, cobertura, credito, titulos, paragrafos, total_paragrafos) values ('william-shakespeare_as-you-like-it', 'pt', 'trecho', 'Tradução para o português do Brasil feita por IA (Claude) para o Alice''s Library; trecho de abertura, revisão pendente.', $tr${"acti":"Ato I"}$tr$::jsonb, $tr${"scenei~scenei":"Cena I","orchardofolivershouse~orchardofolivershouse":"Pomar da casa de Oliver.","enterorlandoandadam~enterorlandoandadam":"Entram Orlando e Adam.","orlandoasirememberadamitwasuponthisfashi~nowiseremedyhowtoavoidit":"Orlando — Pelo que me lembro, Adam, foi desta maneira que ele me legou por testamento apenas mil coroas e, como dizes, encarregou meu irmão, sob sua bênção, de me criar bem: e é aí que começa a minha tristeza. Meu irmão Jaques ele mantém na escola, e a fama fala em ouro de seu aproveitamento; quanto a mim, ele me mantém rusticamente em casa ou, para falar com mais propriedade, me retém aqui sem criação; pois chamas a isso criar um cavalheiro de meu nascimento, quando em nada difere do estabulamento de um boi? Seus cavalos são mais bem criados; pois, além de serem bonitos pela boa ração, são ensinados na equitação, e para isso se pagam caro os cavaleiros; mas eu, seu irmão, nada ganho com ele senão crescimento; pelo que seus animais nos esterqueiros lhe são tão obrigados quanto eu. Além deste nada que tão fartamente me dá, o pouco que a natureza me deu o seu semblante parece tirar-me: deixa-me comer com seus criados, nega-me o lugar de irmão e, tanto quanto está em seu poder, mina minha fidalguia com a minha educação. É isto, Adam, o que me aflige; e o espírito de meu pai, que creio estar em mim, começa a se amotinar contra esta servidão: não a suportarei mais, embora ainda não saiba nenhum remédio sensato para evitá-la.","adamyondercomesmymasteryourbrother~comesmymasteryourbrother":"Adam — Eis que vem aí meu amo, vosso irmão.","orlandogoapartadamandthoushalthearhowhew~lthearhowhewillshakemeup":"Orlando — Afasta-te, Adam, e ouvirás como ele vai me sacudir.","enteroliver~enteroliver":"Entra Oliver.","olivernowsirwhatmakeyouhere~vernowsirwhatmakeyouhere":"Oliver — Então, senhor! que fazeis aqui?","orlandonothingiamnottaughttomakeanything~mnottaughttomakeanything":"Orlando — Nada: não fui ensinado a fazer coisa alguma.","oliverwhatmaryouthensir~oliverwhatmaryouthensir":"Oliver — Que estragais, então, senhor?","orlandomarrysiriamhelpingyoutomarthatwhi~otherofyourswithidleness":"Orlando — Ora, senhor, ajudo-vos a estragar, com ociosidade, o que Deus fez: um pobre e indigno irmão vosso.","olivermarrysirbebetteremployedandbenaugh~mployedandbenaughtawhile":"Oliver — Ora, senhor, empregai-vos melhor e sumi por um tempo.","orlandoshallikeepyourhogsandeathuskswith~tishouldcometosuchpenury":"Orlando — Hei de guardar vossos porcos e comer bolotas com eles? Que porção pródiga gastei eu, para chegar a tamanha penúria?","oliverknowyouwhereyouraresir~erknowyouwhereyouraresir":"Oliver — Sabeis onde estais, senhor?","orlandoosirverywellhereinyourorchard~erywellhereinyourorchard":"Orlando — Oh, senhor, muito bem: aqui, em vosso pomar.","oliverknowyoubeforewhomsir~iverknowyoubeforewhomsir":"Oliver — Sabeis diante de quem, senhor?","orlandoaybetterthanhimiambeforeknowsmeik~meisnearertohisreverence":"Orlando — Sim, melhor do que aquele diante de quem estou me conhece. Sei que sois meu irmão mais velho e, na gentil condição do sangue, assim deveríeis conhecer-me. A cortesia das nações vos permite ser meu superior, por serdes o primogênito; mas essa mesma tradição não tira meu sangue, ainda que houvesse vinte irmãos entre nós: tenho tanto de meu pai em mim quanto vós; embora, confesso, o fato de virdes antes de mim vos aproxime mais de sua reverência.","oliverwhatboy~oliverwhatboy":"Oliver — O quê, rapaz!","orlandocomecomeelderbrotheryouaretooyoun~theryouaretooyounginthis":"Orlando — Vamos, vamos, irmão mais velho, sois novo demais nisto.","oliverwiltthoulayhandsonmevillain~tthoulayhandsonmevillain":"Oliver — Ousas pôr as mãos em mim, vilão?","orlandoiamnovillainiamtheyoungestsonofsi~othouhastrailedonthyself":"Orlando — Não sou vilão; sou o filho mais novo de Sir Rowland de Boys; ele foi meu pai, e três vezes vilão é quem diz que tal pai gerou vilões. Não fosses meu irmão, não tiraria esta mão de tua garganta até que a outra te arrancasse a língua por dizeres tal coisa: injuriaste a ti mesmo.","adamsweetmastersbepatientforyourfathersr~ersremembrancebeataccord":"Adam — Doces senhores, tende paciência: em memória de vosso pai, estai em paz.","oliverletmegoisay~oliverletmegoisay":"Oliver — Soltai-me, digo.","orlandoiwillnottillipleaseyoushallhearme~thatiwillgobuymyfortunes":"Orlando — Não o farei até que me apraza: ouvir-me-eis. Meu pai vos encarregou em testamento de dar-me boa educação: criastes-me como um camponês, obscurecendo e ocultando de mim todas as qualidades de um cavalheiro. O espírito de meu pai cresce forte em mim, e não o suportarei mais: portanto permiti-me os exercícios que convêm a um cavalheiro, ou dai-me a pobre quota que meu pai me deixou por testamento; com ela irei comprar a minha fortuna."}$tr$::jsonb, 24)
