-- william-shakespeare_hamlet (52 parágrafos, excerpt)
insert into public.livros_traducoes (texto_slug, idioma, cobertura, credito, titulos, paragrafos, total_paragrafos) values ('william-shakespeare_hamlet', 'pt', 'trecho', 'Tradução para o português do Brasil feita por IA (Claude) para o Alice''s Library; trecho de abertura, revisão pendente.', $tr${"acti":"Ato I"}$tr$::jsonb, $tr${"scenei~scenei":"Cena I","elsinoreaplatformbeforethecastle~aplatformbeforethecastle":"Elsinore. Uma plataforma diante do castelo.","franciscoathispostentertohimbernardo~ispostentertohimbernardo":"Francisco em seu posto. Entra Bernardo.","bernardowhosthere~bernardowhosthere":"Bernardo — Quem está aí?","francisconayanswermestandandunfoldyourse~mestandandunfoldyourself":"Francisco — Não, responda-me você: alto, e identifique-se.","bernardolonglivetheking~bernardolonglivetheking":"Bernardo — Viva o rei!","franciscobernardo~franciscobernardo":"Francisco — Bernardo?","bernardohe~bernardohe":"Bernardo — Ele mesmo.","franciscoyoucomemostcarefullyuponyourhou~ostcarefullyuponyourhour":"Francisco — Você chega pontualíssimo à sua hora.","bernardotisnowstrucktwelvegettheetobedfr~lvegettheetobedfrancisco":"Bernardo — Já soaram as doze; vá para a cama, Francisco.","franciscoforthisreliefmuchthankstisbitte~tercoldandiamsickatheart":"Francisco — Muito obrigado pela rendição: faz um frio cortante, \n e eu estou com o coração doente.","bernardohaveyouhadquietguard~ardohaveyouhadquietguard":"Bernardo — Teve uma guarda tranquila?","francisconotamousestirring~ancisconotamousestirring":"Francisco — Nem um rato se mexeu.","bernardowellgoodnightifyoudomeethoratioa~fmywatchbidthemmakehaste":"Bernardo — Bem, boa noite. \n Se encontrar Horácio e Marcelo, \n meus companheiros de vigília, diga-lhes que se apressem.","franciscoithinkihearthemstandhowhosthere~hearthemstandhowhosthere":"Francisco — Acho que os ouço. Alto lá! Quem vem?","enterhoratioandmarcellus~enterhoratioandmarcellus":"Entram Horácio e Marcelo.","horatiofriendstothisground~ratiofriendstothisground":"Horácio — Amigos desta terra.","marcellusandliegementothedane~llusandliegementothedane":"Marcelo — E vassalos do Dinamarquês.","franciscogiveyougoodnight~ranciscogiveyougoodnight":"Francisco — Boa noite a vocês.","marcellusofarewellhonestsoldierwhohathre~oldierwhohathrelievedyou":"Marcelo — Oh, adeus, honesto soldado: \n quem o rendeu?","franciscobernardohasmyplacegiveyougoodni~lacegiveyougoodnightexit":"Francisco — Bernardo tomou meu lugar. \n Boa noite a vocês. Sai.","marcellushollabernardo~marcellushollabernardo":"Marcelo — Olá! Bernardo!","bernardosaywhatishoratiothere~rdosaywhatishoratiothere":"Bernardo — Diga, \n o quê, Horácio está aí?","horatioapieceofhim~horatioapieceofhim":"Horácio — Um pedaço dele.","bernardowelcomehoratiowelcomegoodmarcell~atiowelcomegoodmarcellus":"Bernardo — Bem-vindo, Horácio; bem-vindo, bom Marcelo.","marcelluswhathasthisthingappeardagainton~thingappeardagaintonight":"Marcelo — E então, essa coisa apareceu de novo esta noite?","bernardoihaveseennothing~bernardoihaveseennothing":"Bernardo — Não vi nada.","marcellushoratiosaystisbutourfantasyandw~proveoureyesandspeaktoit":"Marcelo — Horácio diz que é só fantasia nossa, \n e não deixa que a crença o domine \n quanto a essa visão terrível, vista duas vezes por nós: \n por isso lhe roguei que viesse conosco \n vigiar os minutos desta noite; \n para que, se essa aparição vier outra vez, \n ele confirme nossos olhos e lhe fale.","horatiotushtushtwillnotappear~iotushtushtwillnotappear":"Horácio — Bah, bah, não vai aparecer.","bernardositdownawhileandletusonceagainas~ywhatwehavetwonightsseen":"Bernardo — Sente-se um pouco; \n e deixe que mais uma vez assaltemos seus ouvidos, \n tão fortificados contra a nossa história, \n com o que vimos por duas noites.","horatiowellsitwedownandletushearbernardo~shearbernardospeakofthis":"Horácio — Pois bem, sentemo-nos, \n e ouçamos Bernardo falar disto.","bernardolastnightofallwhenyondsamestarth~elfthebellthenbeatingone":"Bernardo — Na noite passada, \n quando aquela mesma estrela, a oeste do polo, \n já tinha feito seu curso para iluminar aquela parte do céu \n onde agora arde, Marcelo e eu, \n o sino então batendo uma hora...","enterghost~enterghost":"Entra o Fantasma.","marcelluspeacebreaktheeofflookwhereitcom~offlookwhereitcomesagain":"Marcelo — Silêncio, cale-se; veja, aí vem ele de novo!","bernardointhesamefigurelikethekingthatsd~gurelikethekingthatsdead":"Bernardo — Na mesma figura, igual ao rei que morreu.","marcellusthouartascholarspeaktoithoratio~ascholarspeaktoithoratio":"Marcelo — Você é letrado; fale com ele, Horácio.","bernardolooksitnotlikethekingmarkithorat~likethekingmarkithoratio":"Bernardo — Não se parece com o rei? Repare, Horácio.","horatiomostlikeitharrowsmewithfearandwon~rrowsmewithfearandwonder":"Horácio — Muitíssimo: enche-me de medo e de assombro.","bernardoitwouldbespoketo~bernardoitwouldbespoketo":"Bernardo — Quer que lhe falem.","marcellusquestionithoratio~rcellusquestionithoratio":"Marcelo — Interrogue-o, Horácio.","horatiowhatartthouthatusurpstthistimeofn~byheavenichargetheespeak":"Horácio — Quem és tu, que usurpas esta hora da noite, \n juntamente com essa bela e guerreira forma \n na qual a majestade da Dinamarca sepultada \n outrora marchava? Pelo céu, eu te conjuro: fala!","marcellusitisoffended~marcellusitisoffended":"Marcelo — Ele se ofendeu.","bernardoseeitstalksaway~bernardoseeitstalksaway":"Bernardo — Vejam, ele se afasta a passos largos!","horatiostayspeakspeakichargetheespeakexi~chargetheespeakexitghost":"Horácio — Pára! Fala, fala! Eu te conjuro, fala! Sai o Fantasma.","marcellustisgoneandwillnotanswer~stisgoneandwillnotanswer":"Marcelo — Foi-se, e não quer responder.","bernardohownowhoratioyoutrembleandlookpa~anfantasywhatthinkyouont":"Bernardo — Então, Horácio! Você treme e está pálido: \n não é isto algo mais do que fantasia? \n Que pensa disso?","horatiobeforemygodimightnotthisbelievewi~dtrueavouchofmineowneyes":"Horácio — Perante meu Deus, eu não poderia crer nisto \n sem o testemunho sensível e verdadeiro \n dos meus próprios olhos.","marcellusisitnotliketheking~cellusisitnotliketheking":"Marcelo — Não se parece com o rei?","horatioasthouarttothyselfsuchwastheverya~olacksontheicetisstrange":"Horácio — Como você se parece consigo mesmo: \n era essa a mesma armadura que ele vestia \n quando combateu o ambicioso norueguês; \n assim franziu ele o cenho quando, num colérico parlamento, \n derrotou os polacos de trenó sobre o gelo. \n É estranho.","marcellusthustwicebeforeandjumpatthisdea~talkhathhegonebyourwatch":"Marcelo — Assim, duas vezes antes, e justo nesta hora morta, \n passou ele com marcial passada por nossa guarda.","horatioinwhatparticularthoughttoworkikno~trangeeruptiontoourstate":"Horácio — Em que pensamento particular trabalhar, não sei; \n mas no conjunto e alcance de minha opinião, \n isto pressagia alguma estranha erupção em nosso Estado.","marcellusgoodnowsitdownandtellmehethatkn~daywhoistthatcaninformme":"Marcelo — Ora, sente-se, e diga-me, quem souber, \n por que esta guarda tão estrita e vigilante \n fatiga assim todas as noites os súditos da terra, \n e por que tal fundição diária de canhões de bronze, \n e comércio estrangeiro de apetrechos de guerra; \n por que tal recrutamento de carpinteiros navais, cuja dura tarefa \n não separa o domingo do resto da semana; \n o que pode estar para vir, que esta pressa suada \n faz da noite companheira de labor do dia: \n quem é que pode me informar?"}$tr$::jsonb, 52)
