-- william-shakespeare_henry-v (2 parágrafos, excerpt)
insert into public.livros_traducoes (texto_slug, idioma, cobertura, credito, titulos, paragrafos, total_paragrafos) values ('william-shakespeare_henry-v', 'pt', 'trecho', 'Tradução para o português do Brasil feita por IA (Claude) para o Alice''s Library; trecho de abertura, revisão pendente.', $tr${"prologue":"Prólogo"}$tr$::jsonb, $tr${"enterchorus~enterchorus":"Entra o CORO.","chorusoforamuseoffirethatwouldascendtheb~kindlytojudgeourplayexit":"CORO — Ó, por uma Musa de fogo, que ascendesse\nAo mais luminoso céu da invenção,\nUm reino por palco, príncipes por atores\nE monarcas por testemunhas da cena grandiosa!\nEntão o guerreiro Henrique, qual ele mesmo,\nTomaria o porte de Marte; e a seus calcanhares,\nPresos como cães de caça, a fome, a espada e o fogo\nAgachar-se-iam, à espera de serviço. Mas perdão, nobres senhores,\nPelos espíritos rasteiros e sem altura que ousaram\nTrazer a este tablado indigno\nTão grande assunto: pode este rinque de rinhas conter\nOs vastos campos da França? Ou podemos nós apertar\nNeste O de madeira os próprios elmos\nQue espantaram o ar em Azincourt?\nÓ, perdão! Pois um algarismo torto pode\nAtestar em pouco espaço um milhão;\nE deixai que nós, zeros dessa grande conta,\nAtuemos sobre as vossas forças imaginárias.\nSuponde que dentro do cinto destes muros\nEstão agora confinadas duas poderosas monarquias,\nCujas frontes altaneiras, contíguas,\nO perigoso e estreito oceano separa:\nCompletai nossas imperfeições com vossos pensamentos;\nDividi um só homem em mil partes\nE criai um poder imaginário;\nPensai, quando falarmos de cavalos, que os vedes\nImprimindo seus orgulhosos cascos na terra que os recebe;\nPois são vossos pensamentos que agora devem adornar nossos reis,\nLevá-los daqui para ali; saltando sobre os tempos,\nTransformando a realização de muitos anos\nNuma ampulheta: para o que suprir,\nAdmiti-me, o Coro, a esta história;\nQue, à maneira de prólogo, rogo à vossa humilde paciência\nQue ouça com brandura, julgue com bondade a nossa peça. Sai."}$tr$::jsonb, 2)
