-- william-shakespeare_king-lear (26 parágrafos, excerpt)
insert into public.livros_traducoes (texto_slug, idioma, cobertura, credito, titulos, paragrafos, total_paragrafos) values ('william-shakespeare_king-lear', 'pt', 'trecho', 'Tradução para o português do Brasil feita por IA (Claude) para o Alice''s Library; trecho de abertura, revisão pendente.', $tr${"acti":"Ato I"}$tr$::jsonb, $tr${"scenei~scenei":"Cena I","kinglearspalace~kinglearspalace":"O palácio do Rei Lear","enterkentgloucesterandedmund~rkentgloucesterandedmund":"Entram Kent, Gloucester e Edmund.","kentithoughtthekinghadmoreaffectedtheduk~dukeofalbanythancornwall":"Kent — Pensei que o rei tivesse mais afeição ao Duque de Albany do que a Cornwall.","gloucesteritdidalwaysseemsotousbutnowint~akechoiceofeithersmoiety":"Gloucester — Sempre nos pareceu assim: mas agora, na divisão do reino, não se vê qual dos duques ele mais estima; pois as porções são tão equilibradas que o exame mais minucioso não saberia escolher entre uma metade e outra.","kentisnotthisyoursonmylord~ntisnotthisyoursonmylord":"Kent — Não é este o seu filho, milorde?","gloucesterhisbreedingsirhathbeenatmychar~ehimthatnowiambrazedtoit":"Gloucester — Sua criação, senhor, correu por minha conta: tantas vezes corei ao reconhecê-lo, que agora estou calejado.","kenticannotconceiveyou~kenticannotconceiveyou":"Kent — Não o compreendo.","gloucestersirthisyoungfellowsmothercould~orherbeddoyousmellafault":"Gloucester — Senhor, a mãe deste rapaz compreendeu: pelo que ficou de ventre redondo, e teve, de fato, senhor, um filho no berço antes de ter um marido no leito. Sente cheiro de falta?","kenticannotwishthefaultundonetheissueofi~heissueofitbeingsoproper":"Kent — Não posso desejar a falta desfeita, sendo o fruto dela tão bem-feito.","gloucesterbutihavesirasonbyorderoflawsom~thisnoblegentlemanedmund":"Gloucester — Mas tenho, senhor, um filho por força da lei, uns anos mais velho que este, que nem por isso me é mais caro: embora este maroto tenha vindo ao mundo um tanto atrevidamente, antes de ser chamado, sua mãe era bela; houve bom divertimento em sua feitura, e o bastardo deve ser reconhecido. Conhece este nobre cavalheiro, Edmund?","edmundnomylord~edmundnomylord":"Edmund — Não, milorde.","gloucestermylordofkentrememberhimhereaft~fterasmyhonourablefriend":"Gloucester — Milorde de Kent: lembre-se dele daqui por diante como meu honrado amigo.","edmundmyservicestoyourlordship~myservicestoyourlordship":"Edmund — Meus serviços a Vossa Senhoria.","kentimustloveyouandsuetoknowyoubetter~youandsuetoknowyoubetter":"Kent — Devo estimá-lo, e peço conhecê-lo melhor.","edmundsirishallstudydeserving~dsirishallstudydeserving":"Edmund — Senhor, esforçar-me-ei por merecê-lo.","gloucesterhehathbeenoutnineyearsandawayh~hallagainthekingiscoming":"Gloucester — Esteve fora nove anos, e fora estará de novo. O rei vem vindo.","sennetenterkinglearcornwallalbanygoneril~gancordeliaandattendants":"Toque de trombetas. Entram o Rei Lear, Cornwall, Albany, Goneril, Regan, Cordélia e Séquito.","kinglearattendthelordsoffranceandburgund~nceandburgundygloucester":"Rei Lear — Atenda os senhores de França e Borgonha, Gloucester.","gloucesterishallmyliege~gloucesterishallmyliege":"Gloucester — Atenderei, meu soberano.","exeuntgloucesterandedmund~xeuntgloucesterandedmund":"Saem Gloucester e Edmund.","kinglearmeantimeweshallexpressourdarkerp~loureldestbornspeakfirst":"Rei Lear — Entrementes exporemos nosso propósito mais sombrio.\nDai-me o mapa. Sabei que dividimos\nem três o nosso reino: e é firme intento nosso\nsacudir de nossa idade todos os cuidados e negócios,\nconferindo-os a forças mais jovens, enquanto nós,\naliviados, rastejamos para a morte. Nosso filho de Cornwall,\ne vós, nosso não menos amado filho de Albany,\ntemos nesta hora vontade firme de tornar público\no dote de cada uma de nossas filhas, para que futura contenda\nseja prevenida desde já. Os príncipes, França e Borgonha,\ngrandes rivais no amor de nossa filha mais nova,\nlongamente fizeram em nossa corte sua estada amorosa,\ne aqui devem ser respondidos. Dizei-me, filhas minhas —\nvisto que agora nos despiremos juntos de mando,\nposse de território, cuidados de Estado —\nqual de vós diremos que mais nos ama?\nPara que nossa maior generosidade se estenda\nonde a natureza com o mérito disputa. Goneril,\nnossa primogênita, falai primeiro.","gonerilsiriloveyoumorethanwordscanwieldt~llmannerofsomuchiloveyou":"Goneril — Senhor, amo-vos mais do que palavras podem manejar a matéria;\nmais que a luz dos olhos, o espaço e a liberdade;\nalém de tudo o que se possa avaliar, rico ou raro;\nnão menos que a vida, com graça, saúde, beleza, honra;\ntanto quanto filha jamais amou, ou pai achou;\num amor que faz o fôlego pobre e a fala incapaz;\nalém de toda medida de tanto eu vos amo.","cordeliaasidewhatshallcordeliadoloveandb~ordeliadoloveandbesilent":"Cordélia — À parte. Que fará Cordélia? Amar, e calar.","learofalltheseboundsevenfromthislinetoth~reganwifetocornwallspeak":"Lear — De todos estes limites, desta linha até esta,\ncom florestas sombrias e planícies enriquecidas,\ncom rios abundantes e vastos prados,\nfazemos-te senhora: à tua descendência e à de Albany\nseja isto perpétuo. Que diz nossa segunda filha,\nnossa queridíssima Regan, esposa de Cornwall? Falai.","regansiriammadeoftheselfsamemetalthatmys~teinyourdearhighnesslove":"Regan — Senhor, sou feita\ndo mesmo metal que minha irmã,\ne avaliai-me pelo seu valor. Em meu verdadeiro coração\nacho que ela nomeia o próprio ato do meu amor;\nsó que fica aquém: pois declaro\nser inimiga de todas as outras alegrias\nque o mais precioso domínio dos sentidos possui;\ne sinto-me feliz somente\nno amor de Vossa cara Alteza."}$tr$::jsonb, 26)
