-- william-shakespeare_macbeth (37 parágrafos, excerpt)
insert into public.livros_traducoes (texto_slug, idioma, cobertura, credito, titulos, paragrafos, total_paragrafos) values ('william-shakespeare_macbeth', 'pt', 'trecho', 'Tradução para o português do Brasil feita por IA (Claude) para o Alice''s Library; trecho de abertura, revisão pendente.', $tr${"acti":"Ato I"}$tr$::jsonb, $tr${"scenei~scenei":"Cena I","adesertplace~adesertplace":"Um lugar deserto.","thunderandlightningenterthreewitches~ghtningenterthreewitches":"Trovões e relâmpagos. Entram três Bruxas.","firstwitchwhenshallwethreemeetagaininthu~thunderlightningorinrain":"Primeira Bruxa — Quando nos reuniremos as três outra vez\nNo trovão, no relâmpago ou na chuva?","secondwitchwhenthehurlyburlysdonewhenthe~whenthebattleslostandwon":"Segunda Bruxa — Quando o alvoroço acabar,\nQuando a batalha for perdida e ganha.","thirdwitchthatwillbeerethesetofsun~thatwillbeerethesetofsun":"Terceira Bruxa — Isso será antes de o sol se pôr.","firstwitchwheretheplace~firstwitchwheretheplace":"Primeira Bruxa — E o lugar?","secondwitchupontheheath~secondwitchupontheheath":"Segunda Bruxa — Na charneca.","thirdwitchtheretomeetwithmacbeth~chtheretomeetwithmacbeth":"Terceira Bruxa — Lá, para encontrar Macbeth.","firstwitchicomegraymalkin~irstwitchicomegraymalkin":"Primeira Bruxa — Já vou, Graymalkin!","secondwitchpaddockcalls~secondwitchpaddockcalls":"Segunda Bruxa — O Sapo chama.","thirdwitchanon~thirdwitchanon":"Terceira Bruxa — Já.","allfairisfoulandfoulisfairhoverthroughth~thefogandfilthyairexeunt":"Todas — O belo é feio, e o feio é belo:\nPairemos pela névoa e pelo ar imundo. Saem.","sceneii~sceneii":"Cena II","acampnearforres~acampnearforres":"Um acampamento perto de Forres.","alarumwithinenterduncanmalcolmdonalbainl~meetingableedingsergeant":"Toque de alarme ao longe. Entram Duncan, Malcolm, Donalbain, Lennox e Criados, ao encontro de um Sargento ensanguentado.","duncanwhatbloodymanisthathecanreportasse~ftherevolttheneweststate":"Duncan — Quem é aquele homem coberto de sangue? Ele pode informar,\nPelo que sua condição indica, sobre a revolta\nO estado mais recente.","malcolmthisisthesergeantwholikeagoodandh~ebroilasthoudidstleaveit":"Malcolm — Este é o sargento\nQue, como bom e valente soldado, lutou\nPara me livrar do cativeiro. Salve, bravo amigo!\nDize ao rei o que sabes da refrega\nTal como a deixaste.","sergeantdoubtfulitstoodastwospentswimmer~isheaduponourbattlements":"Sargento — Duvidosa ela estava;\nComo dois nadadores exaustos que se agarram um ao outro\nE sufocam a própria arte. O impiedoso Macdonwald —\nDigno de ser rebelde, pois para isso\nAs multiplicadas vilanias da natureza\nEnxameiam sobre ele — das ilhas ocidentais\nÉ suprido de kerns e gallowglasses;\nE a fortuna, sorrindo à sua causa maldita,\nParecia a prostituta de um rebelde: mas tudo era fraco demais:\nPois o bravo Macbeth — bem merece esse nome —\nDesdenhando a fortuna, com seu aço brandido,\nQue fumegava de sangrenta execução,\nComo favorito da valentia abriu a sua passagem\nAté enfrentar o canalha;\nQue nem lhe apertou a mão, nem lhe disse adeus,\nAté o rasgar desde o umbigo até as queixadas,\nE fixar-lhe a cabeça em nossas ameias.","duncanovaliantcousinworthygentleman~antcousinworthygentleman":"Duncan — Ó valente primo! digno cavalheiro!","sergeantaswhencethesunginshisreflections~sofmenbeganafreshassault":"Sargento — Assim como de onde o sol começa a sua reflexão\nTempestades que naufragam e trovões terríveis irrompem,\nAssim da fonte de onde parecia vir o conforto\nO desconforto transborda. Atende, rei da Escócia, atende:\nMal a justiça, armada de valor,\nObrigara esses kerns saltitantes a confiar nos calcanhares,\nO senhor norueguês, avaliando a vantagem,\nCom armas areadas e novos reforços de homens\nComeçou um novo assalto.","duncandismaydnotthisourcaptainsmacbethan~captainsmacbethandbanquo":"Duncan — Isso não desanimou\nNossos capitães, Macbeth e Banquo?","sergeantyesassparrowseaglesortheharethel~mfaintmygashescryforhelp":"Sargento — Sim;\nComo pardais a águias, ou a lebre ao leão.\nSe digo a verdade, devo relatar que eles eram\nComo canhões sobrecarregados de dupla carga, tanto\nDobrando e redobrando golpes sobre o inimigo:\nA não ser que pretendessem banhar-se em feridas fumegantes\nOu perpetuar a memória de outro Gólgota,\nNão sei dizer.\nMas estou fraco, meus ferimentos pedem socorro.","duncansowellthywordsbecometheeasthywound~eantattendedwhocomeshere":"Duncan — Tão bem te ornam as palavras como as feridas;\nAmbas têm sabor de honra. Ide buscar-lhe cirurgiões. Sai o Sargento, acompanhado.\nQuem vem aí?","enterross~enterross":"Entra Ross.","malcolmtheworthythaneofross~colmtheworthythaneofross":"Malcolm — O digno barão de Ross.","lennoxwhatahastelooksthroughhiseyessosho~eemstospeakthingsstrange":"Lennox — Que pressa transparece em seus olhos! Assim deve olhar\nQuem parece falar de coisas estranhas.","rossgodsavetheking~rossgodsavetheking":"Ross — Deus salve o rei!","duncanwhencecamestthouworthythane~ncecamestthouworthythane":"Duncan — De onde vens, digno barão?","rossfromfifegreatkingwherethenorweyanban~ncludethevictoryfellonus":"Ross — De Fife, grande rei;\nOnde os estandartes noruegueses zombam do céu\nE abanam gelo em nossa gente. O próprio rei da Noruega,\nCom terríveis multidões,\nAuxiliado por esse desleal traidor,\nO barão de Cawdor, iniciou um funesto combate;\nAté que o noivo de Belona, revestido de armadura à prova,\nO enfrentou com igualdades de si mesmo,\nPonta contra ponta rebelde, braço contra braço,\nRefreando-lhe o espírito pródigo: e, para concluir,\nA vitória coube a nós.","duncangreathappiness~duncangreathappiness":"Duncan — Grande ventura!","rossthatnowswenothenorwayskingcravescomp~nddollarstoourgeneraluse":"Ross — Que agora\nSweno, o rei dos noruegueses, implora um acordo;\nNem consentimos em dar sepultura a seus homens\nAntes que desembolsasse na ilha de Saint Colme\nDez mil dólares para o uso geral de nossa causa.","duncannomorethatthaneofcawdorshalldeceiv~sformertitlegreetmacbeth":"Duncan — Nunca mais esse barão de Cawdor enganará\nNossa mais íntima confiança: vai, pronuncia sua morte imediata,\nE com o seu antigo título saúda Macbeth.","rossillseeitdone~rossillseeitdone":"Ross — Verei que seja feito.","duncanwhathehathlostnoblemacbethhathwone~oblemacbethhathwonexeunt":"Duncan — O que ele perdeu o nobre Macbeth ganhou. Saem.","sceneiii~sceneiii":"Cena III","aheathnearforres~aheathnearforres":"Uma charneca perto de Forres."}$tr$::jsonb, 37)
