-- william-shakespeare_othello (17 parágrafos, excerpt)
insert into public.livros_traducoes (texto_slug, idioma, cobertura, credito, titulos, paragrafos, total_paragrafos) values ('william-shakespeare_othello', 'pt', 'trecho', 'Tradução para o português do Brasil feita por IA (Claude) para o Alice''s Library; trecho de abertura, revisão pendente.', $tr${"acti":"Ato I"}$tr$::jsonb, $tr${"scenei~scenei":"Cena I","veniceastreet~veniceastreet":"Veneza. Uma rua.","enterroderigoandiago~enterroderigoandiago":"Entram Rodrigo e Iago.","roderigotushnevertellmeitakeitmuchunkind~ethineshouldstknowofthis":"Rodrigo — Bah! Nunca me venha com isso; tomo-o muito a mal \n que tu, Iago, que dispuseste de minha bolsa \n como se os cordões fossem teus, soubesses disto.","iagosbloodbutyouwillnothearmeifeverididd~reamofsuchamatterabhorme":"Iago — Pelo sangue de Deus, mas o senhor não quer me ouvir: \n se alguma vez sonhei com tal coisa, abomine-me.","roderigothoutoldstmethoudidstholdhiminth~houdidstholdhiminthyhate":"Rodrigo — Disseste-me que o odiavas.","iagodespisemeifidonotthreegreatonesofthe~emarkhismoorshipsancient":"Iago — Despreze-me, se não é verdade. Três grandes da cidade, \n em pessoal súplica para me fazer seu tenente, \n tiraram-lhe o chapéu; e, pela fé de um homem, \n sei o meu preço, não valho posto pior: \n mas ele, amante de seu próprio orgulho e de seus intentos, \n esquiva-se, com um circunlóquio empolado \n horrivelmente recheado de epítetos de guerra; \n e, em conclusão, \n rejeita meus intercessores; pois “Certamente”, diz ele, \n “já escolhi o meu oficial.” \n E quem era ele? \n Ora, um grande aritmético, \n um tal Miguel Cássio, florentino, \n sujeito quase danado por uma bela esposa; \n que nunca pôs um esquadrão em campo, \n nem conhece a divisão de uma batalha \n mais que uma fiandeira; a não ser a teoria livresca, \n em que os cônsules togados sabem propor \n tão magistralmente quanto ele: mero palavreado, sem prática, \n é toda a sua soldadesca. Mas ele, senhor, teve a eleição: \n e eu, de quem os olhos dele tinham visto a prova \n em Rodes, em Chipre e em outras terras \n cristãs e pagãs, devo ficar a sotavento e em calmaria \n por causa de devedor e credor: esse contador de fichas, \n ele, em boa hora, há de ser seu tenente, \n e eu — Deus guarde a marca! — alferes de Sua Mourice.","roderigobyheaveniratherwouldhavebeenhish~rwouldhavebeenhishangman":"Rodrigo — Pelo céu, eu preferia ter sido o carrasco dele.","iagowhytheresnoremedytisthecurseofservic~rmamaffinedtolovethemoor":"Iago — Ora, não há remédio; é a maldição do serviço, \n a promoção vai por cartas e por afeição, \n e não pela velha gradação, em que cada segundo \n era herdeiro do primeiro. Agora, senhor, julgue o senhor mesmo \n se em algum termo justo estou obrigado \n a amar o Mouro.","roderigoiwouldnotfollowhimthen~goiwouldnotfollowhimthen":"Rodrigo — Então eu não o seguiria.","iagoosircontentyouifollowhimtoservemytur~awstopeckatiamnotwhatiam":"Iago — Oh, senhor, tenha calma; \n sigo-o para me servir dele a meu tempo: \n não podemos todos ser amos, nem todos os amos \n podem ser fielmente seguidos. O senhor notará \n muitos servos devotados e de joelhos dobrados, \n que, enamorados de sua própria obsequiosa servidão, \n gastam seu tempo, como o asno do patrão, \n por nada além de forragem, e na velhice são despedidos: \n chicoteiem-me tais honestos patifes. Outros há \n que, enfeitados de formas e semblantes de dever, \n mantêm contudo o coração servindo a si mesmos, \n e, lançando só aparências de serviço a seus senhores, \n prosperam à custa deles e, quando forraram \n os próprios casacos, \n prestam homenagem a si mesmos: esses sujeitos têm alma; \n e um desses eu me confesso. Pois, senhor, \n é tão certo quanto o senhor ser Rodrigo \n que, se eu fosse o Mouro, não seria Iago: \n ao segui-lo, sigo apenas a mim mesmo; \n o céu é meu juiz, não que eu o faça por amor e dever, \n mas por parecê-lo, para o meu fim particular: \n pois, quando meu agir exterior demonstrar \n o ato e a figura nativos do meu coração \n em cumprimento externo, não tardará muito \n que eu traga o coração à manga \n para os gaios o bicarem: eu não sou o que sou.","roderigowhatafullfortunedoesthethicklips~lipsoweifhecancarrytthus":"Rodrigo — Que plena fortuna possui o beiçudo, \n se consegue levar isto adiante!","iagocallupherfatherrousehimmakeafterhimp~ontasitmaylosesomecolour":"Iago — Chame o pai dela, \n acorde-o: vá atrás dele, envenene-lhe o deleite, \n proclame-o pelas ruas; inflame-lhe os parentes, \n e, ainda que ele habite clima fértil, \n infeste-o de moscas: embora a sua alegria seja alegria, \n lance-lhe tais mudanças de aflição \n que ela perca alguma cor.","roderigohereisherfathershouseillcallalou~fathershouseillcallaloud":"Rodrigo — Eis a casa do pai dela; vou chamar em voz alta.","iagodowithliketimorousaccentanddireyella~eisspiedinpopulouscities":"Iago — Faça-o, com tom igualmente temeroso e grito horrendo \n como quando, de noite e por negligência, o fogo \n é avistado em cidades populosas.","roderigowhathobrabantiosigniorbrabantioh~bantiosigniorbrabantioho":"Rodrigo — Ó de casa, Brabâncio! Senhor Brabâncio, ó de casa!","iagoawakewhathobrabantiothievesthievesth~ndyourbagsthievesthieves":"Iago — Acorde! Ó de casa, Brabâncio! Ladrões! Ladrões! Ladrões! \n Olhe por sua casa, sua filha e suas bolsas! \n Ladrões! Ladrões!"}$tr$::jsonb, 17)
