-- william-shakespeare_richard-iii (14 parágrafos, excerpt)
insert into public.livros_traducoes (texto_slug, idioma, cobertura, credito, titulos, paragrafos, total_paragrafos) values ('william-shakespeare_richard-iii', 'pt', 'trecho', 'Tradução para o português do Brasil feita por IA (Claude) para o Alice''s Library; trecho de abertura, revisão pendente.', $tr${"acti":"Ato I"}$tr$::jsonb, $tr${"scenei~scenei":"Cena I","londonastreet~londonastreet":"Londres. Uma rua.","enterricharddukeofgloucestersolus~arddukeofgloucestersolus":"Entra Ricardo, Duque de Gloucester, sozinho.","gloucesternowisthewinterofourdiscontentm~omysoulhereclarencecomes":"GLOUCESTER — Eis que o inverno de nosso descontentamento\nSe fez glorioso verão por este sol de York;\nE todas as nuvens que pesavam sobre nossa casa\nSepultaram-se no fundo seio do oceano.\nAgora nossas frontes cingem-se de louros vitoriosos;\nNossas armas amolgadas pendem como troféus;\nNossos severos alarmes mudaram-se em alegres festas,\nNossas marchas terríveis em danças deleitosas.\nA guerra de rosto severo alisou a fronte enrugada;\nE agora, em vez de montar corcéis encouraçados\nPara aterrar a alma de adversários medrosos,\nSalta ágil no quarto de uma dama\nAo som lascivo de um alaúde.\nMas eu, que não fui feito para jogos de recreio,\nNem talhado para cortejar um espelho amoroso;\nEu, rudemente cunhado, sem a majestade do amor\nPara pavonear-me diante de uma ninfa lasciva e saltitante;\nEu, a quem falta esta bela proporção,\nTrapaceado em feições pela natureza enganadora,\nDeformado, inacabado, enviado antes do tempo\nA este mundo que respira, mal feito pela metade,\nE tão coxo e fora de moda\nQue os cães me ladram quando manquejo por perto;\nEu, nesta fraca e flautada época de paz,\nNão tenho prazer algum com que passar o tempo,\nSenão espiar minha sombra ao sol\nE discantar sobre minha própria deformidade:\nE portanto, uma vez que não posso ser amante\nPara entreter estes belos dias de fala fácil,\nResolvi ser um vilão\nE odiar os ociosos prazeres destes dias.\nTramas tenho urdido, perigosas induções,\nPor profecias de bêbados, libelos e sonhos,\nPara pôr meu irmão Clarence e o rei\nEm mortal ódio um contra o outro:\nE se o rei Eduardo for tão leal e justo\nQuanto eu sou sutil, falso e traiçoeiro,\nHoje mesmo Clarence será encerrado em segredo,\nPor causa de uma profecia, que diz que G\nDos herdeiros de Eduardo será o assassino.\nMergulhai, pensamentos, até o fundo de minha alma: eis que vem Clarence.","enterclarenceguardedandbrakenbury~enceguardedandbrakenbury":"Entram Clarence, sob guarda, e Brakenbury.","brothergooddaywhatmeansthisarmedguardtha~rdthatwaitsuponyourgrace":"Irmão, bom dia: que significa esta guarda armada\nQue acompanha vossa graça?","clarencehismajestytenderingmypersonssafe~ducttoconveymetothetower":"CLARENCE — Sua majestade,\nZelando pela segurança de minha pessoa, designou\nEsta escolta para conduzir-me à Torre.","gloucesteruponwhatcause~gloucesteruponwhatcause":"GLOUCESTER — Por que motivo?","clarencebecausemynameisgeorge~ncebecausemynameisgeorge":"CLARENCE — Porque meu nome é George.","gloucesteralackmylordthatfaultisnoneofyo~hematterclarencemayiknow":"GLOUCESTER — Ai, meu senhor, essa falta não é vossa;\nPor isso ele devia prender vossos padrinhos:\nÓ, quiçá sua majestade pretenda\nQue sejais rebatizado na Torre.\nMas qual é o caso, Clarence? Posso saber?","clarenceyearichardwheniknowforiprotestas~hishighnesstocommitmenow":"CLARENCE — Sim, Ricardo, quando eu souber; pois protesto\nQue ainda não sei: mas, até onde posso apurar,\nEle dá ouvidos a profecias e sonhos;\nE do alfabeto arranca a letra G,\nE diz que um mago lhe disse que por G\nSua descendência seria deserdada;\nE, como meu nome George começa com G,\nSegue-se em seu pensamento que sou eu o homem.\nEssas, pelo que apuro, e outras frivolidades como essas\nMoveram sua alteza a prender-me agora.","gloucesterwhythisitiswhenmenareruledbywo~safeclarencewearenotsafe":"GLOUCESTER — Ora, eis o que dá quando os homens são governados por mulheres:\nNão é o rei que vos manda à Torre;\nMinha Lady Grey, sua esposa, Clarence, é ela\nQue o tempera a essa extremidade.\nNão foram ela e aquele bom homem de respeito,\nAnthony Woodville, seu irmão ali,\nQue o fizeram mandar lorde Hastings à Torre,\nDe onde hoje mesmo foi libertado?\nNão estamos seguros, Clarence; não estamos seguros.","clarencebyheavenithinktheresnomanissecur~gswastoherforhisdelivery":"CLARENCE — Pelos céus, creio que não há homem seguro\nSenão os parentes da rainha e os arautos noctâmbulos\nQue labutam entre o rei e a senhora Shore.\nNão ouvistes que humilde suplicante\nFoi lorde Hastings junto a ela por sua libertação?","gloucesterhumblycomplainingtoherdeitygot~htygossipsinthismonarchy":"GLOUCESTER — Queixando-se humildemente à divindade dela\nConseguiu meu lorde camareiro a liberdade.\nDir-vos-ei o que penso: este é o nosso caminho,\nSe quisermos manter o favor do rei:\nSer homens dela e vestir-lhe a libré:\nA viúva ciumenta e gasta e ela mesma,\nDesde que nosso irmão as armou damas,\nSão poderosas comadres nesta monarquia."}$tr$::jsonb, 14)
on conflict (texto_slug, idioma) do update set cobertura = excluded.cobertura, credito = excluded.credito, titulos = excluded.titulos, paragrafos = excluded.paragrafos, total_paragrafos = excluded.total_paragrafos, atualizado_em = now();

-- william-shakespeare_romeo-and-juliet (51 parágrafos, excerpt)
insert into public.livros_traducoes (texto_slug, idioma, cobertura, credito, titulos, paragrafos, total_paragrafos) values ('william-shakespeare_romeo-and-juliet', 'pt', 'trecho', 'Tradução para o português do Brasil feita por IA (Claude) para o Alice''s Library; trecho de abertura, revisão pendente.', $tr${"acti":"Ato I"}$tr$::jsonb, $tr${"scenei~scenei":"Cena I","veronaapublicplace~veronaapublicplace":"Verona. Um lugar público.","entersampsonandgregoryofthehouseofcapule~medwithswordsandbucklers":"Entram Sansão e Gregório, da casa dos Capuleto, armados de espadas e escudos.","sampsongregoryomywordwellnotcarrycoals~omywordwellnotcarrycoals":"SANSÃO — Gregório, palavra minha, não vamos carregar carvão.","gregorynoforthenweshouldbecolliers~orthenweshouldbecolliers":"GREGÓRIO — Não, pois então seríamos carvoeiros.","sampsonimeananwebeincholerwelldraw~ananwebeincholerwelldraw":"SANSÃO — Quero dizer, se nos irarmos, sacaremos da espada.","gregoryaywhileyoulivedrawyourneckoutothe~rawyourneckoutothecollar":"GREGÓRIO — Sim, enquanto viveres, tira o pescoço da coleira.","sampsonistrikequicklybeingmoved~istrikequicklybeingmoved":"SANSÃO — Firo depressa, quando me provocam.","gregorybutthouartnotquicklymovedtostrike~tnotquicklymovedtostrike":"GREGÓRIO — Mas não és depressa provocado a ferir.","sampsonadogofthehouseofmontaguemovesme~hehouseofmontaguemovesme":"SANSÃO — Um cão da casa dos Montéquio me provoca.","gregorytomoveistostirandtobevaliantistos~ouartmovedthourunnstaway":"GREGÓRIO — Provocar é mover-se; e ser valente é manter-se firme: portanto, se és provocado, foges.","sampsonadogofthathouseshallmovemetostand~fanymanormaidofmontagues":"SANSÃO — Um cão daquela casa me fará ficar firme: tomarei o lado da parede de qualquer homem ou donzela dos Montéquio.","gregorythatshowstheeaweakslavefortheweak~rtheweakestgoestothewall":"GREGÓRIO — Isso mostra que és um escravo fraco; pois o mais fraco vai de encontro à parede.","sampsontrueandthereforewomenbeingtheweak~dthrusthismaidstothewall":"SANSÃO — É verdade; e por isso as mulheres, sendo os vasos mais frágeis, são sempre empurradas contra a parede: portanto empurrarei os homens dos Montéquio para longe da parede, e empurrarei suas donzelas contra a parede.","gregorythequarrelisbetweenourmastersandu~nourmastersandustheirmen":"GREGÓRIO — A briga é entre nossos amos e nós, seus criados.","sampsontisalloneiwillshowmyselfatyrantwh~maidsandcutofftheirheads":"SANSÃO — Tanto faz, mostrar-me-ei um tirano: quando tiver lutado com os homens, serei cruel com as donzelas e lhes cortarei as cabeças.","gregorytheheadsofthemaids~regorytheheadsofthemaids":"GREGÓRIO — As cabeças das donzelas?","sampsonaytheheadsofthemaidsortheirmaiden~akeitinwhatsensethouwilt":"SANSÃO — Sim, as cabeças das donzelas, ou suas donzelices; toma no sentido que quiseres.","gregorytheymusttakeitinsensethatfeelit~ttakeitinsensethatfeelit":"GREGÓRIO — Hão de tomar no sentido as que o sentirem.","sampsonmetheyshallfeelwhileiamabletostan~wniamaprettypieceofflesh":"SANSÃO — A mim hão de sentir enquanto eu puder me manter em pé: e é sabido que sou um belo pedaço de carne.","gregorytiswellthouartnotfishifthouhadstt~ofthehouseofthemontagues":"GREGÓRIO — É bom que não sejas peixe; se fosses, serias um pobre bacalhau. Saca a tua ferramenta; aí vêm dois da casa dos Montéquio.","sampsonmynakedweaponisoutquarreliwillbac~soutquarreliwillbackthee":"SANSÃO — Minha arma nua já está fora: puxa a briga, eu te apoiarei.","gregoryhowturnthybackandrun~goryhowturnthybackandrun":"GREGÓRIO — Como! Virar as costas e correr?","sampsonfearmenot~sampsonfearmenot":"SANSÃO — Não me temas.","gregorynomarryifearthee~gregorynomarryifearthee":"GREGÓRIO — Não, por Nossa Senhora; eu, temer-te!","sampsonletustakethelawofoursidesletthemb~awofoursidesletthembegin":"SANSÃO — Fiquemos com a lei do nosso lado; deixemos que eles comecem.","gregoryiwillfrownasipassbyandletthemtake~dletthemtakeitastheylist":"GREGÓRIO — Franzirei o cenho ao passar, e que o tomem como quiserem.","sampsonnayastheydareiwillbitemythumbatth~sgracetothemiftheybearit":"SANSÃO — Não, como ousarem. Morderei o polegar para eles; o que é uma afronta, se a aguentarem.","enterabrahamandbalthasar~enterabrahamandbalthasar":"Entram Abraão e Baltasar.","abrahamdoyoubiteyourthumbatussir~oyoubiteyourthumbatussir":"ABRAÃO — Mordeis o polegar para nós, senhor?","sampsonidobitemythumbsir~sampsonidobitemythumbsir":"SANSÃO — Eu mordo o polegar, senhor.","sampsonasidetogregoryisthelawofoursideif~sthelawofoursideifisayay":"SANSÃO — À parte, a Gregório. A lei está do nosso lado, se eu disser que sim?","gregoryno~gregoryno":"GREGÓRIO — Não.","sampsonnosiridonotbitemythumbatyousirbut~yousirbutibitemythumbsir":"SANSÃO — Não, senhor, não mordo o polegar para vós, senhor, mas mordo o polegar, senhor.","gregorydoyouquarrelsir~gregorydoyouquarrelsir":"GREGÓRIO — Quereis briga, senhor?","abrahamquarrelsirnosir~abrahamquarrelsirnosir":"ABRAÃO — Briga, senhor! Não, senhor.","sampsonifyoudosiriamforyouiserveasgoodam~youiserveasgoodamanasyou":"SANSÃO — Se quereis, senhor, estou às vossas ordens: sirvo a um homem tão bom quanto o vosso.","abrahamnobetter~abrahamnobetter":"ABRAÃO — Não melhor.","sampsonwellsir~sampsonwellsir":"SANSÃO — Pois bem, senhor.","gregorysaybetterherecomesoneofmymastersk~mesoneofmymasterskinsmen":"GREGÓRIO — Diz “melhor”: aí vem um parente do meu amo.","sampsonyesbettersir~sampsonyesbettersir":"SANSÃO — Sim, melhor, senhor.","abrahamyoulie~abrahamyoulie":"ABRAÃO — Mentis.","sampsondrawifyoubemengregoryrememberthys~thyswashingblowtheyfight":"SANSÃO — Sacai, se sois homens. Gregório, lembra-te do teu golpe de arrasar. Lutam.","enterbenvolio~enterbenvolio":"Entra Benvólio.","benvoliopartfoolsputupyourswordsyouknown~oudobeatsdowntheirswords":"BENVÓLIO — Separai, tolos! \n Embainhai as espadas; não sabeis o que fazeis. Abate-lhes as espadas.","entertybalt~entertybalt":"Entra Teobaldo.","tybaltwhatartthoudrawnamongtheseheartles~benvoliolookuponthydeath":"TEOBALDO — Que, tu, sacado entre estes covardes servos? \n Volta-te, Benvólio, e olha a tua morte.","benvolioidobutkeepthepeaceputupthyswordo~geittopartthesemenwithme":"BENVÓLIO — Só mantenho a paz: embainha a tua espada, \n ou usa-a para ajudar-me a separar estes homens.","tybaltwhatdrawnandtalkofpeaceihatethewor~aveattheecowardtheyfight":"TEOBALDO — Que, sacado e a falar de paz! Odeio a palavra, \n como odeio o inferno, todos os Montéquio, e a ti: \n Em guarda, covarde! Lutam.","enterseveralofbothhouseswhojointhefrayth~enentercitizenswithclubs":"Entram vários de ambas as casas, que se juntam à briga; depois entram Cidadãos, com porretes.","firstcitizenclubsbillsandpartisansstrike~letsdownwiththemontagues":"PRIMEIRO CIDADÃO — Porretes, alabardas e partasanas! Batei! Abatei-os! \n Abaixo os Capuleto! Abaixo os Montéquio!"}$tr$::jsonb, 51)
