-- william-shakespeare_the-merchant-of-venice (21 parágrafos, excerpt)
insert into public.livros_traducoes (texto_slug, idioma, cobertura, credito, titulos, paragrafos, total_paragrafos) values ('william-shakespeare_the-merchant-of-venice', 'pt', 'trecho', 'Tradução para o português do Brasil feita por IA (Claude) para o Alice''s Library; trecho de abertura, revisão pendente.', $tr${"acti":"Ato I"}$tr$::jsonb, $tr${"scenei~scenei":"Cena I","veniceastreet~veniceastreet":"Veneza. Uma rua.","enterantoniosalarinoandsalanio~ntoniosalarinoandsalanio":"Entram Antônio, Salarino e Salânio.","antonioinsoothiknownotwhyiamsosaditweari~ihavemuchadotoknowmyself":"Antônio — Em verdade, não sei por que estou tão triste:\nCansa-me; dizeis que vos cansa;\nMas como o apanhei, achei ou adquiri,\nDe que matéria é feito, de que nasce,\nIsso tenho de aprender;\nE tal tristeza sem juízo faz de mim\nQue mal consigo me reconhecer.","salarinoyourmindistossingontheoceanthere~ythemwiththeirwovenwings":"Salarino — Vossa mente balança no oceano;\nLá, onde vossos galeões de velas soberbas,\nComo senhores e ricos burgueses sobre as ondas,\nOu, por assim dizer, os cortejos do mar,\nDominam do alto os pequenos mercadores,\nQue lhes fazem reverências, lhes prestam homenagem,\nQuando voam por eles com suas asas tecidas.","salaniobelievemesirhadisuchventurefortht~outofdoubtwouldmakemesad":"Salânio — Crede-me, senhor, se eu tivesse tal empresa no mar,\nA melhor parte de minhas afeições estaria\nCom minhas esperanças no estrangeiro. Estaria sempre\nArrancando capim, para saber onde se assenta o vento,\nEspiando mapas atrás de portos, cais e ancoradouros;\nE todo objeto que me fizesse temer\nInfortúnio às minhas empresas, sem dúvida\nMe faria triste.","salarinomywindcoolingmybrothwouldblowmet~othinkuponhismerchandise":"Salarino — Meu vento, a esfriar-me o caldo,\nSoprar-me-ia uma febre, ao pensar\nQue dano um vento forte demais no mar poderia fazer.\nNão veria correr a areia da ampulheta\nSem pensar em baixios e bancos de areia,\nE ver meu rico Andrew encalhado na areia,\nBaixando a gávea mais que as costelas\nPara beijar o seu sepulcro. Se eu fosse à igreja\nE visse o santo edifício de pedra,\nE não me lembrasse logo de rochas perigosas,\nQue, tocando apenas o flanco de minha gentil embarcação,\nEspalhariam todas as suas especiarias na corrente,\nVestiriam as águas rugidoras com minhas sedas,\nE, numa palavra, valendo agora isto tanto,\nE logo nada? Terei eu o pensamento\nDe pensar nisto, e me faltará o pensamento\nDe que tal coisa, ocorrendo, me faria triste?\nMas não me digais; sei que Antônio\nEstá triste de pensar em suas mercadorias.","antoniobelievemenoithankmyfortuneforitmy~merchandisemakesmenotsad":"Antônio — Crede-me, não: agradeço à minha sorte,\nMinhas empresas não estão confiadas a um só casco,\nNem a um só lugar; nem toda a minha fortuna\nDepende da sorte do presente ano:\nPortanto minhas mercadorias não me fazem triste.","salarinowhythenyouareinlove~arinowhythenyouareinlove":"Salarino — Ora, então estais apaixonado.","antoniofiefie~antoniofiefie":"Antônio — Ora, ora!","salarinonotinloveneitherthenletussayyoua~rswearthejestbelaughable":"Salarino — Nem apaixonado? Então digamos que estais triste\nPorque não estais alegre: e seria tão fácil\nPara vós rir, saltar e dizer que estais alegre\nPorque não estais triste. Por Jano de duas cabeças,\nA natureza criou estranhos sujeitos em seu tempo:\nUns que sempre espiarão pelos olhos semicerrados\nE rirão como papagaios de um gaiteiro,\nE outros de aspecto tão avinagrado\nQue não mostrarão os dentes em sorriso,\nAinda que Nestor jure ser a graça risível.","enterbassaniolorenzoandgratiano~ssaniolorenzoandgratiano":"Entram Bassânio, Lourenço e Graciano.","salanioherecomesbassanioyourmostnoblekin~eyounowwithbettercompany":"Salânio — Aí vem Bassânio, vosso nobilíssimo parente,\nGraciano e Lourenço. Ficai bem:\nDeixamo-vos agora com melhor companhia.","salarinoiwouldhavestaydtillihadmadeyoume~friendshadnotpreventedme":"Salarino — Teria ficado até vos fazer alegre,\nSe amigos mais dignos não me tivessem antecipado.","antonioyourworthisverydearinmyregarditak~bracetheoccasiontodepart":"Antônio — Vosso valor me é muito caro.\nPenso que vossos próprios negócios vos chamam\nE aproveitais a ocasião para partir.","salarinogoodmorrowmygoodlords~inogoodmorrowmygoodlords":"Salarino — Bom dia, meus bons senhores.","bassaniogoodsigniorsbothwhenshallwelaugh~ceedingstrangemustitbeso":"Bassânio — Bons senhores ambos, quando riremos? dizei, quando?\nTornais-vos excessivamente esquivos: deve ser assim?","salarinowellmakeourleisurestoattendonyou~exeuntsalarinoandsalanio":"Salarino — Faremos que nossos lazeres sirvam aos vossos. Saem Salarino e Salânio.","lorenzomylordbassaniosinceyouhavefoundan~aveinmindwherewemustmeet":"Lourenço — Milorde Bassânio, já que encontrastes Antônio,\nNós dois vos deixaremos: mas na hora do jantar,\nRogo-vos, lembrai onde devemos nos encontrar.","bassanioiwillnotfailyou~bassanioiwillnotfailyou":"Bassânio — Não vos faltarei.","gratianoyoulooknotwellsigniorantonioyouh~ouaremarvellouslychanged":"Graciano — Não pareceis bem, Senhor Antônio;\nDais importância demais ao mundo:\nPerdem-no os que o compram com muito cuidado:\nCrede-me, estais maravilhosamente mudado."}$tr$::jsonb, 21)
on conflict (texto_slug, idioma) do update set cobertura = excluded.cobertura, credito = excluded.credito, titulos = excluded.titulos, paragrafos = excluded.paragrafos, total_paragrafos = excluded.total_paragrafos, atualizado_em = now();

-- william-shakespeare_the-taming-of-the-shrew (23 parágrafos, excerpt)
insert into public.livros_traducoes (texto_slug, idioma, cobertura, credito, titulos, paragrafos, total_paragrafos) values ('william-shakespeare_the-taming-of-the-shrew', 'pt', 'trecho', 'Tradução para o português do Brasil feita por IA (Claude) para o Alice''s Library; trecho de abertura, revisão pendente.', $tr${"induction":"Indução"}$tr$::jsonb, $tr${"scenei~scenei":"Cena I","beforeanalehouseonaheath~beforeanalehouseonaheath":"Diante de uma taverna numa charneca.","enterhostessandsly~enterhostessandsly":"Entram a Taverneira e Sly.","slyillpheezeyouinfaith~slyillpheezeyouinfaith":"Sly — Vou te dar uma sova, juro.","hostessapairofstocksyourogue~essapairofstocksyourogue":"Taverneira — Um par de grilhões, seu patife!","slyyeareabaggagetheslysarenorogueslookin~rislettheworldslidesessa":"Sly — Você é uma rameira: os Sly não são patifes; olhe nas crônicas; viemos com Ricardo, o Conquistador. Portanto, paucas pallabris; deixe o mundo rolar: sessa!","hostessyouwillnotpayfortheglassesyouhave~ortheglassesyouhaveburst":"Taverneira — Não vai pagar pelos copos que quebrou?","slynonotadeniergobyjeronimygotothycoldbe~otothycoldbedandwarmthee":"Sly — Não, nem um centavo. Passe de largo, Jerônimo: vá para a sua cama fria e se aqueça.","hostessiknowmyremedyimustgofetchthethird~fetchthethirdboroughexit":"Taverneira — Sei qual é o meu remédio; vou chamar o guarda-mor. Sai.","slythirdorfourthorfifthboroughillanswerh~comeandkindlyfallsasleep":"Sly — Guarda-mor, ou segundo, ou terceiro, responderei a ele conforme a lei: não saio daqui um palmo, rapaz: que venha, e com boas maneiras. Adormece.","hornswindedenteralordfromhuntingwithhist~dfromhuntingwithhistrain":"Soam trompas. Entra um Lorde, voltando da caça, com seu séquito.","lordhuntsmanichargetheetenderwellmyhound~losethedogfortwentypound":"Lorde — Caçador, mando-te tratar bem dos meus cães:\nA cadela Merriman, coitada, está esfalfada;\nE emparelha Clowder com a cadela de voz grave.\nNão viste, rapaz, como Silver acertou a pista\nNo canto da sebe, no rastro mais frio?\nNão perderia esse cão por vinte libras.","firsthuntsmanwhybelmanisasgoodashemylord~eitakehimforthebetterdog":"Primeiro Caçador — Ora, Belman é tão bom quanto ele, senhor;\nLatiu ao achar o rastro na mais completa perda\nE duas vezes hoje descobriu o faro mais fraco:\nCreia-me, tenho-o por melhor cão.","lordthouartafoolifechowereasfleetiwoulde~morrowiintendtohuntagain":"Lorde — És um tolo: se Echo fosse tão veloz,\nEu o julgaria digno de uma dúzia de tais.\nMas dá-lhes bem de comer e cuida de todos:\nAmanhã pretendo caçar de novo.","firsthuntsmaniwillmylord~firsthuntsmaniwillmylord":"Primeiro Caçador — Assim farei, senhor.","lordwhatshereonedeadordrunkseedothhebrea~dordrunkseedothhebreathe":"Lorde — Que é isto? um morto, ou um bêbado? Vede, respira?","secondhuntsmanhebreathesmylordwerehenotw~dbutcoldtosleepsosoundly":"Segundo Caçador — Respira, senhor. Se não estivesse aquecido de cerveja,\nEsta seria uma cama bem fria para dormir tão a fundo.","lordomonstrousbeasthowlikeaswineheliesgr~ebeggarthenforgethimself":"Lorde — Ó monstruosa besta! como jaz feito um porco!\nMorte horrenda, quão vil e repugnante é tua imagem!\nSenhores, vou pregar uma peça a este bêbado.\nQue pensais, se ele fosse levado para a cama,\nEnvolto em roupas perfumadas, anéis postos nos dedos,\nUm banquete deliciosíssimo junto ao leito,\nE bravos criados ao redor quando despertasse,\nNão esqueceria o mendigo de si mesmo?","firsthuntsmanbelievemelordithinkhecannot~lordithinkhecannotchoose":"Primeiro Caçador — Creia-me, senhor, penso que não poderia deixar de esquecer.","secondhuntsmanitwouldseemstrangeuntohimw~trangeuntohimwhenhewaked":"Segundo Caçador — Pareceria estranho a ele quando acordasse.","lordevenasaflatteringdreamorworthlessfan~itbehusbandedwithmodesty":"Lorde — Tal qual um sonho lisonjeiro ou fantasia sem valor.\nEntão levantai-o e conduzi bem a brincadeira:\nCarregai-o com cuidado para o meu mais belo aposento\nE guarnecei-o com todos os meus quadros licenciosos:\nBanhai-lhe a cabeça imunda em águas destiladas mornas\nE queimai lenha perfumada para adocicar o aposento:\nProvidenciai-me música pronta quando despertar,\nPara fazer um som doce e celestial;\nE se por acaso ele falar, estai logo preparados\nE com baixa e submissa reverência\nDizei: “Que ordena vossa honra?”\nQue um o sirva com uma bacia de prata\nCheia de água de rosas e coberta de flores;\nOutro traga o jarro, o terceiro uma toalha,\nE diga: “Apraz a vossa senhoria refrescar as mãos?”\nAlguém esteja pronto com uma roupa custosa\nE lhe pergunte que traje há de vestir;\nOutro lhe fale de seus cães e cavalo,\nE de que sua dama lamenta o seu mal:\nPersuadi-o de que esteve lunático;\nE quando ele disser que está, dizei que sonha,\nPois ele nada é senão um poderoso lorde.\nFazei isso e fazei-o com boa graça, gentis senhores:\nSerá passatempo sobremodo excelente,\nSe for conduzido com discrição.","firsthuntsmanmylordiwarrantyouwewillplay~snolessthanwhatwesayheis":"Primeiro Caçador — Senhor, garanto que faremos o nosso papel,\nDe modo que ele pense, por nossa verdadeira diligência,\nQue não é menos do que dizemos que é.","lordtakehimupgentlyandtobedwithhimandeac~mejourneytoreposehimhere":"Lorde — Levantai-o com suavidade e para a cama com ele;\nE cada um ao seu ofício quando despertar. Alguns levam Sly. Soa uma trombeta.\nMeu rapaz, vai ver que trombeta é essa que soa: Sai um Criado.\nTalvez algum nobre cavalheiro que pretenda,\nem viagem, repousar aqui."}$tr$::jsonb, 23)
on conflict (texto_slug, idioma) do update set cobertura = excluded.cobertura, credito = excluded.credito, titulos = excluded.titulos, paragrafos = excluded.paragrafos, total_paragrafos = excluded.total_paragrafos, atualizado_em = now();

-- william-shakespeare_the-tempest (42 parágrafos, excerpt)
insert into public.livros_traducoes (texto_slug, idioma, cobertura, credito, titulos, paragrafos, total_paragrafos) values ('william-shakespeare_the-tempest', 'pt', 'trecho', 'Tradução para o português do Brasil feita por IA (Claude) para o Alice''s Library; trecho de abertura, revisão pendente.', $tr${"acti":"Ato I"}$tr$::jsonb, $tr${"scenei~scenei":"Cena I","onashipatseaatempestuousnoiseofthunderan~thunderandlightningheard":"Num navio no mar: ouve-se um ruído tempestuoso de trovões e relâmpagos.","enterashipmasterandaboatswain~ashipmasterandaboatswain":"Entram um Mestre do navio e um Contramestre.","masterboatswain~masterboatswain":"Mestre — Contramestre!","boatswainheremasterwhatcheer~swainheremasterwhatcheer":"Contramestre — Aqui, mestre: que ânimo?","mastergoodspeaktothemarinersfalltotyarel~sagroundbestirbestirexit":"Mestre — Bom, fala aos marinheiros: mãos à obra, ligeiro, ou encalhamos: mexei-vos, mexei-vos. Sai.","entermariners~entermariners":"Entram Marinheiros.","boatswainheighmyheartscheerlycheerlymyhe~burstthywindifroomenough":"Contramestre — Eia, meus bravos! Alegria, alegria, meus bravos! Ligeiro, ligeiro! Recolhei o velacho. Atentai ao apito do mestre. Sopra, até estourares o fôlego, se houver mar para isso!","enteralonsosebastianantonioferdinandgonz~erdinandgonzaloandothers":"Entram Alonso, Sebastião, Antônio, Ferdinando, Gonzalo e outros.","alonsogoodboatswainhavecarewheresthemast~heresthemasterplaythemen":"Alonso — Bom contramestre, tende cuidado. Onde está o mestre? Fazei-vos homens.","boatswainipraynowkeepbelow~atswainipraynowkeepbelow":"Contramestre — Rogo-vos agora, ficai lá embaixo.","antoniowhereisthemasterboatswain~hereisthemasterboatswain":"Antônio — Onde está o mestre, contramestre?","boatswaindoyounothearhimyoumarourlabourk~abinsyoudoassistthestorm":"Contramestre — Não o ouvis? Atrapalhais o nosso trabalho: ficai em vossos camarotes: ajudais a tempestade.","gonzalonaygoodbepatient~gonzalonaygoodbepatient":"Gonzalo — Calma, bom homem, tende paciência.","boatswainwhentheseaishencewhatcaresthese~cabinsilencetroubleusnot":"Contramestre — Quando o mar tiver paciência. Fora! Que se importam esses rugidores com o nome de rei? Para o camarote: silêncio! não nos estorveis.","gonzalogoodyetrememberwhomthouhastaboard~memberwhomthouhastaboard":"Gonzalo — Bom homem, lembra-te contudo de quem tens a bordo.","boatswainnonethatimorelovethanmyselfyoua~eartsoutofourwayisayexit":"Contramestre — Ninguém a quem eu ame mais que a mim mesmo. Sois um conselheiro; se podeis mandar a esses elementos que se calem e operar a paz do momento, não puxaremos mais uma corda; usai vossa autoridade: se não podeis, agradecei por haver vivido tanto e preparai-vos em vosso camarote para a desgraça da hora, se assim suceder. Alegria, bons bravos! Fora do nosso caminho, digo. Sai.","gonzaloihavegreatcomfortfromthisfellowme~ourcaseismiserableexeunt":"Gonzalo — Esse sujeito me dá grande conforto: parece-me que não tem sinal de afogamento; sua compleição é perfeita forca. Firme, bom Destino, para o seu enforcamento: faze da corda de seu fado o nosso cabo, pois o nosso pouco adianta. Se ele não nasceu para ser enforcado, nosso caso é miserável. Saem.","reenterboatswain~reenterboatswain":"Reentra o Contramestre.","boatswaindownwiththetopmastyarelowerlowe~hantheweatherorouroffice":"Contramestre — Abaixo o mastro de gávea! ligeiro! mais baixo, mais baixo! Ponde-a à capa com a vela grande. Ouve-se um grito lá dentro. Praga sobre essa gritaria! são mais altos que o temporal e que o nosso ofício.","reentersebastianantonioandgonzalo~bastianantonioandgonzalo":"Reentram Sebastião, Antônio e Gonzalo.","yetagainwhatdoyouhereshallwegiveoeranddr~ddrownhaveyouamindtosink":"De novo! que fazeis aqui? Havemos de desistir e afogar-nos? Tendes vontade de afundar?","sebastianapoxoyourthroatyoubawlingblasph~asphemousincharitabledog":"Sebastião — Peste na tua garganta, cão berrador, blasfemo, sem caridade!","boatswainworkyouthen~boatswainworkyouthen":"Contramestre — Trabalhai vós, então.","antoniohangcurhangyouwhoresoninsolentnoi~idtobedrownedthanthouart":"Antônio — Enforcado, cachorro! enforcado, filho de uma cadela, insolente barulhento! Temos menos medo de nos afogar do que tu.","gonzaloillwarranthimfordrowningthoughthe~leakyasanunstanchedwench":"Gonzalo — Garanto que ele não morre afogado, ainda que o navio não fosse mais forte que uma casca de noz e fizesse tanta água quanto uma moça sem estancamento.","boatswainlayheraholdaholdsethertwocourse~esofftoseaagainlayheroff":"Contramestre — Ponde-a à orça, à orça! largai as duas velas ao mar outra vez; afastai-a!","entermarinerswet~entermarinerswet":"Entram Marinheiros molhados.","marinersalllosttoprayerstoprayersalllost~oprayerstoprayersalllost":"Marinheiros — Tudo perdido! às orações, às orações! tudo perdido!","boatswainwhatmustourmouthsbecold~nwhatmustourmouthsbecold":"Contramestre — Quê, nossas bocas hão de esfriar?","gonzalothekingandprinceatprayersletsassi~themforourcaseisastheirs":"Gonzalo — O rei e o príncipe em orações! ajudemo-los, \n Pois o nosso caso é o deles.","sebastianimoutofpatience~sebastianimoutofpatience":"Sebastião — Perdi a paciência.","antoniowearemerelycheatedofourlivesbydru~ningthewashingoftentides":"Antônio — Somos meramente trapaceados em nossas vidas por bêbados: \n Este rufião de bocarra — quisera que jazesses afogado \n A lavagem de dez marés!","gonzalohellbehangdyetthougheverydropofwa~andgapeatwidesttogluthim":"Gonzalo — Ele ainda será enforcado, \n Ainda que cada gota d’água jure contra isso \n E se abra o mais que possa para o engolir.","aconfusednoisewithinmercyonuswesplitwesp~herwesplitwesplitwesplit":"Ouve-se um ruído confuso lá dentro: “Misericórdia!” \n “Estamos nos partindo, nos partindo!” — “Adeus, minha mulher e meus filhos!” — \n “Adeus, irmão!” — “Estamos nos partindo, nos partindo, nos partindo!”","antonioletsallsinkwiththeking~ioletsallsinkwiththeking":"Antônio — Afundemos todos com o rei.","sebastianletstakeleaveofhimexeuntantonio~xeuntantonioandsebastian":"Sebastião — Vamos despedir-nos dele. Saem Antônio e Sebastião.","gonzalonowwouldigiveathousandfurlongsofs~ldfaindieadrydeathexeunt":"Gonzalo — Agora eu daria mil estádios de mar por um acre de terra estéril, urze comprida, tojo castanho, qualquer coisa. Seja feita a vontade lá de cima! mas eu preferiria morrer de morte seca. Saem.","sceneii~sceneii":"Cena II","theislandbeforeprosperoscell~slandbeforeprosperoscell":"A ilha. Diante da gruta de Próspero.","enterprosperoandmiranda~enterprosperoandmiranda":"Entram Próspero e Miranda.","mirandaifbyyourartmydearestfatheryouhave~fraughtingsoulswithinher":"Miranda — Se por vossa arte, meu querido pai, fizestes \n Estas águas bravias rugirem assim, acalmai-as. \n O céu, parece, derramaria piche fedorento, \n Não fosse o mar, subindo até a face do firmamento, \n Apagar-lhe o fogo. Oh, eu sofri \n Com aqueles que vi sofrer: um nobre navio, \n Que trazia, sem dúvida, alguma nobre criatura, \n Feito em pedaços. Oh, o grito bateu \n Contra o meu próprio coração. Pobres almas, pereceram. \n Se eu fosse algum deus de poder, teria \n Afundado o mar dentro da terra antes que \n Ele engolisse assim o bom navio e \n As almas que o carregavam."}$tr$::jsonb, 42)
on conflict (texto_slug, idioma) do update set cobertura = excluded.cobertura, credito = excluded.credito, titulos = excluded.titulos, paragrafos = excluded.paragrafos, total_paragrafos = excluded.total_paragrafos, atualizado_em = now();

-- william-shakespeare_twelfth-night (31 parágrafos, excerpt)
insert into public.livros_traducoes (texto_slug, idioma, cobertura, credito, titulos, paragrafos, total_paragrafos) values ('william-shakespeare_twelfth-night', 'pt', 'trecho', 'Tradução para o português do Brasil feita por IA (Claude) para o Alice''s Library; trecho de abertura, revisão pendente.', $tr${"acti":"Ato I"}$tr$::jsonb, $tr${"scenei~scenei":"Cena I","thedukespalace~thedukespalace":"O palácio do Duque.","enterdukecurioandotherlordsmusiciansatte~rlordsmusiciansattending":"Entram o Duque, Cúrio e outros Nobres; Músicos acompanhando.","dukeifmusicbethefoodofloveplayongivemeex~italoneishighfantastical":"Duque — Se a música é o alimento do amor, tocai; \n dai-me dela em excesso, para que, saciado, \n o apetite adoeça e assim morra. \n Aquela melodia outra vez! Tinha uma queda agonizante: \n oh, chegou-me ao ouvido como o doce som \n que sopra sobre um talude de violetas, \n roubando e dando perfume! Basta; não mais: \n já não é tão doce como era antes. \n Ó espírito do amor! Como és vivo e fresco, \n pois, não obstante tua capacidade \n receber como o mar, nada ali entra, \n de qualquer valor e quilate que seja, \n que não caia em baixa e em vil preço, \n mesmo em um minuto: tão cheia de formas é a fantasia \n que só ela é altamente fantástica.","curiowillyougohuntmylord~curiowillyougohuntmylord":"Cúrio — Quereis ir à caça, meu senhor?","dukewhatcurio~dukewhatcurio":"Duque — O quê, Cúrio?","curiothehart~curiothehart":"Cúrio — Ao cervo.","dukewhysoidothenoblestthatihaveowhenmine~elhoundseersincepursueme":"Duque — Ora, é o que faço, o mais nobre que tenho: \n oh, quando meus olhos viram Olívia pela primeira vez, \n pareceu-me que ela purgava o ar da pestilência! \n Nesse instante fui transformado em cervo; \n e meus desejos, como cães ferozes e cruéis, \n desde então me perseguem.","entervalentine~entervalentine":"Entra Valentim.","hownowwhatnewsfromher~hownowwhatnewsfromher":"E então! Que notícias dela?","valentinesopleasemylordimightnotbeadmitt~stinginhersadremembrance":"Valentim — Se apraz a meu senhor, não me foi permitido entrar; \n mas de sua criada trago esta resposta: \n que o próprio céu, até o calor de sete anos, \n não verá o rosto dela em plena luz; \n mas, como uma reclusa, ela andará velada \n e regará uma vez por dia o seu quarto em redor \n com salmoura que ofende os olhos: tudo para temperar \n o amor morto de um irmão, que ela quer manter fresco \n e duradouro em sua triste lembrança.","dukeoshethathathaheartofthatfineframetop~canopiedwithbowersexeunt":"Duque — Oh, aquela que tem um coração de tão fina feitura \n que paga esta dívida de amor só a um irmão, \n como amará quando a rica seta de ouro \n tiver matado o rebanho de todos os outros afetos \n que nela vivem; quando fígado, cérebro e coração, \n esses tronos soberanos, estiverem todos providos, e preenchidas \n suas doces perfeições por um só e mesmo rei! \n Adiante, levai-me a doces leitos de flores: \n pensamentos de amor repousam ricos sob dosséis de ramos. Saem.","sceneii~sceneii":"Cena II","theseacoast~theseacoast":"A costa marítima.","enterviolaacaptainandsailors~rviolaacaptainandsailors":"Entram Viola, um Capitão e Marinheiros.","violawhatcountryfriendsisthis~whatcountryfriendsisthis":"Viola — Que país é este, amigos?","captainthisisillyrialady~captainthisisillyrialady":"Capitão — Esta é a Ilíria, senhora.","violaandwhatshouldidoinillyriamybrotherh~rowndwhatthinkyousailors":"Viola — E que hei de fazer na Ilíria? \n Meu irmão está no Elísio. \n Talvez não tenha se afogado: que pensais, marinheiros?","captainitisperchancethatyouyourselfweres~thatyouyourselfweresaved":"Capitão — Foi por acaso que a senhora mesma se salvou.","violaomypoorbrotherandsoperchancemayhebe~herandsoperchancemayhebe":"Viola — Oh, meu pobre irmão! E assim, por acaso, pode ele também ter-se salvo.","captaintruemadamandtocomfortyouwithchanc~hewavessolongasicouldsee":"Capitão — É verdade, senhora: e, para consolá-la com a sorte, \n tenha por certo que, depois que nosso navio se partiu, \n quando a senhora e os poucos salvos com a senhora \n se agarravam ao nosso bote à deriva, vi seu irmão, \n previdentíssimo no perigo, atar-se, \n a coragem e a esperança ensinando-lhe o expediente, \n a um forte mastro que boiava sobre o mar; \n e ali, como Árion no dorso do golfinho, \n vi-o travar convívio com as ondas \n por tanto tempo quanto pude ver.","violaforsayingsotheresgoldmineownescapeu~himknowstthouthiscountry":"Viola — Por dizeres isso, aí tens ouro: \n meu próprio escape abre à minha esperança, \n para a qual a tua fala serve de autoridade, \n o mesmo para ele. Conheces este país?","captainaymadamwellforiwasbredandbornnott~stravelfromthisveryplace":"Capitão — Sim, senhora, bem; pois fui criado e nasci \n a menos de três horas de viagem deste mesmo lugar.","violawhogovernshere~violawhogovernshere":"Viola — Quem governa aqui?","captainanobledukeinnatureasinname~obledukeinnatureasinname":"Capitão — Um nobre duque, em natureza como em nome.","violawhatishisname~violawhatishisname":"Viola — Qual é o nome dele?","captainorsino~captainorsino":"Capitão — Orsino.","violaorsinoihaveheardmyfathernamehimhewa~amehimhewasabachelorthen":"Viola — Orsino! Ouvi meu pai nomeá-lo: \n era então solteiro.","captainandsoisnoworwassoverylateforbutam~dseektheloveoffairolivia":"Capitão — E o é ainda agora, ou o era muito há pouco; \n pois há apenas um mês parti daqui, \n e então corria fresco o murmúrio — pois, bem sabeis, \n o que os grandes fazem os pequenos tagarelam — \n de que ele buscava o amor da bela Olívia.","violawhatsshe~violawhatsshe":"Viola — Quem é ela?","captainavirtuousmaidthedaughterofacountt~dthecompanyandsightofmen":"Capitão — Uma donzela virtuosa, filha de um conde \n que morreu há cerca de um ano, deixando-a \n sob a proteção do filho, seu irmão, \n que também logo morreu: por cujo caro amor, \n dizem, ela abjurou a companhia \n e a vista dos homens."}$tr$::jsonb, 31)
on conflict (texto_slug, idioma) do update set cobertura = excluded.cobertura, credito = excluded.credito, titulos = excluded.titulos, paragrafos = excluded.paragrafos, total_paragrafos = excluded.total_paragrafos, atualizado_em = now();

